TURATH_CHUNK(18,[{"num":3600,"demo":false,"sanad":"","matn":["عَنْ أَبِي رَافِعٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ غَسَّلَ مَيِّتًا فَكَتَمَ عَلَيْهِ غُفِرَ لَهُ أَرْبَعِينَ مَرَّةً، وَمَنْ كَفَّنَ مَيِّتًا كَسَاهُ اللَّهُ مِنَ السُّنْدُسِ، وَإِسْتَبْرَقِ الْجَنَّةِ، وَمَنْ حَفَرَ لِمَيِّتٍ قَبْرًا فَأَجَنَّهُ فِيهِ أُجْرِيَ لَهُ مِنَ الْأَجْرِ كَأَجْرِ مَسْكَنٍ أُسْكِنَهُ إِلَى يَوْمِ الْقِيَامَةِ."],"takhrij":"حسن: رواه الحاكم (1307) عن بكر بن محمد الصيرفي، ثنا عبد الصمد بن الفضل، ثنا عبدالله بن يزيد المقرئ، ثنا سعيد بن أبي أيوب، عن شرحبيل بن شريك المعافري، عن علي بن رباح اللخمي، عن أبي رافع فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الفضيلة في تغسيل الميت وتكفينه وحفر قبره","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ḥākim (1307).","chapter_en":"What is reported concerning the virtue of washing the deceased, shrouding him, and digging his grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abū Rāfiʿ said: The Messenger of Allah ﷺ said: “Whoever washes a deceased person and keeps what he saw private, Allah will forgive him forty times. Whoever shrouds a deceased person, Allah will clothe him with fine silk and brocade of Paradise. And whoever digs a grave for a deceased person and buries him in it, he will be given a reward like the reward of providing him a dwelling until the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (1307)."},{"num":3601,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: مَنْ غَسَّلَ مَيِّتًا، فَسَتَرَهُ، سَتَرَهُ اللهُ مِنَ الذُّنُوبِ، وَمَنْ كَفَّنَهُ كَسَاهُ اللهُ مِنَ السُّنْدُسِ."],"takhrij":"حسن: رواه الطبراني في الكبير (8077) عن أحمد بن سهل بن أيوب الأهوازي، ثنا عبد الملك بن مروان الحذَّاء، ثنا سُليم بن أخضر، ثنا سعير بن الخِمس، عن أبي غالب، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الفضيلة في تغسيل الميت وتكفينه وحفر قبره","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Kabīr (8/337).","chapter_en":"What is reported concerning the virtue of washing the deceased, shrouding him, and digging his grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abū Umāmah reported that the Prophet ﷺ said: “Whoever washes a deceased person and conceals what he saw, Allah will conceal his sins. And whoever shrouds him, Allah will clothe him with fine silk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (8077)."},{"num":3602,"demo":false,"sanad":"","matn":["عن عَائِشَةَ تَقُولُ: لَمَّا أَرَادُوا غَسْلَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا: وَاللَّهِ مَا نَدْرِي أَنُجَرِّدُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ ثِيَابِهِ كَمَا نُجَرِّدُ مَوْتَانَا، أَمْ نُغَسِّلُهُ وَعَلَيْهِ ثِيَابُهُ؟ فَلَمَّا اخْتَلَفُوا أَلْقَى اللَّهُ عَلَيْهِمُ النَّوْمَ حَتَّى مَا مِنْهُمْ رَجُلٌ إِلاَّ وَذَقْنُهُ فِي صَدْرِهِ، ثُمَّ كَلَّمَهُمْ مُكَلِّمٌ مِنْ نَاحِيَةِ الْبَيْتِ لاَ يَدْرُونَ مَنْ هُوَ؟ أَنِ اغْسِلُوا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ ثِيَابُهُ، فَقَامُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَغَسَلُوهُ، وَعَلَيْهِ قَمِيصُهُ يَصُبُّونَ الْمَاءَ فَوْقَ الْقَمِيصِ، وَيُدَلِّكُونَهُ بِالْقَمِيصِ دُونَ أَيْدِيهِمْ، وَكَانَتْ عَائِشَةُ تَقُولُ: لَوِ اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ مَا غَسَّلَهُ إِلاَّ نِسَاؤُهُ."],"takhrij":"حسن: رواه أبو داود (3141)، وابن ماجه (1464) كلاهما من حديث محمد بن إسحاق، حدثني يحيى بن عبَّاد، عن أبيه عباد بن عبدالله بن الزبير، قال: سمعت عائشة فذكرته. واللفظ لأبي داود. وأما ابن ماجه فاقتصر على قول عائشة: لو استقبلت من أمري ... .","grade":"حسن","chapter_ar":"باب ما جاء في صفة غسل النبي ﷺ","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3141), Ibn Mājah (1464), and this is the wording of Abū Dāwūd.","chapter_en":"What is reported about how the Prophet ﷺ was washed","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah said: When they wanted to wash the Prophet ﷺ, they said: “By Allah, we do not know whether we should remove the clothes of the Messenger of Allah ﷺ as we do for our dead, or wash him while his clothes remain on him.” When they disagreed, Allah cast sleep over them, until there was not a man among them except that his chin had dropped to his chest. Then a speaker from one side of the house spoke to them, and they did not know who he was, saying: “Wash the Prophet ﷺ while his clothes are on him.” So they went to the Messenger of Allah ﷺ and washed him while his shirt was on him, pouring water over the shirt and rubbing him through the shirt rather than with their bare hands. ʿĀ’ishah used to say: “If I had known then what I came to know later, no one would have washed him except his wives.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9369],"tks":"حسن: رواه أبو داود (3141)، وابن ماجه (1464)، واللفظ لأبي داود."},{"num":3603,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: رَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْبَقِيعِ، فَوَجَدَنِي، وَأَنَا أَجِدُ صُدَاعًا فِي رَأْسِي، وَأَنَا أَقُولُ: وَارَأْسَاهُ فَقَالَ: بَلْ أَنَا يَا عَائِشَةُ! وَارَأْسَاهُ. ثُمَّ قَالَ: مَا ضَرَّكِ لَوْ مِتِّ قَبْلِي فَقُمْتُ عَلَيْكِ، فَغَسَّلْتُكِ، وَكَفَّنْتُكِ، وَصَلَّيْتُ عَلَيْكِ، وَدَفَنْتُكِ."],"takhrij":"حسن: رواه ابن ماجه (1465)، والنسائي في \"الكبرى\" (7074)، وأحمد (25908)، وابن حبان (6585)، والبيهقي (6659) كلّهم من حديث محمد بن سلمة، عن محمد بن إسحاق، عن يعقوب بن عُتْبة، عن الزهري، عن عبيدالله بن عبدالله، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب غسل أحد الزوجين للآخر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (1465), al-Nasā’ī in al-Kubrā (7074), Aḥmad (25908), Ibn Ḥibbān (6585).","chapter_en":"One spouse washing the other","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿĀ’ishah said: The Messenger of Allah ﷺ returned from al-Baqīʿ and found me suffering from a headache, and I was saying, “Oh, my head!” So he said: “Rather I should be saying, O ʿĀ’ishah, ‘Oh, my head!’” Then he said: “What harm would there be for you if you died before me, and I took care of you, washed you, shrouded you, prayed over you, and buried you?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1465)، والنسائي في الكبرى (7074)، وأحمد (25908)، وابن حبان (6585)."},{"num":3604,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْيَوْمِ الَّذِي بُدِئَ فِيهِ، فَقُلْتُ: وَارَأْسَاهْ، فَقَالَ: وَدِدْتُ أَنَّ ذَلِكَ كَانَ وَأَنَا حَيٌّ، فَهَيَّأْتُكِ وَدَفَنْتُكِ قَالَتْ: فَقُلْتُ غَيْرَى: كَأَنِّي بِكَ فِي ذَلِكَ الْيَوْمِ عَرُوسًا بِبَعْضِ نِسَائِكَ. قَالَ: وَأَنَا وَارَأْسَاهْ، ادْعُوا لِي أَبَاكِ وَأَخَاكِ حَتَّى أَكْتُبَ لِأَبِي بَكْرٍ كِتَابًا، فَإِنِّي أَخَافُ أَنْ يَقُولَ قَائِلٌ، وَيَتَمَنَّى مُتَمَنٍّ: أَنَا أَوْلَى، وَيَأْبَى الله عَزَّ وَجَلَّ وَالْمُؤْمِنُونَ إِلَّا أَبَا بَكْرٍ."],"takhrij":"صحيح: رواه الإمام أحمد (25113)، والبيهقي (16588) كلاهما من حديث يزيد بن هارون، أخبرنا إبراهيم بن سعد، عن صالح بن كيسان، عن الزهري، عن عروة، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب غسل أحد الزوجين للآخر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Aḥmad (25113), al-Bayhaqī (8/153). It is also in Muslim (2387) in shortened form regarding the appointment of Abū Bakr.","chapter_en":"One spouse washing the other","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿĀ’ishah said: The Messenger of Allah ﷺ entered upon me on the first day of his illness, and I said: “Oh, my head!” He said: “I would have liked for that to happen while I was still alive, so that I could prepare you and bury you.” She said: So I replied jealously: “It is as if I can see you that day as a bridegroom with one of your wives.” He said: “And I am saying, ‘Oh, my head!’ Call your father and your brother for me so that I may write something appointing Abū Bakr, for I fear that someone may speak and someone may wishfully hope, saying: ‘I am more entitled,’ while Allah, Mighty and Majestic, and the believers refuse anyone but Abū Bakr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (25113)، والبيهقي (16588)، وهو في مسلم (2387) مختصرا في ذكر استخلاف أبي بكر."},{"num":3605,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ الأَنْصَارِيَّةِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ تُوُفِّيَتِ ابْنَتُهُ، فَقَالَ: اغْسِلْنَهَا ثَلاَثًا، أَوْ خَمْسًا أَوْ أَكْثَرَ مَنْ ذَلِكَ. إِنْ رَأَيْتُنَّ ذَلِكَ بِمَاءٍ وَسِدْرٍ، وَاجْعَلْنَ فِي الآخِرَةِ كَافُورًا، أَوْ شَيْئًا مِنْ كَافُورٍ، فَإِذَا فَرَغْتُنَّ فَآذِنَّنِي. فَلَمَّا فَرَغْنَا آذَنَّاهُ، فَأَعْطَانَا حِقْوَهُ، فَقَالَ: أَشْعِرْنَهَا إِيَّاهُ. تَعْنِي إِزَارَهُ."],"takhrij":"متفق عليه: رواه مالك في الجنائز (2) عن أيوب بن أبي تميمة السختياني، عن محمد بن سيرين، عن أم عطية الأنصارية فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب غسل الميت وتراً","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (2), al-Bukhārī (1253), Muslim (939/38).","chapter_en":"Washing the deceased an odd number of times","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Umm ʿAṭiyyah al-Anṣāriyyah said: The Messenger of Allah ﷺ came to us when his daughter died and said: “Wash her three times, or five times, or more than that if you think it necessary, with water and lotus leaves, and put camphor — or some camphor — in the final wash. Then when you are finished, inform me.” She said: When we finished, we informed him, and he gave us his waist-wrapper and said: “Wrap her in this next to her body.” By his waist-wrapper, she meant his lower garment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2)، والبخاري (1253)، ومسلم (939/38)."},{"num":3606,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَسْلِ ابْنَتِهِ: ابْدَأْنَ بِمَيَامِنِهَا، وَمَوَاضِعِ الْوُضُوءِ مِنْهَا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1255)، ومسلم في الجنائز (939/43) كلاهما من حديث إسماعيل بن إبراهيم، حدثنا خالد الحذاء، عن حفصة بنت سيرين، عن أم عطية فذكرته.","grade":"متفق عليه","chapter_ar":"باب يبدأ بميامن الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1255), Muslim (939/43).","chapter_en":"Beginning with the right side of the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Umm ʿAṭiyyah said: The Messenger of Allah ﷺ said regarding the washing of his daughter: “Begin with her right side and the parts of her body used for ablution.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1255)، ومسلم (939/43)."},{"num":3607,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: ضَفَرْنَا شَعَرَ بِنْتِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. تَعْنِي ثَلاَثَةَ قُرُونٍ. وَقَالَ وَكِيعٌ: قَالَ سُفْيَانُ: نَاصِيَتَهَا وَقَرْنَيْهَا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1262) عن قبيصة، حدثنا سفيان، عن هشام، عن أم الهُذيل (حفصة بنت سيرين) عن أم عطية فذكرته.","grade":"متفق عليه","chapter_ar":"باب جعل شعر المرأة ثلاثة قرون","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1262), Muslim (939/41). In another wording: We divided her hair into three parts: the two side sections and the forelock.","chapter_en":"Making a woman’s hair into three braids","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Umm ʿAṭiyyah said: We braided the hair of the daughter of the Prophet ﷺ — meaning three braids. Wakīʿ said: Sufyān said: Her forelock and her two side sections."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1262)، ومسلم (939/41). وفيه: قالت: فضفرنا شعرها ثلاثة أثلاث، قرنيها وناصيتها."},{"num":3608,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ قَالَتِ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : اغْسِلْنَهَا وِتْرًا ثَلَاثًا أَوْ خَمْسًا أَوْ سَبْعًا وَقَالَتْ: مَشَطْنَاهَا ثَلَاثَةَ قُرُونٍ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1254)، ومسلم في الجنائز (939) كلاهما من حديث أيوب، عن حفصة، عن أم عطية فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مشط شعر المرأة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1254), Muslim (939).","chapter_en":"What is reported about combing a woman’s hair","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Umm ʿAṭiyyah said: The Prophet ﷺ said: “Wash her an odd number of times: three, or five, or seven.” And she said: We combed her hair into three braids."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1254)، ومسلم (939)."},{"num":3609,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: تُوُفِّيَتْ إِحْدَى بَنَاتِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَانَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: اغْسِلْنَهَا بِالسِّدْرِ وِتْرًا ثَلاَثًا أَوْ خَمْسًا، أَوْ أَكْثَرَ مِنْ ذَلِكَ إِنْ رَأَيْتُنَّ ذَلِكَ، وَاجْعَلْنَ فِي الآخِرَةِ كَافُورًا، أَوْ شَيْئًا مِنْ كَافُورٍ، فَإِذَا فَرَغْتُنَّ فَآذِنَّنِي. فَلَمَّا فَرَغْنَا آذَنَّاهُ، فَأَلْقَى إِلَيْنَا حِقْوَهُ، فَضَفَرْنَا شَعَرَهَا ثَلاَثَةَ قُرُونٍ، وَأَلْقَيْنَاهَا خَلْفَهَا."],"takhrij":"صحيح: رواه البخاري في الجنائز (1263) عن مسدد، حدثنا يحيى بن سعيد، عن هشام بن حسان، قال: حدثنا حفصة، عن أم عطية فذكرته.","grade":"صحيح","chapter_ar":"باب إلقاء شعر المرأة خلفها","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1263).","chapter_en":"Placing a woman’s hair behind her","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Umm ʿAṭiyyah said: One of the daughters of the Prophet ﷺ died, and the Prophet ﷺ came to us and said: “Wash her with lotus leaves an odd number of times: three or five, or more than that if you think it necessary, and put camphor — or some camphor — in the final wash. Then when you are finished, inform me.” When we finished, we informed him, and he threw his waist-wrapper to us. Then we braided her hair into three braids and placed them behind her."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1263)."},{"num":3610,"demo":false,"sanad":"","matn":["عن ابْنِ سِيرِينَ يَقُولُ جَاءَتْ أُمُّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا امْرَأَةٌ مِنَ الأَنْصَارِ مِنَ اللاَّتِي بَايَعْنَ، قَدِمَتِ الْبِصْرَةَ، تُبَادِرُ ابْنًا لَهَا فَلَمْ تُدْرِكْهُ، ـ فَحَدَّثَتْنَا قَالَتْ: دَخَلَ عَلَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَغْسِلُ ابْنَتَهُ فَقَالَ: اغْسِلْنَهَا ثَلاَثًا، أَوْ خَمْسًا، أَوْ أَكْثَرَ مِنْ ذَلِكَ إِنْ رَأَيْتُنَّ ذَلِكَ بِمَاءٍ وَسِدْرٍ، وَاجْعَلْنَ فِي الآخِرَةِ كَافُورًا، فَإِذَا فَرَغْتُنَّ فَآذِنَّنِي. قَالَتْ: فَلَمَّا فَرَغْنَا أَلْقَى إِلَيْنَا حَقْوَهُ، فَقَالَ: أَشْعِرْنَهَا إِيَّاهُ. وَلَمْ يَزِدْ عَلَى ذَلِكَ، وَلاَ أَدْرِي أَىُّ بَنَاتِهِ. وَزَعَمَ أَنَّ الإِشْعَارَ الْفُفْنَهَا فِيهِ، وَكَذَلِكَ كَانَ ابْنُ سِيرِينَ يَأْمُرُ بِالْمَرْأَةِ أَنْ تُشْعَرَ وَلاَ تُؤْزَرَ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1261) عن أحمد، حدثنا عبدالله بن وهب، أخبرنا ابن جريج، أن أيوب أخبره، قال: سمعت ابن سيرين يقول فذكره. وأخرجه مسلم في الجنائز (939/36) من وجه آخر عن أيوب نحوه إلى قوله: أشْعِرْنَها إياه .","grade":"متفق عليه","chapter_ar":"باب كيف الإشعار للميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1261), Muslim (939/36).","chapter_en":"How the inner wrapping is placed on the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":12,"content":{"translation":{"en":["Ibn Sīrīn said: Umm ʿAṭiyyah came — a woman from the Anṣār who had pledged allegiance — and she had come to Basrah, hurrying after one of her sons, but she did not reach him. She narrated to us, saying: The Prophet ﷺ entered upon us while we were washing his daughter and said: “Wash her three times, or five times, or more than that if you think it necessary, with water and lotus leaves, and put camphor in the final wash. Then when you are finished, inform me.” She said: When we finished, he threw his waist-wrapper to us and said: “Place it as the garment closest to her body.” And he did not say more than that. I do not know which of his daughters it was. And it was said that ishʿār means to wrap her in that cloth as the innermost layer. Likewise, Ibn Sīrīn used to instruct that a woman should have an inner garment placed next to her body and not merely be wrapped with an outer waist-cloth."]},"buhuth":{"en":["Ishʿār refers to the cloth that touches the body directly."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1261)، ومسلم (939/36)."},{"num":3611,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُفِّنَ فِي ثَلاَثَةِ أَثْوَابٍ بِيضٍ سَحُولِيَّةٍ، لَيْسَ فِيهَا قَمِيصٌ وَلاَ عِمَامَةٌ."],"takhrij":"متفق عليه: رواه مالك في الجنائز (5) عن هشام بن عروة، عن أبيه، عن عائشة فذكرته. ورواه البخاي في الجنائز (1273) عن إسماعيل، عن مالك به.","grade":"متفق عليه","chapter_ar":"باب كفن النبي في ثلاثة أثواب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (5), al-Bukhārī (1271, 1273), Muslim (941/46).","chapter_en":"The Prophet was shrouded in three garments","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":13,"content":{"translation":{"en":["ʿĀ’ishah said: The Messenger of Allah ﷺ was shrouded in three white Suḥūlī garments. There was no shirt and no turban among them."]},"buhuth":{"en":["In another chain through Hishām from ʿĀ’ishah, she said: The Messenger of Allah ﷺ was first wrapped in a Yemeni cloak that belonged to ʿAbdullāh ibn Abī Bakr, then it was removed from him, and he was shrouded in three Yemeni Suḥūlī garments with no turban and no shirt. Then ʿAbdullāh took the cloak and said: “I will be shrouded in it.” Then he said: “The Messenger of Allah ﷺ was not shrouded in it, so should I be shrouded in it?” Then he gave it away in charity.","Suḥūlī is also narrated as Yemeni Suḥūlī, and in another version: Suḥūlī made of cotton.","Suḥūl is the plural of saḥl, meaning a pure white cloth, and it is only made from cotton.","It is also narrated with a fatḥah as a relation to Saḥūl, a village in Yemen.","Al-Azharī said: with fatḥah it refers to the place; with ḍammah it refers to the garments.","This was also narrated by Abū Dāwūd (3152), al-Tirmidhī (996), al-Nasā’ī (1899), and Ibn Mājah (1469). In that wording, people mentioned to ʿĀ’ishah their statement that he was shrouded in two cloths and a striped cloak, and she replied: They did bring a striped cloak, but they returned it and did not shroud him in it.","A striped cloak means a patterned garment."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9371],"tks":"متفق عليه: رواه مالك (5)، والبخاري (1271، 1273)، ومسلم (941/46)."},{"num":3612,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلْتُ عَلَى أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: فِي كَمْ كَفَّنْتُمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: فِي ثَلاَثَةِ أَثْوَابٍ بِيضٍ سَحُولِيَّةٍ، لَيْسَ فِيهَا قَمِيصٌ وَلاَ عِمَامَةٌ. وَقَالَ لَهَا: فِي أَىِّ يَوْمٍ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: يَوْمَ الاِثْنَيْنِ. قَالَ: فَأَىُّ يَوْمٍ هَذَا؟ قَالَتْ: يَوْمُ الاِثْنَيْنِ. قَالَ: أَرْجُو فِيمَا بَيْنِي وَبَيْنَ اللَّيْلِ. فَنَظَرَ إِلَى ثَوْبٍ عَلَيْهِ كَانَ يُمَرَّضُ فِيهِ، بِهِ رَدْعٌ مِنْ زَعْفَرَانٍ فَقَالَ: اغْسِلُوا ثَوْبِي هَذَا، وَزِيدُوا عَلَيْهِ ثَوْبَيْنِ فَكَفِّنُونِي فِيهَا. قُلْتُ: إِنَّ هَذَا خَلَقٌ. قَالَ: إِنَّ الْحَىَّ أَحَقُّ بِالْجَدِيدِ مِنَ الْمَيِّتِ، إِنَّمَا هُوَ لِلْمُهْلَةِ. فَلَمْ يُتَوَفَّ حَتَّى أَمْسَى مِنْ لَيْلَةِ الثُّلاَثَاءِ وَدُفِنَ، قَبْلَ أَنْ يُصْبِحَ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1387) عن معلى بن أسد، حدثنا وُهيب، عن هشام، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب كفن النبي في ثلاثة أثواب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1387).","chapter_en":"The Prophet was shrouded in three garments","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":13,"content":{"translation":{"en":["ʿĀ’ishah said: I entered upon Abū Bakr and he asked: “In how many cloths did you shroud the Prophet ﷺ?” She said: “In three white Suḥūlī garments, with no shirt and no turban among them.” Then he asked her: “On which day did the Messenger of Allah ﷺ die?” She said: “On Monday.” He said: “And what day is today?” She said: “Monday.” He said: “I hope that what remains for me is until tonight.” Then he looked at a garment he had been wearing while ill, and it had traces of saffron on it, and he said: “Wash this garment of mine, and add two more garments to it, then shroud me in them.” I said: “This one is worn out.” He said: “The living has more right to new clothing than the dead. It is only for the body’s decay.” Then he did not pass away until the evening of Tuesday night, and he was buried before morning."]},"buhuth":{"en":["The phrase “for the body’s decay” was explained in different ways. ʿIyāḍ said it was narrated with ḍammah, fatḥah, and kasrah on the mīm. Ibn Ḥabīb said: with kasrah it means discharge from the body, with fatḥah it means delay, and with ḍammah it means the dregs of oil. The intended meaning here is bodily decay and discharge."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9372],"tks":"صحيح: رواه البخاري (1387)."},{"num":3613,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ قَالَ: كُفِّن رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ثَلاَثِ رباطٍ بيضٍ سَحُولِيَّةٍ."],"takhrij":"حسن: رواه ابن ماجه (1470) عن محمد بن خلفٍ العسقلاني قال: حدثنا عمرو بن أبي سلمة، قال: هذا ما سمعتُ من أبي مُعَيد حفص بن غيلان، عن سليمان بن موسى، عن نافع، عن عبدالله بن عمر فذكر الحديث.","grade":"حسن","chapter_ar":"باب كفن النبي في ثلاثة أثواب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (1470).","chapter_en":"The Prophet was shrouded in three garments","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: The Messenger of Allah ﷺ was shrouded in three white Suḥūlī wrap-cloths."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9373],"tks":"حسن: رواه ابن ماجه (1470)."},{"num":3614,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَفَّنَ حَمْزَةَ بْنَ عَبْدِ الْمُطَّلِبِ فِي نَمِرَةٍ فِي ثَوْبٍ وَاحِدٍ."],"takhrij":"حسن: رواه الترمذي (997) عن ابن أبي عمر، حدثنا بشر بن السري، عن زائدة، عن عبدالله بن محمد بن عقيل، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تكفين حمزة بن عبد المطلب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Tirmidhī (997), Aḥmad (14521).","chapter_en":"What is reported about shrouding Ḥamzah ibn ʿAbd al-Muṭṭalib","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Jābir reported that the Messenger of Allah ﷺ shrouded Ḥamzah ibn ʿAbd al-Muṭṭalib in a striped woolen wrap, in a single garment."]},"buhuth":{"en":["A namirah is a wrap with black and white stripes, or a woolen cloak worn by desert Arabs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (997)، والإمام أحمد (14521)."},{"num":3615,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ، قَالَ: أَخْبَرَنِي أَبِي الزُّبَيْرُ: أَنَّهُ لَمَّا كَانَ يَوْمُ أُحُدٍ أَقْبَلَتِ امْرَأَةٌ تَسْعَى، حَتَّى إِذَا كَادَتْ أَنْ تُشْرِفَ عَلَى الْقَتْلَى، قَالَ: فَكَرِهَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَرَاهُمْ. فَقَالَ: الْمَرْأَةَ الْمَرْأَةَ. قَالَ الزُّبَيْرُ: فَتَوَسَّمْتُ أَنَّهَا أُمِّي صَفِيَّةُ، قَالَ: فَخَرَجْتُ أَسْعَى إِلَيْهَا، فَأَدْرَكْتُهَا قَبْلَ أَنْ تَنْتَهِيَ إِلَى الْقَتْلَى، قَالَ: فَلَدَمَتْ فِي صَدْرِي، وَكَانَتِ امْرَأَةً جَلْدَةً، قَالَتْ: إِلَيْكَ، لَا أَرْضَ لَكَ، قَالَ: فَقُلْتُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَزَمَ عَلَيْكِ. قَالَ: فَوَقَفَتْ، وَأَخْرَجَتْ ثَوْبَيْنِ مَعَهَا، فَقَالَتْ: هَذَانِ ثَوْبَانِ جِئْتُ بِهِمَا لِأَخِي حَمْزَةَ، فَقَدْ بَلَغَنِي مَقْتَلُهُ، فَكَفِّنُوهُ فِيهِمَا، قَالَ: فَجِئْنَا بِالثَّوْبَيْنِ لِنُكَفِّنَ فِيهِمَا حَمْزَةَ، فَإِذَا إِلَى جَنْبِهِ رَجُلٌ مِنَ الْأَنْصَارِ قَتِيلٌ، قَدْ فُعِلَ بِهِ كَمَا فُعِلَ بِحَمْزَةَ، قَالَ: فَوَجَدْنَا غَضَاضَةً وَحَيَاءً أَنْ نُكَفِّنَ حَمْزَةَ فِي ثَوْبَيْنِ، وَالْأَنْصَارِيُّ لَا كَفَنَ لَهُ، فَقُلْنَا: لِحَمْزَةَ ثَوْبٌ، وَلِلِأَنْصَارِيِّ ثَوْبٌ، فَقَدَرْنَاهُمَا فَكَانَ أَحَدُهُمَا أَكْبَرَ مِنَ الآخَرِ، فَأَقْرَعْنَا بَيْنَهُمَا، فَكَفَّنَّا كُلَّ وَاحِدٍ مِنْهُمَا فِي الثَّوْبِ الَّذِي طَارَ لَهُ."],"takhrij":"حسن: رواه الإمام أحمد (1418)، والبزار (980)، وأبو يعلى (686)، كلهم من طريق سليمان بن داود الهاشمي، أخبرنا عبدالرحمن- يعني ابن أبي الزياد، عن هاشم، عن عروة، عن أبيه الزبير، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تكفين حمزة بن عبد المطلب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (1418), al-Bazzār (980), Abū Yaʿlā (686).","chapter_en":"What is reported about shrouding Ḥamzah ibn ʿAbd al-Muṭṭalib","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["ʿUrwah said: My father al-Zubayr told me that on the day of Uḥud, a woman came hurrying. When she was about to overlook the slain, the Prophet ﷺ disliked that she should see them, so he said: “The woman, the woman.” Al-Zubayr said: I realized it was my mother, Ṣafiyyah. So I hurried out toward her and reached her before she got to the slain. He said: She struck my chest, and she was a strong woman. She said: “Step aside. May you have no standing with me.” He said: I told her: “The Messenger of Allah ﷺ has firmly instructed you not to go.” So she stopped, and she took out two garments she had with her and said: “These are two garments I brought for my brother Ḥamzah, for news has reached me that he has been killed. So shroud him in them.” He said: We brought the two garments to shroud Ḥamzah in them, but beside him was a slain man from the Anṣār who had been mutilated just as Ḥamzah had been mutilated. He said: We felt ashamed and uneasy to shroud Ḥamzah in two garments while the Anṣārī had no shroud. So we said: One garment for Ḥamzah and one garment for the Anṣārī. We measured the two garments and found that one was larger than the other, so we drew lots between them, and we shrouded each of them in the garment that fell to him."]},"buhuth":{"en":["The phrase “ladamat” means she struck and pushed against my chest."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (1418)، والبزار (980)، وأبو يعلى (686)."},{"num":3616,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا تُوُفِّيَ أَحَدُكُمْ فَوَجَدَ شَيْئًا فَلْيُكَفَّنْ فِي ثَوْبٍ حِبَرَةٍ."],"takhrij":"حسن: رواه أبو داود (3150) عن الحسن بن الصباح البزار، حدثنا إسماعيل - يعني ابن عبد الكريم - حدثني إبراهيم بن عقيل بن معقل، عن أبيه، عن وهب بن منبه، عن جابر قال: فذكره.","grade":"حسن","chapter_ar":"باب يُستحب أن يكون أحد ثوبيه حِبرة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3150).","chapter_en":"It is recommended that one of the shroud cloths be striped","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Jābir said: I heard the Messenger of Allah ﷺ say: “When one of you dies, if he has the means, let him be shrouded in a striped cloth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3150)."},{"num":3617,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ قَالَتْ: دَخَلَ عَلَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَغْسِلُ ابْنَتَهُ... فَلَمَّا فَرَغْنَا آذَنَّاهُ، فَأَلْقَى إِلَيْنَا حَقْوَهُ، فَقَالَ: أَشْعِرْنَهَا إِيَّاهُ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1261)، ومسلم في الجنائز (929: 36) كلاهما من حديث أيوب، عن ابن سيرين، عن أم عطية فذكرته في كيفية غسل النبي صلى الله عليه وسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كفن المرأة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1261), Muslim (939/36).","chapter_en":"What is reported about the shroud of a woman","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["Umm ʿAṭiyyah said: The Prophet ﷺ entered upon us while we were washing his daughter. When we had finished, he threw his waist-wrapper to us and said: “Place it as the garment closest to her body.”"]},"buhuth":{"en":["His waist-wrapper means his lower garment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1261)، ومسلم (939/36).","voc":["muslim",2111]},{"num":3618,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: كَانَ رَجُلٌ وَاقِفٌ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَرَفَةَ، فَوَقَعَ عَنْ رَاحِلَتِهِ.","قَالَ أَيُّوبُ: فَوَقَصَتْهُ، وَقَالَ عَمْرٌو: فَأَقْصَعَتْهُ -ـ- فَمَاتَ، فَقَالَ النبي صلى الله عليه وسلم: اغْسِلُوهُ بِمَاءٍ وَسِدْرٍ، وَكَفِّنُوهُ فِي ثَوْبَيْنِ، وَلاَ تُحَنِّطُوهُ، وَلاَ تُخَمِّرُوا رَأْسَهُ، فَإِنَّهُ يُبْعَثُ يَوْمَ الْقِيَامَةِ .ـ.","قال أيوب: يُلَبِّي، وقال عمرو: ملبياً."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1268)، ومسلم في الجنائز (1206) كلاهما من حديث حماد بن زيد، عن عمرو بن دينار وأيوب، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب في تكفين المحرم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1268), Muslim (1206), with al-Bukhārī’s wording.","chapter_en":"Regarding shrouding a person in the state of ihram","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":17,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: A man was standing with the Prophet ﷺ at ʿArafah, and he fell from his mount. Ayyūb said: It broke his neck. ʿAmr said: It killed him instantly. So he died.","Then the Prophet ﷺ said: “Wash him with water and lotus leaves, and shroud him in two cloths. Do not apply funeral perfume to him, and do not cover his head, for he will be raised on the Day of Resurrection” — Ayyūb said: “saying the talbiyah,” and ʿAmr said: “while saying the talbiyah.”"]},"buhuth":{"en":["The phrase “in two cloths” means in his own two garments, and those two garments were the ihram garments in which he had entered ihram.","“Do not apply funeral perfume to him” means do not place ḥanūṭ on him. Ḥanūṭ is a mixture of perfume prepared especially for the deceased and not used otherwise.","“Do not cover his head” means do not place a covering over it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1268)، ومسلم (1206)، واللفظ للبخاري."},{"num":3619,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ قَالَ: أَتَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قبر عبدالله بْنَ أبيّ بَعْدَ مَا دُفن، فَأَخْرَجَهُ فَنَفَثَ فِيهِ مِنْ رِيقِهِ، وَأَلْبَسَهُ قَمِيصَهُ.","وفي رواية: فوضعه على ركبتيه."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1270)، ومسلم في صفات المنافقين (2773) كلاهما من حديث سفيان بن عيينة، عن عمرو (هو ابن دينار) سمع جابر بن عبدالله يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب تكفين عبد الله بن أُبيٍّ في قميص رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1270), Muslim (2773).","chapter_en":"Shrouding ʿAbdullāh ibn Ubayy in the shirt of the Messenger of Allah ﷺ","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Prophet ﷺ came to the grave of ʿAbdullāh ibn Ubayy after he had been buried. He had him brought out, blew some of his blessed saliva onto him, and clothed him in his own shirt. In another narration: He placed him on his knees."]},"buhuth":{"en":["The phrase “after he had been buried” means after he had already been lowered into his grave. The family of ʿAbdullāh ibn Ubayy feared that attending would be difficult for the Prophet ﷺ, so they hurried to prepare him before the Prophet ﷺ arrived. When he arrived, he found that they had already lowered him into the grave, so he ordered that he be brought out in fulfillment of his promise to provide the shirt and pray over him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1270)، ومسلم (2773)."},{"num":3620,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّ عبدالله بْنَ أبيّ لَمَّا تُوُفِّيَ جَاءَ ابْنُهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! أَعْطِنِي قَمِيصَكَ أُكفِّنه فِيهِ، وصلِّ عَلَيْهِ، وَاسْتَغْفِرْ لَهُ، فَأَعْطَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَمِيصَهُ فَقَالَ: آذِنِّي أُصَلِّي عَلَيْهِ . فَآذَنَهُ: فَلَمَّا أَرَادَ أَنْ يُصَلِّيَ عَلَيْهِ جَذَبَهُ عُمَرُ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: أَلَيْسَ اللَّهُ قَدْ نَهَاكَ أَنْ تُصَلِّيَ عَلَى الْمُنَافِقِينَ؟ فَقَالَ: أَنَا بَيْنَ خِيرَتَيْنِ قَالَ: ﴿اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ﴾ [سورة التَّوْبَةِ:80] فَصَلَّى عَلَيْهِ، فَنَزَلَتْ: ﴿وَلَا تُصَلِّ عَلَى أَحَدٍ مِنْهُمْ مَاتَ أَبَدًا﴾ [سورة التَّوْبَةِ:84]."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1269)، ومسلم في صفات المنافقين (2774) كلاهما من حديث يحيى بن سعيد، عن عبيدالله بن عمر، عن نافع، عن ابن عمر فذكره. قال مسلم: وزاد: فترك الصلاة عليهم.","grade":"متفق عليه","chapter_ar":"باب تكفين عبد الله بن أُبيٍّ في قميص رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1269), Muslim (2774). Muslim adds: So he stopped praying over them.","chapter_en":"Shrouding ʿAbdullāh ibn Ubayy in the shirt of the Messenger of Allah ﷺ","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar reported that when ʿAbdullāh ibn Ubayy died, his son came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, give me your shirt so that I may shroud him in it, pray over him, and seek forgiveness for him.” So the Prophet ﷺ gave him his shirt and said: “Inform me so that I may pray over him.” So he informed him. When he intended to pray over him, ʿUmar pulled him and said: “Has Allah not forbidden you from praying over the hypocrites?” He said: “I have been given a choice between two matters.” Then he recited: “Ask forgiveness for them, or do not ask forgiveness for them. Even if you ask forgiveness for them seventy times, Allah will never forgive them.” [9:80] So he prayed over him, and then the verse was revealed: “And never pray over any of them who dies.” [9:84]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1269)، ومسلم (2774). قال مسلم: وزاد: فترك الصلاة عليهم."},{"num":3621,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ، قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُ عَبْدَ اللَّهِ بْنَ أُبَىٍّ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ، فَلَمَّا دَخَلَ عَلَيْهِ عَرَفَ فِيهِ الْمَوْتَ قَالَ: قَدْ كُنْتُ أَنْهَاكَ عَنْ حُبِّ يَهُودَ. قَالَ: فَقَدْ أَبْغَضَهُمْ أَسْعَدُ بْنُ زُرَارَةَ، فَمَهْ فَلَمَّا مَاتَ أَتَاهُ ابْنُهُ فَقَالَ: يَا رَسُولَ اللَّهِ! إِنَّ عَبْدَ اللَّهِ بْنَ أُبَىٍّ قَدْ مَاتَ، فَأَعْطِنِي قَمِيصَكَ أُكَفِّنْهُ فِيهِ. فَنَزَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَمِيصَهُ فَأَعْطَاهُ إِيَّاهُ."],"takhrij":"حسن: رواه أبو داود (3094) عن عبد العزيز بن يحيى، حدثنا محمد بن سلمة، عن محمد بن إسحاق، عن الزهري، عن عروة، عن أسامة بن زيد فذكره.","grade":"حسن","chapter_ar":"باب تكفين عبد الله بن أُبيٍّ في قميص رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3094).","chapter_en":"Shrouding ʿAbdullāh ibn Ubayy in the shirt of the Messenger of Allah ﷺ","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Usāmah ibn Zayd said: The Messenger of Allah ﷺ went out to visit ʿAbdullāh ibn Ubayy during the illness in which he died. When he entered upon him, he recognized the signs of death in him and said: “I had kept warning you against loving the Jews.” He replied: “Asʿad ibn Zurārah hated them, so what did that do for him?” Then when he died, his son came to him and said: “O Messenger of Allah ﷺ, ʿAbdullāh ibn Ubayy has died, so give me your shirt so I may shroud him in it.” So the Messenger of Allah ﷺ removed his shirt and gave it to him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3094)."},{"num":3622,"demo":false,"sanad":"","matn":["عن ابن عباس، أن عبدالله بن أبيّ قال له أبوه: أي بني! اطلب ثوباً من ثياب النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تُكَفِّني فيه، ومره فليصَلِّ عليَّ، قال: فأتاه فقال: يا رسول الله! قد عرفت شرف عبدالله، وهو يطلب إليك ثوباً من ثيابك نُكَفِّنه فيه، وتُصلي عليه، فقال عمر: يا رسول الله! أتصلي عليه، وقد نهاك الله أن تصلي عليه؟ فقال: أين؟ فقال: ﴿اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ﴾ [سورة التوبة:80] قال: فإني سأزيد على سبعين، فأنزل الله: ﴿وَلَا تُصَلِّ عَلَى أَحَدٍ مِنْهُمْ مَاتَ أَبَدًا وَلَا تَقُمْ عَلَى قَبْرِهِ﴾ [سورة التوبة: 84] قال: فأرسل إلى عمر فأخبره بذلك."],"takhrij":"حسن: رواه البيهقي في الدلائل (1772) عن بشر بن السري، حدثنا رباح بن أبي معروف المكي، حدثنا سالم بن عجلان، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب تكفين عبد الله بن أُبيٍّ في قميص رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bayhaqī in al-Dalā’il (5/288).","chapter_en":"Shrouding ʿAbdullāh ibn Ubayy in the shirt of the Messenger of Allah ﷺ","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Ibn ʿAbbās reported that ʿAbdullāh ibn ʿAbdullāh ibn Ubayy said that his father told him: “My son, seek for me one of the garments of the Prophet ﷺ so that I may be shrouded in it, and ask him to pray over me.” So he came to him and said: “O Messenger of Allah ﷺ, you know the standing of ʿAbdullāh, and he asks from you one of your garments so that we may shroud him in it, and that you pray over him.” Then ʿUmar said: “O Messenger of Allah ﷺ, are you going to pray over him, while Allah has forbidden you from praying over him?” He said: “Where?” So ʿUmar recited: “Ask forgiveness for them or do not ask forgiveness for them. Even if you ask forgiveness for them seventy times, Allah will never forgive them.” [9:80] He said: “Then I will ask more than seventy times.” Then Allah revealed: “And never pray over any of them who dies, nor stand at his grave.” [9:84] He said: So he sent word to ʿUmar and informed him of that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي في (( الدلائل )) (5/288)."},{"num":3623,"demo":false,"sanad":"","matn":["عن جابر بْنِ عبدالله يُحَدِّثُ  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ يَوْمًا، فَذَكَرَ رَجُلًا مِنْ أَصْحَابِهِ قُبِضَ، فَكُفِّنَ فِي كَفَنٍ غَيْرِ طَائِلٍ، وَقُبِرَ لَيْلًا، فَزَجَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْبَرَ الرَّجُلُ بِاللَّيْلِ حَتَّى يُصَلَّى عَلَيْهِ، إِلَّا أَنْ يُضْطَرَّ إِنْسَانٌ إِلَى ذَلِكَ، وَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا كَفَّنَ أَحَدُكُمْ أَخَاهُ فَلْيُحَسِّنْ كَفَنَهُ."],"takhrij":"صحيح: رواه مسلم في الجنائز (943) من طرق عن حجاج بن محمد، قال: قال ابن جريج: أخبرني أبو الزبير، أنه سمع جابر بن عبدالله يُحَدِّث أن النبي صلى الله عليه وسلم خطب يوماً فذكر الحديث مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في تحسين كفن الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (943).","chapter_en":"What is reported about making the shroud of the deceased good","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Prophet ﷺ delivered a sermon one day and mentioned a man from his companions who had died and was shrouded in a poor shroud, then buried at night. The Prophet ﷺ strongly discouraged burying a person at night before prayer had been offered over him, unless someone was forced to do so. And the Prophet ﷺ said: “When one of you shrouds his brother, let him make his shroud good.”"]},"buhuth":{"en":["The phrase “a poor shroud” means a weak or insufficient shroud that did not properly cover him.","The scholars understood the Prophet’s discouragement of night burial here to be about that specific man, because the Prophet’s funeral prayer over him had been missed. Otherwise, the majority hold that burying at night is allowed. Abū Bakr was buried at night. Those who disliked night burial did so because fewer people would attend the funeral prayer, since most remain in their homes."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (943)."},{"num":3624,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا وَلِيَ أَحَدُكُمْ أَخَاهُ فَلْيُحَسِّنْ كَفَنَهُ."],"takhrij":"حسن: رواه الترمذي (995)، وابن ماجه (1474) كلاهما عن محمد بن بشار، قال: حدثنا عمر بن يونس، قال: حدثنا عكرمة بن عمار، عن هشام ابن حسان، عن محمد بن سيرين، عن أبي قتادة فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في تحسين كفن الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Tirmidhī (995), who graded it Ḥasan, and Ibn Mājah (1474).","chapter_en":"What is reported about making the shroud of the deceased good","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Abū Qatādah said: The Messenger of Allah ﷺ said: “When one of you takes charge of his brother, let him make his shroud good.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (995) وحسنه، وابن ماجه (1474)."},{"num":3625,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَيْرُ ثِيَابِكُمُ الْبَيَاضُ، فَكَفِّنُوا فِيهَا مَوْتَاكُمْ، وَالْبَسُوهَا."],"takhrij":"حسن: رواه أبو داود (3878)، والترمذي (994)، والنسائي (5113)، وابن ماجه (1472) كلهم من طريق عبدالله بن عثمان بن خُثَيم، عن سعيد بن جبير، عن ابن عباس فذكر الحديث، واللفظ لابن ماجه، وصحَّحه ابن حبان (5423)، والحاكم (1308) وقال: صحيح على شرط مسلم.","grade":"حسن","chapter_ar":"باب ما جاء في بياض الكفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3878), al-Tirmidhī (994), al-Nasā’ī (5113), Ibn Mājah (1472), and this is the wording of Ibn Mājah.","chapter_en":"What is reported about the whiteness of the shroud","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":20,"content":{"translation":{"en":["Ibn ʿAbbās said: The Messenger of Allah ﷺ said: “The best of your garments are the white ones, so shroud your dead in them and wear them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3878)، والترمذي (994)، والنسائي (5113)، وابن ماجه (1472)، واللفظ لابن ماجه."},{"num":3626,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْبَسُوا مِنْ ثِيَابِكُمُ الْبَيَاضَ، فَإِنَّهَا أَطْهَرُ وَأَطْيَبُ، وَكَفِّنُوا فِيهَا مَوْتَاكُمْ."],"takhrij":"صحيح: رواه النسائي (1896) عن عمرو بن علي، قال: حدثنا يحيى ابن سعيد، قال: سمعت سعيد بن أبي عروبة، يحدث عن أيوب، عن أبي قلابة، عن أبي المهلَّب، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في بياض الكفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1896), ʿAbd al-Razzāq in al-Muṣannaf (6198), and Aḥmad (20235).","chapter_en":"What is reported about the whiteness of the shroud","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":20,"content":{"translation":{"en":["Samurah ibn Jundub reported that the Prophet ﷺ said: “Wear white garments, for they are purer and better, and shroud your dead in them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1896)، وعبد الرزاق في المصنف (6198)، والإمام أحمد (20235)."},{"num":3627,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَكَرَ امْرَأَةً مِنْ بَنِي إِسْرَائِيلَ، حَشَتْ خَاتَمَهَا مِسْكًا، وَالْمِسْكُ أَطْيَبُ الطِّيبِ."],"takhrij":"صحيح: رواه مسلم في كتاب الألفاظ في الأدب (2252) من طرق عن أبي نضرة، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب أن المسك أطيب الطيب للحي والميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (2252).","chapter_en":"Musk is the finest perfume for both the living and the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":21,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that the Messenger of Allah ﷺ mentioned a woman from the Children of Israel who had filled her ring with musk, and musk is the finest of perfumes."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2252)."},{"num":3628,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ قَالَتْ: دَخَلَ عَلَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَغَسِلُ ابْنَتَهُ فَقَالَ: وَاجْعَلْنَ فِي الْآخِرَةِ كَافُورًا، أَوْ شَيْئًا مِنْ كَافُورٍ .."],"takhrij":"متفق عليه: رواه مالك في الجنائز (2) عن أيوب بن أبي تميمة السختياني، عن محمد بن سيرين، عن أم عطية الأنصارية فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب إجمار الكفن وتبخيره وتطييبه بالكافور والمسك","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (2), al-Bukhārī (1253), Muslim (939/38).","chapter_en":"Perfuming the shroud with incense, camphor, and musk","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["Umm ʿAṭiyyah said: The Prophet ﷺ entered upon us while we were washing his daughter and said: “Put camphor, or some camphor, in the final wash.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2)، والبخاري (1253)، ومسلم (939/38)."},{"num":3629,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِذَا أَجْمَرْتُمُ الْمَيِّتَ فأجمروا ثَلَاثًا ."],"takhrij":"حسن: رواه الإمام أحمد (14540)، وأبو يعلى (2300) كلاهما من حديث يحيى بن آدم، حدثنا قُطبة بن عبد العزيز، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب إجمار الكفن وتبخيره وتطييبه بالكافور والمسك","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (14540), Abū Yaʿlā (2300), authenticated by Ibn Ḥibbān (3031).","chapter_en":"Perfuming the shroud with incense, camphor, and musk","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Prophet ﷺ said: “When you perfume the deceased with incense, do it three times.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (14540)، وأبو يعلى (2300)، وصححه ابن حبان (3031)."},{"num":3630,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: كَانَ رَجُلٌ وَاقِفٌ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَرَفَةَ فَوَقَعَ عَنْ رَاحِلَتِهِ، قَالَ أَيُّوبُ: فَوَقَصَتْهُ، وَقَالَ عَمْرٌو: فَأَقْصَعَتْهُ فَمَاتَ فَقَالَ: اغْسِلُوهُ بِمَاءٍ وَسِدْرٍ، وَكَفِّنُوهُ فِي ثَوْبَيْنِ، وَلَا تُحَنِّطُوهُ وَلَا تُخَمِّرُوا رَأْسَهُ، فَإِنَّهُ يُبْعَثُ يَوْمَ الْقِيَامَةِ، قَالَ أَيُّوبُ: يُلَبِّي، وَقَالَ عَمْرٌو: مُلَبِّيًا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1268)، ومسلم في الجنائز (1206) كلاهما من حديث حماد بن زيد، عن عمرو بن دينار وأيوب، عن سعيد بن جبير، عن ابن عباس فذكره، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحنيط الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1268), Muslim (1206), and this is the wording of al-Bukhārī.","chapter_en":"What is reported about perfuming the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["Ibn ʿAbbās said: The Messenger of Allah ﷺ said about a man who died at ʿArafah while in ihram: “Wash him with water and lotus leaves, shroud him in two cloths, do not apply funeral perfume to him, and do not cover his head, for Allah will raise him on the Day of Resurrection saying the talbiyah.” In another wording: “while saying the talbiyah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1268)، ومسلم (1206)، واللفظ للبخاري.","voc":["muslim",2845]},{"num":3631,"demo":false,"sanad":"","matn":["عَنْ عُتَيٍّ، قَالَ: رَأَيْتُ شَيْخًا بِالْمَدِينَةِ يَتَكَلَّمُ، فَسَأَلْتُ عَنْهُ، فَقَالُوا: هَذَا أُبَيُّ بْنُ كَعْبٍ، فَقَالَ: إِنَّ آدَمَ عَلَيْهِ السلام لَمَّا حَضَرَهُ الْمَوْتُ قَالَ لِبَنِيهِ: أَيْ بَنِيَّ إِنِّي أَشْتَهِي مِنْ ثِمَارِ الْجَنَّةِ، فَذَهَبُوا يَطْلُبُونَ لَهُ، فَاسْتَقْبَلَتْهُمُ الْمَلَائِكَةُ وَمَعَهُمْ أَكْفَانُهُ وَحَنُوطُهُ، وَمَعَهُمُ الْفُؤُوسُ وَالْمَسَاحِي وَالْمَكَاتِلُ، فَقَالُوا لَهُمْ: يَا بَنِي آدَمَ، مَا تُرِيدُونَ وَمَا تَطْلُبُونَ، أَوْ مَا تُرِيدُونَ وَأَيْنَ تَذْهَبُونَ؟، قَالُوا: أَبُونَا مَرِيضٌ فَاشْتَهَى مِنْ ثِمَارِ الْجَنَّةِ، قَالُوا لَهُمْ: ارْجِعُوا فَقَدْ قُضِيَ قَضَاءُ أَبِيكُمْ. فَجَاءُوا، فَلَمَّا رَأَتْهُمْ حَوَّاءُ عَرَفَتْهُمْ، فَلَاذَتْ بِآدَمَ، فَقَالَ: إِلَيْكِ عَنِّي فَإِنِّي إِنَّمَا أُوتِيتُ مِنْ قِبَلِكِ، خَلِّي بَيْنِي وَبَيْنَ مَلَائِكَةِ رَبِّي تَبَارَكَ وَتَعَالَى. فَقَبَضُوهُ، وَغَسَّلُوهُ وَكَفَّنُوهُ وَحَنَّطُوهُ، وَحَفَرُوا لَهُ وَأَلْحَدُوا لَهُ، وَصَلَّوْا عَلَيْهِ، ثُمَّ دَخَلُوا قَبْرَهُ فَوَضَعُوهُ فِي قَبْرِهِ وَوَضَعُوا عَلَيْهِ اللَّبِنَ، ثُمَّ خَرَجُوا مِنَ الْقَبْرِ، ثُمَّ حَثَوْا عَلَيْهِ التُّرَابَ، ثُمَّ قَالُوا: يَا بَنِي آدَمَ هَذِهِ سُنَّتُكُمْ."],"takhrij":"حسن: رواه عبدالله بن أحمد (21240) عن هدبة بن خالد، حدثنا حماد بن سلمة، عن حُميد، عن الحسن، عن عُتَيٍّ قال فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحنيط الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: ʿAbdullāh ibn Aḥmad (21240).","chapter_en":"What is reported about perfuming the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["ʿUtayy said: I saw an old man in Madinah speaking, so I asked about him and they said: “This is Ubayy ibn Kaʿb.” He said: When death came to Adam, peace be upon him, he said to his sons: “My sons, I long for the fruits of Paradise.” So they went to seek them for him. The angels came to meet them, carrying his shrouds and perfume, and with them were axes, spades, and baskets. They said to them: “O children of Adam, what do you want, and what are you seeking?” or “What do you want, and where are you going?” They said: “Our father is ill and he longed for the fruits of Paradise.” The angels said: “Go back, for the decree concerning your father has now been completed.” So they returned. When Ḥawwā’ saw them, she recognized them and clung to Adam. He said: “Away from me. I was only afflicted because of you. Leave me alone with the angels of my Lord, Blessed and Exalted.” Then they took his soul, washed him, shrouded him, perfumed him, dug his grave, made a niche grave for him, prayed over him, then entered the grave and placed him in it, set the bricks over him, then came out of the grave and threw soil over him. Then they said: “O children of Adam, this is your way.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الله بن أحمد (21240)."},{"num":3632,"demo":false,"sanad":"","matn":["عَنْ أَبِي وَائِلٍ قَالَ: كَانَ عِنْدَ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ مِسْكٌ، فَأَوْصَى أَنْ يُحَنَّطَ بِهِ، قَالَ: وَقَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ: هُوَ فَضْلُ حَنُوطِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه البيهقي (6707) عن أبي عبدالله الحافظ، أنبأ أبو بكر ابن إسحاق، أنبا محمد بن أيوب، أنبا إبراهيم بن موسى، ثنا حميد بن عبدالرحمن الرؤاسي، ثنا الحسن بن صالح، عن هارون بن سعد، عن أبي وائل فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحنيط الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bayhaqī (3/405–406).","chapter_en":"What is reported about perfuming the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["Abū Wā’il said: ʿAlī had some musk, and he instructed that he be perfumed with it after death. ʿAlī said: “It is what remained from the perfume of the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (6707)."},{"num":3633,"demo":false,"sanad":"","matn":["عن حميد قَالَ: لَمَّا تُوُفِّيَ أَنَسُ بْنُ مَالِكٍ جُعِلَ فِي حَنُوطِهِ مِسْكٌ فِيهِ مِنْ عَرَقِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه البيهقي (6709) من طريق ابن أبي مريم، حدثني يحيى بن أيوب، حدثني حُميد فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحنيط الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bayhaqī (3/406).","chapter_en":"What is reported about perfuming the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["Ḥumayd said: When Anas ibn Mālik died, musk that contained some of the sweat of the Messenger of Allah ﷺ was placed in the perfume prepared for his body."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (6709)."},{"num":3634,"demo":false,"sanad":"","matn":["عَنْ خَبَّابِ بْنِ الْأَرَتِّ قَالَ:  هَاجَرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَبِيلِ اللَّهِ، نَبْتَغِي وَجْهَ اللَّهِ، فَوَجَبَ أَجْرُنَا عَلَى اللَّهِ، فَمِنَّا مَنْ مَضَى لَمْ يَأْكُلْ مِنْ أَجْرِهِ شَيْئًا، مِنْهُمْ مُصْعَبُ بْنُ عُمَيْرٍ، قُتِلَ يَوْمَ أُحُدٍ، فَلَمْ يُوجَدْ لَهُ شَيْءٌ يُكَفَّنُ فِيهِ إِلَّا نَمِرَةٌ، فَكُنَّا إِذَا وَضَعْنَاهَا عَلَى رَأْسِهِ خَرَجَتْ رِجْلَاهُ، وَإِذَا وَضَعْنَاهَا عَلَى رِجْلَيْهِ خَرَجَ رَأْسُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ضَعُوهَا مِمَّا يَلِي رَأْسَهُ، وَاجْعَلُوا عَلَى رِجْلَيْهِ الْإِذْخِرَ، وَمِنَّا مَنْ أَيْنَعَتْ لَهُ ثَمَرَتُهُ فَهُوَ يَهْدِبُهَا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1276)، ومسلم في الجنائز (940) كلاهما من طريق الأعمش، عن شقيق، عن خبَّاب بن الأرَثِّ فذكره ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب إذا لم يجد كفنًا إلا ما يُواري رأسه أو قدميه غطَّى رأسه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1276), Muslim (940).","chapter_en":"If only enough shroud is found to cover either the head or the feet, the head is covered","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Khabbāb ibn al-Aratt said: We migrated with the Messenger of Allah ﷺ in the path of Allah, seeking the Face of Allah, so our reward became due from Allah. Among us were some who passed away without having taken anything from their reward in this world. One of them was Muṣʿab ibn ʿUmayr. He was killed on the day of Uḥud, and nothing was found to shroud him in except a striped wrap. When we placed it over his head, his feet became uncovered, and when we placed it over his feet, his head became uncovered. So the Messenger of Allah ﷺ said: “Place it over the part near his head, and put idhkhir grass over his feet.” And among us are some whose fruits ripened fully, and they are now plucking them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8834],"tks":"متفق عليه: رواه البخاري (1276)، ومسلم (940)."},{"num":3635,"demo":false,"sanad":"","matn":["عن سعد بن إبراهيم، عن أبيه إبراهيم قال: أتى عبدالرحمن بن عوف يوماً بطعامه، فقال: قُتل مصعب بن عُمير - وكان خيراً مني- فلم يوجد له ما يُكفَّن فيه إلا بردة، لقد خشيتُ أن يكون قد عُجِّلت لنا طيباتُنا في حياتنا الدنيا، ثم جعل يبكي."],"takhrij":"صحيح: رواه البخاري في الجنائز (1274) عن أحمد بن محمد المكي، حدثنا إبراهيم بن سعد، عن سعد، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب إذا لم يجد كفنًا إلا ما يُواري رأسه أو قدميه غطَّى رأسه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1274).","chapter_en":"If only enough shroud is found to cover either the head or the feet, the head is covered","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Saʿd ibn Ibrāhīm reported from his father Ibrāhīm that one day food was brought to ʿAbd al-Raḥmān ibn ʿAwf, and he said: “Muṣʿab ibn ʿUmayr was killed — and he was better than me — and nothing was found to shroud him in except a single cloak. I fear that our good things may have been hastened for us in this worldly life.” Then he began to weep."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1274)."},{"num":3636,"demo":false,"sanad":"","matn":["عَنْ حَارِثَةَ بْنِ مُضَرِّبٍ، قَالَ: دَخَلْتُ عَلَى خَبَّابٍ، وَقَدْ اكْتَوَى سَبْعًا فَقَالَ: لَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَتَمَنَّى أَحَدُكُمُ الْمَوْتَ لَتَمَنَّيْتُهُ وَلَقَدْ رَأَيْتُنِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا أَمْلِكُ دِرْهَمًا، وَإِنَّ فِي جَانِبِ بَيْتِي الْآنَ لَأَرْبَعِينَ أَلْفَ دِرْهَمٍ. قَالَ: ثُمَّ أُتِيَ بِكَفَنِهِ، فَلَمَّا رَآهُ بَكَى، وَقَالَ: لَكِنَّ حَمْزَةَ لَمْ يُوجَدْ لَهُ كَفَنٌ إِلَّا بُرْدَةٌ مَلْحَاءُ، إِذَا جُعِلَتْ عَلَى رَأْسِهِ قَلَصَتْ عَنْ قَدَمَيْهِ، وَإِذَا جُعِلَتْ عَلَى قَدَمَيْهِ قَلَصَتْ عَنْ رَأْسِهِ، حَتَّى مُدَّتْ عَلَى رَأْسِهِ، وَجُعِلَ عَلَى قَدَمَيْهِ الْإِذْخِرُ."],"takhrij":"صحيح: رواه الترمذي (970) عن محمد بشار، حدثنا محمد بن جعفر، حدثنا شعبة، عن أبي إسحاق، عن حارثة بن مُضَرِّب فذكر الحديث غير أن الترمذي لم يذكر قصة كفن حمزة، وإنما ذكره الإمام أحمد (21072، 27219) واللفظ له من وجه آخر، عن إسرائيل، عن أبي إسحاق بإسناده.","grade":"صحيح","chapter_ar":"باب إذا لم يجد كفنًا إلا ما يُواري رأسه أو قدميه غطَّى رأسه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Tirmidhī (970), Aḥmad (21072, 27219), and this is Aḥmad’s wording.","chapter_en":"If only enough shroud is found to cover either the head or the feet, the head is covered","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Ḥārithah ibn Muḍarrib said: I entered upon Khabbāb after he had been cauterized seven times. He said: “Were it not that I heard the Messenger of Allah ﷺ say, ‘None of you should wish for death,’ I would have wished for it. I remember myself with the Messenger of Allah ﷺ when I did not own even a dirham, yet now there are forty thousand dirhams at the side of my house.” He said: Then his shroud was brought to him, and when he saw it he cried and said: “Ḥamzah could not be found a shroud except a striped cloak. If it was placed over his head, it shrank away from his feet, and if it was placed over his feet, it shrank away from his head. So it was stretched over his head, and idhkhir grass was placed over his feet.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (970)، وأحمد (21072، 27219)، واللفظ له."},{"num":3637,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ امْرَأَةً، جَاءَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِبُرْدَةٍ مَنْسُوجَةٍ فِيهَا حَاشِيَتُهَا، ـ أَتَدْرُونَ مَا الْبُرْدَةُ؟ قَالُوا: الشَّمْلَةُ. قَالَ: نَعَمْ. قَالَتْ: نَسَجْتُهَا بِيَدِي، فَجِئْتُ لأَكْسُوَكَهَا. فَأَخَذَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجًا إِلَيْهَا، فَخَرَجَ إِلَيْنَا وَإِنَّهَا إِزَارُهُ، فَحَسَّنَهَا فُلاَنٌ فَقَالَ: اكْسُنِيهَا، مَا أَحْسَنَهَا. قَالَ الْقَوْمُ: مَا أَحْسَنْتَ، لَبِسَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجًا إِلَيْهَا، ثُمَّ سَأَلْتَهُ وَعَلِمْتَ أَنَّهُ لاَ يَرُدُّ. قَالَ: إِنِّي وَاللَّهِ مَا سَأَلْتُهُ لأَلْبَسَهَا، إِنَّمَا سَأَلْتُهُ لِتَكُونَ كَفَنِي. قَالَ سَهْلٌ: فَكَانَتْ كَفَنَهُ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1277) عن عبدالله بن مسلمة، حدثنا ابن أبي حازم، عن أبيه، عن سهل فذكره.","grade":"صحيح","chapter_ar":"باب من أعد الكفن في حياته","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1277).","chapter_en":"One who prepares his shroud during his lifetime","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":25,"content":{"translation":{"en":["Sahl ibn Saʿd reported that a woman came to the Prophet ﷺ with a woven cloak that still had its border on it. He said: “Do you know what a burdah is?” They said: “A wrap.” He said: “Yes.” She said: “I wove it with my own hands, and I came to clothe you with it.” So the Prophet ﷺ took it because he needed it, and he came out to us wearing it as his lower garment. A man admired it and said: “Give it to me to wear. How beautiful it is!” The people said: “You did not do well. The Prophet ﷺ wore it because he needed it, and then you asked him for it, while you knew he does not refuse anyone.” The man said: “By Allah, I did not ask for it to wear it. I only asked him for it so that it would be my shroud.” Sahl said: So it became his shroud."]},"buhuth":{"en":["The phrase “its border” means its edge, or that it was new and had not yet been cut from a larger piece of cloth.","As for “a man”, it was said he was ʿAbd al-Raḥmān ibn ʿAwf, and it was also said that he was an unknown Bedouin man."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15326],"tks":"صحيح: رواه البخاري (1277)."},{"num":3638,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ."],"takhrij":"حسن: رواه الترمذي (993)، وابن ماجه (1463) كلاهما عن محمد بن عبد الملك بن أبي الشوارب، قال: حدثنا عبد العزيز بن المختار، عن سُهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكر الحديث واللفظ لابن ماجه.","grade":"حسن","chapter_ar":"باب استحباب الغسل لمن غسَّل ميتًا","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Tirmidhī (993), Ibn Mājah (1463), and this is Ibn Mājah’s wording.","chapter_en":"The recommendation of ghusl for one who washes a deceased person","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":26,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “Whoever washes a deceased person should bathe.”"]},"buhuth":{"en":["Abū Dāwūd (3162) also narrated it with the wording: “Whoever washes the deceased should bathe, and whoever carries him should perform ablution.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (993)، وابن ماجه (1463)، واللفظ لابن ماجه."},{"num":3639,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ عَلَيْكُمْ فِي غَسْلِ مَيِّتِكُمْ غُسْلٌ إِذَا غَسَّلْتُمُوهُ، فَإِنَّ مَيِّتَكُمْ لَيْسَ بِنَجَسٍ، فَحَسْبُكُمْ أَنْ تَغْسِلُوا أَيْدِيَكُمْ."],"takhrij":"حسن: رواه الدارقطنيّ في سننه (1839) وعنه الحاكم في المستدرك (1426)، عن أحمد بن محمد بن سعيد، عن أبي شيبة إبراهيم بن عبدالله بن أبي شيبة، عن خالد بن مخلد، عن سليمان بن بلال، عن عمرو بن أبي عمرو، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب من لم ير الغسل من غسل الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Dāraquṭnī in his Sunan (2/76), al-Ḥākim in al-Mustadrak (1426).","chapter_en":"Those who did not hold ghusl to be required after washing the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب غسل الميت وتكفينه","group_en":"Compilation of chapters on washing and shrouding the deceased","part_no":13,"group_no":5,"chapter_no":27,"content":{"translation":{"en":["Ibn ʿAbbās said: The Messenger of Allah ﷺ said: “You are not required to bathe after washing your deceased. Your deceased is not impure, so it is enough for you to wash your hands.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني في سننه (1839)، والحاكم في المستدرك (1426)."},{"num":3640,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ يَقُولُ مَرُّوا بِجَنَازَةٍ فَأَثْنَوْا عَلَيْهَا خَيْرًا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَجَبَتْ. ثُمَّ مَرُّوا بِأُخْرَى فَأَثْنَوْا عَلَيْهَا شَرًّا فَقَالَ: وَجَبَتْ. فَقَالَ عُمَرُ بْنُ الْخَطَّابِ: رَضِيَ اللَّهُ عَنْهُ مَا وَجَبَتْ؟ قَالَ: هَذَا أَثْنَيْتُمْ عَلَيْهِ خَيْرًا فَوَجَبَتْ لَهُ الْجَنَّةُ، وَهَذَا أَثْنَيْتُمْ عَلَيْهِ شَرًّا فَوَجَبَتْ لَهُ النَّارُ، أَنْتُمْ شُهَدَاءُ اللَّهِ فِي الأَرْضِ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1367) عن آدم، عن شعبة، حدثنا عبد العزيز بن صُهيب قال: سمعت أنس بن مالك فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ثناء الناس على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1367), Muslim (949).","chapter_en":"People praising or criticizing the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik said: They passed by a funeral and spoke well of the deceased, so the Prophet ﷺ said: “It has become due.” Then they passed by another funeral and spoke badly of the deceased, so he said: “It has become due.” ʿUmar ibn al-Khaṭṭāb said: “What has become due?” He said: “This one, you spoke well of him, so Paradise became due for him. And this one, you spoke badly of him, so the Fire became due for him. You are Allah’s witnesses on the earth.”"]},"buhuth":{"en":["Al-Ḥākim added (1/377): “Allah has angels who speak upon the tongues of the children of Adam regarding what is in a person of good and evil.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14657],"tks":"متفق عليه: رواه البخاري (1367)، ومسلم (949)."},{"num":3641,"demo":false,"sanad":"","matn":["عَنْ أَبِي الأَسْوَدِ قَالَ: قَدِمْتُ الْمَدِينَةَ- وَقَدْ وَقَعَ بِهَا مَرَضٌ- فَجَلَسْتُ إِلَى عُمَرَ بْنِ الْخَطَّابِ، فَمَرَّتْ بِهِمْ جَنَازَةٌ، فأُثْني عَلَى صَاحِبِهَا خَيْرًا فقـــــال عمرُ: وَجَبَتْ، ثُمَّ مُرَّ بِأُخْرَى فَأُثْنِيَ عَلَى صَاحِبِهَا خَيْرًا، فقـــــال عُمَرُ: وَجَبَتْ، ثُمَّ مُرَّ بِأُخْرَى، فأثنى عَلَى صاحبهــــا خَيْرًا، فقـــال عمرُ: وَجَبَتْ، ثُمَّ مُرَّ بِالثَّالِثَةِ فأُثْنِي عَلَى صاحبهـــا شرّاً، فَقَالَ وَجَبَتْ. فَقَالَ أَبُو الأَسْوَدِ: فَقُلْتُ: وَمَا وَجَبَتْ يَا أَمِيرَ الْمُؤْمِنِينَ؟ قَالَ: قُلْتُ كَمَا قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَيُّمَا مُسْلِمٍ شَهِدَ لَهُ أَرْبَعَةٌ بِخَيْرٍ أَدْخَلَهُ اللَّهُ الْجَنَّةَ فقلنـــا: وَثَلاَثَةٌ؟ قَالَ: وَثَلاَثَةٌ. فَقُلْنَا: وَاثْنَانِ؟ قـــال: وَاثْنَانِ. ثُمَّ لَمْ نَسْأَلْهُ عَنِ الْوَاحِدِ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1368) عن عفان بن مسلم، حدثنا داود بن أبي الفرات، عن عبدالله بن بريدة، عن أبي الأسود فذكره.","grade":"صحيح","chapter_ar":"باب ثناء الناس على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1368).","chapter_en":"People praising or criticizing the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abū al-Aswad said: I came to Madinah when an illness had spread there, and I sat with ʿUmar ibn al-Khaṭṭāb. A funeral passed by, and people spoke well of the deceased, so ʿUmar said: “It has become due.” Then another funeral passed by, and people again spoke well of the deceased, so ʿUmar said: “It has become due.” Then a third funeral passed by, and people spoke badly of the deceased, so he said: “It has become due.” Abū al-Aswad said: I asked, “What has become due, O Commander of the Believers?” He said: “I said what the Prophet ﷺ said: ‘Any Muslim for whom four people testify with good, Allah will admit him into Paradise.’” We said: “And three?” He said: “And three.” We said: “And two?” He said: “And two.” Then we did not ask him about one."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1368)."},{"num":3642,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: مُرَّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِجِنَازَةٍ - فَأُثْنِيَ عَلَيْهَا خَيْرًا فِي مَنَاقِبِ الْخَيْرِ فَقَالَ: وَجَبَتْ. ثُمَّ مَرُّوا عَلَيْهِ بِأُخْرَى، فَأُثْنِيَ عَلَيْهَا شَرًّا فِي مَنَاقِبِ الشَّرِّ فَقَالَ: وَجَبَتْ إِنَّكُمْ شُهَدَاءُ اللَّهِ فِي الأَرْضِ."],"takhrij":"حسن: رواه ابن ماجه (1492) عن أبي بكر بن أبي شيبة، قال: حدثنا علي ابن مُسْهر، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب ثناء الناس على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (1492), authenticated by Ibn Ḥibbān (3024), and Aḥmad (7552).","chapter_en":"People praising or criticizing the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah said: A funeral passed by the Prophet ﷺ, and people praised the deceased by mentioning good qualities, so he said: “It has become due.” Then another funeral passed by, and people spoke badly of that deceased by mentioning evil qualities, so he said: “It has become due. You are Allah’s witnesses on the earth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1492)، وصححه ابن حبان (3024)، والإمام أحمد (7552)."},{"num":3643,"demo":false,"sanad":"","matn":["عن سلمة بن الأكوع قال: كنا مع النبي صلى الله عليه وسلم فمُرّ عليه بجنازة، فأثنِيَ عليها بثناءٍ حَسنٍ، فقال: وَجبَتْ! ومُرَّ عليه بجنازة أخرى، فأثنِيَ عليها دون ذلك، فقال: وجبَتْ! قالوا: يا رسول الله، ما وجبَتْ؟ قال: الملائكة شُهداء الله في السماء، وأنتم شهداء الله في الأرض، فما شهدتم عليه وجب. ثم قرأ: ﴿وَقُلِ اعْمَلُوا فَسَيَرَى اللَّهُ عَمَلَكُمْ وَرَسُولُهُ وَالْمُؤْمِنُونَ﴾ [سورة التوبة: 105] الآية. [سورة التوبة: 105]."],"takhrij":"حسن: رواه الطبري في تفسيره (596) عن أبي كريب (محمد بن العلاء بن كريب)، حدثنا زيد بن الحباب، حدثنا عكرمة بن عمار، حدثني إياس بن سلمة بن الأكوع، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب ثناء الناس على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarī in his Tafsīr (2/632).","chapter_en":"People praising or criticizing the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: We were with the Prophet ﷺ when a funeral passed by him, and the deceased was praised with good words, so he said: “It has become due.” Then another funeral passed by him, and the deceased was spoken of with less than that, so he said: “It has become due.” They said: “O Messenger of Allah ﷺ, what has become due?” He said: “The angels are Allah’s witnesses in the heaven, and you are Allah’s witnesses on the earth. Whatever you testify about concerning him becomes due.” Then he recited: “And say: Act, for Allah will see your deeds, and His Messenger, and the believers.” [9:105]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبري في تفسيره (596)."},{"num":3644,"demo":false,"sanad":"","matn":["عن أَبِي قَتَادَةَ عَنْ أَبِيهِ قَالَ:، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا دُعِيَ لِجِنَازَةٍ سَأَلَ عَنْهَا، فَإِنْ أُثْنِيَ عَلَيْهَا خَيْرٌ قَامَ فَصَلَّى عَلَيْهَا، وَإِنْ أُثْنِيَ عَلَيْهَا غَيْرُ ذَلِكَ قَالَ لِأَهْلِهَا: شَأْنُكُمْ بِهَا وَلَمْ يُصَلِّ عَلَيْهَا."],"takhrij":"صحيح: رواه الإمام أحمد (22555) عن يعقوب، حدثنا أبي، عن أبيه، حدثني عبدالله بن أبي قتادة، عن أبيه فذكره، ويعقوب هو: ابن إبراهيم بن سعد.","grade":"صحيح","chapter_ar":"باب ثناء الناس على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Aḥmad (22555), authenticated by Ibn Ḥibbān (3057), and al-Ḥākim (1348).","chapter_en":"People praising or criticizing the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abū Qatādah said: When the Messenger of Allah ﷺ was called to a funeral, he would ask about the deceased. If the deceased was spoken of well, he would stand and pray over him. If the deceased was spoken of otherwise, he would say to the family: “You may deal with him yourselves,” and he would not pray over him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (22555)، وصححه ابن حبان (3057)، والحاكم (1348)."},{"num":3645,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ مُسْلِمٍ يَمُوتُ فَيَشْهَدُ لَهُ أَرْبَعَةُ أَهْلِ أَبْيَاتٍ مِنْ جِيرَانِهِ الْأَدْنَيْنَ أَنَّهُمْ لَا يَعْلَمُونَ إِلَّا خَيْرًا، إِلَّا قَالَ اللَّهُ: قَدْ قَبِلْتُ عِلْمَكُمْ، وَغَفَرْتُ لَهُ مَا لَا تَعْلَمُونَ."],"takhrij":"حسن: رواه الإمام أحمد (13541)، وأبو يعلى (3468 تحقيق الأثري) كلاهما من طريق مؤمل بن إسماعيل، حدثنا حماد، حدثنا ثابت، عن أنس.","grade":"حسن","chapter_ar":"باب ثناء الجيران على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (13541), Abū Yaʿlā (3468), authenticated by Ibn Ḥibbān (3026), and al-Ḥākim (1398).","chapter_en":"The neighbors praising the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik said: The Messenger of Allah ﷺ said: “No Muslim dies, and four households from his nearest neighbors testify that they know nothing about him except good, except that Allah, Mighty and Majestic, says: ‘I have accepted what you know about him, and I have forgiven him for what you do not know.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (13541)، وأبو يعلى (3468)، وصححه ابن حبان (3026)، والحاكم (1398)."},{"num":3646,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَسُبُّوا الأَمْوَاتَ، فَإِنَّهُمْ قَدْ أَفْضَوْا إِلَى مَا قَدَّمُوا."],"takhrij":"صحيح: رواه البخاري في الجنائز (1393) عن آدم، حدثنا شُعبة، عن الأعمش، عن مجاهد، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما يُنهى عن سبِّ الأموات","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1393).","chapter_en":"What is forbidden regarding insulting the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿĀ’ishah said: The Prophet ﷺ said: “Do not insult the dead, for they have already gone on to what they sent ahead.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1393)."},{"num":3647,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: ذُكِرَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَالِكٌ بِسُوءٍ فَقَالَ: لاَ تَذْكُرُوا هَلْكَاكُمْ إِلاَّ بِخَيْرٍ."],"takhrij":"صحيح: رواه النسائي (1935) عن إبراهيم بن يعقوب، قال: حدثني أحمد بن إسحاق، قال: حدثنا وُهيب، حدثنا منصور بن عبدالرحمن، عن أمه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما يُنهى عن سبِّ الأموات","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1935).","chapter_en":"What is forbidden regarding insulting the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, said: A dead person was mentioned negatively in the presence of the Prophet ﷺ, so he said: “Do not mention your dead except with good.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1935)."},{"num":3648,"demo":false,"sanad":"","matn":["عن الْمُغِيرَةِ بن شُعْبَةَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَسُبُّوا الأَمْوَاتَ، فَتُؤْذُوا الأَحْيَاءَ."],"takhrij":"صحيح: رواه الترمذي (1982) عن محمود بن غيلان، حدثنا أبو داود الحُفري، عن سفيان، عن زياد بن عِلاقة قال: سمعت المغيرة بن شعبة فذكره.","grade":"صحيح","chapter_ar":"باب ما يُنهى عن سبِّ الأموات","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Tirmidhī (1982), authenticated by Ibn Ḥibbān (3022), and Aḥmad (18209).","chapter_en":"What is forbidden regarding insulting the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah said: The Messenger of Allah ﷺ said: “Do not insult the dead, lest you hurt the living.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14949],"tks":"صحيح: رواه الترمذي (1982)، وصححه ابن حبان (3022)، والإمام أحمد (18209)."},{"num":3649,"demo":false,"sanad":"","matn":["عَنْ قُطْبَةَ بْنِ مَالِكٍ، قَالَ: سَبَّ أَمِيرٌ مِنَ الْأُمَرَاءِ عَلِيًّا رَضِيَ اللَّهُ تَعَالَى عَنْهُ، فَقَامَ زَيْدُ بْنُ أَرْقَمَ فَقَالَ: أَمَا أَنْ قَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ سَبِّ الْمَوْتَى، فَلِمَ تَسُبُّ عَلِيًّا وَقَدْ مَاتَ؟"],"takhrij":"حسن: رواه الإمام أحمد (19315) عن وكيع، حدثنا مِسْعر، عن أبي أيوب مولى لبني ثعلبة، عن قطبة بن مالك فذكره.","grade":"حسن","chapter_ar":"باب ما يُنهى عن سبِّ الأموات","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (19315), also reported by al-Ṭabarānī in al-Kabīr (5/188).","chapter_en":"What is forbidden regarding insulting the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Quṭbah ibn Mālik said: One of the rulers insulted ʿAlī, so Zayd ibn Arqam stood up and said: “You already know that the Messenger of Allah ﷺ forbade insulting the dead, so why do you insult ʿAlī when he has died?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (19315)، وأخرجه الطبراني في الكبير (4953)."},{"num":3650,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا مَاتَ صَاحِبُكُمْ فَدَعُوهُ، لاَ تَقَعُوا فِيهِ."],"takhrij":"صحيح: رواه أبو داود (4899) عن زهير بن حرب، حدثنا وكيع، حدثنا هشام بن عروة، عن أبيه، عن عائشة فذكرته. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يُنهى عن سبِّ الأموات","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (4899).","chapter_en":"What is forbidden regarding insulting the dead","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿĀ’ishah said: The Messenger of Allah ﷺ said: “When your companion dies, leave him alone and do not speak badly of him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود (4899)."},{"num":3651,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ بْنِ رِبْعِيٍّ الأَنْصَارِيِّ، أَنَّهُ كَانَ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُرَّ عَلَيْهِ بِجِنَازَةٍ فَقَالَ: مُسْتَرِيحٌ، وَمُسْتَرَاحٌ مِنْهُ. قَالُوا: يَا رَسُولَ اللَّهِ! مَا الْمُسْتَرِيحُ وَالْمُسْتَرَاحُ مِنْهُ؟ قَالَ: الْعَبْدُ الْمُؤْمِنُ يَسْتَرِيحُ مِنْ نَصَبِ الدُّنْيَا وَأَذَاهَا إِلَى رَحْمَةِ اللَّهِ، وَالْعَبْدُ الْفَاجِرُ يَسْتَرِيحُ مِنْهُ الْعِبَادُ وَالْبِلاَدُ، وَالشَّجَرُ وَالدَّوَابُّ."],"takhrij":"متفق عليه: رواه مالك في الجنائز (54) عن محمد بن عمرو بن حلحلة الدِيّلي، عن معبد بن كعب بن مالك، عن أبي قتادة بن رِبْعي فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في المستريح والمستراح منه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (54), al-Bukhārī (6512), Muslim (950).","chapter_en":"What is reported about the one who is relieved, and the one from whom others are relieved","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Abū Qatādah ibn Ribʿī used to narrate that the Messenger of Allah ﷺ passed by a funeral and said: “One is relieved, and from another people are relieved.” They said: “O Messenger of Allah ﷺ, who is the one relieved, and who is the one from whom others are relieved?” He said: “The believing servant is relieved from the hardship and harm of this world and goes to the mercy of Allah. As for the wicked servant, the servants, the lands, the trees, and the animals are relieved from him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (54)، والبخاري (6512)، ومسلم (950)."},{"num":3652,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: تُوُفِّيَتِ امْرَأَةٌ كَانَ أَصْحَابُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَضْحَكُونَ مِنْهَا، وَيُمَازِحُونَهَا، فَقُلْتُ: اسْتَرَاحَتْ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا يَسْتَرِيحُ مَنْ غُفِرَ لَهُ."],"takhrij":"حسن: رواه البزار كشف الأستار (789) عن أحمد بن إسحاق الأهوازي، ثنا عثمان بن عمر، ثنا يونس - يعني ابن يزيد، عن الزهري، عن محمد بن عروة بن الزبير، عن أبيه، عن عائشة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في المستريح والمستراح منه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bazzār in Kashf al-Astār (789).","chapter_en":"What is reported about the one who is relieved, and the one from whom others are relieved","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["ʿĀ’ishah said: A woman died whom the companions of the Prophet ﷺ used to laugh at and joke with. So I said: “She has found rest.” The Prophet ﷺ said: “Only the one who has been forgiven truly finds rest.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (789)."},{"num":3653,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بْنِ رَبِيعَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا رَأَيْتُمُ الْجَِنَازَةَ فَقُومُوا لَهَا، حَتَّى تُخَلِّفَكُمْ، أَوْ تُوضَعَ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1307)، ومسلم في الجنائز (958) كلاهما من طريق سفيان، عن الزهري، عن سالم، عن أبيه، عن عامر ابن ربيعة فذكر الحديث ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب القيام للجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1307), Muslim (958).","chapter_en":"Standing for the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["ʿĀmir ibn Rabīʿah said: The Messenger of Allah ﷺ said: “When you see a funeral, stand for it until it passes beyond you or is set down.”"]},"buhuth":{"en":["Al-Bukhārī (1308) and Muslim also narrated with the wording: “When one of you sees a funeral, if he is not walking with it, then let him stand until it leaves him behind, or he leaves it behind, or it is set down before it passes him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1307)، ومسلم (958)."},{"num":3654,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِذَا رَأَيْتُمُ الْجَِنَازَةَ فَقُومُوا، فَمَنْ تَبِعَهَا فَلَا يَجْلِسْ حَتَّى تُوضَعَ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1310)، ومسلم في الجنائز (959/77) كلاهما من حديث هشام (هو ابن حسان) قال: حدثنا يحيى بن أبي كثير، عن أبي سلمة بن عبدالرحمن، عن أبي سعيد فذكره.","grade":"متفق عليه","chapter_ar":"باب القيام للجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1310), Muslim (959/77).","chapter_en":"Standing for the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that the Messenger of Allah ﷺ said: “When you see a funeral, stand. And whoever follows it should not sit until it is set down.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1310)، ومسلم (959/77)."},{"num":3655,"demo":false,"sanad":"","matn":["عَنْ سَعِيدٍ الْمَقْبُرِيِّ، عَنْ أَبِيهِ، قَالَ: كُنَّا فِي جَنَازَةٍ فَأَخَذَ أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ بِيَدِ مَرْوَانَ فَجَلَسَا قَبْلَ أَنْ تُوضَعَ، فَجَاءَ أَبُو سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ فَأَخَذَ بِيَدِ مَرْوَانَ فَقَالَ: قُمْ، فَوَاللَّهِ لَقَدْ عَلِمَ هَذَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَانَا عَنْ ذَلِكَ. فَقَالَ أَبُو هُرَيْرَةَ: صَدَقَ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1309) عن أحمد بن يونس، حدثنا ابن أبي ذئب، عن سعيد المقبري، عن أبيه أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب القيام للجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1309).","chapter_en":"Standing for the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd al-Maqburī said: We were at a funeral, and Abū Hurayrah took Marwān by the hand and they both sat before the funeral was set down. Then Abū Saʿīd al-Khudrī came, took Marwān by the hand, and said: “Stand up. By Allah, this man knows that the Prophet ﷺ forbade us from doing that.” Abū Hurayrah said: “He is telling the truth.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1309)."},{"num":3656,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرُّوا عَلَيْهِ بِجَنَازَةٍ فَقَامَ. وَقَالَ عَمْرٌو إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّتْ بِهِ جَنَازَةٌ فَقَامَ."],"takhrij":"صحيح: رواه النسائي (1919) عن عمرو بن علي قال: حدثنا يحيى بن سعيد، قال: حدثنا زكريا، عن الشعبي قال: قال أبو سعيد.","grade":"صحيح","chapter_ar":"باب القيام للجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1919).","chapter_en":"Standing for the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd reported that a funeral passed by the Messenger of Allah ﷺ and he stood up. And ʿAmr said: A funeral passed by the Messenger of Allah ﷺ, so he stood up."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1919)."},{"num":3657,"demo":false,"sanad":"","matn":["عَنْ عَمِّهِ، يَزِيدَ بْنِ ثَابِتٍ: أَنَّهُمْ كَانُوا جُلُوسًا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَطَلَعَتْ جَنَازَةٌ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَامَ مَنْ مَعَهُ، فَلَمْ يَزَالُوا قِيَامًا حَتَّى نَفَذَتْ."],"takhrij":"صحيح: رواه النسائي (1920) عن أيوب بن محمد الوزَّان، حدثنا مروان، حدثنا عثمان بن حكيم، قال: أخبرني خارجة بن زيد بن ثابت، عن عمه يزيد بن ثابت فذكره.","grade":"صحيح","chapter_ar":"باب القيام للجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1920).","chapter_en":"Standing for the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Yazīd ibn Thābit reported that they were sitting with the Prophet ﷺ when a funeral appeared. The Messenger of Allah ﷺ stood, and those with him also stood, and they remained standing until it had passed by."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1920)."},{"num":3658,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، وَأَبِي، سَعِيدٍ قَالاَ: مَا رَأَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَهِدَ جَنَازَةً قَطُّ فَجَلَسَ حَتَّى تُوضَعَ."],"takhrij":"حسن: رواه النسائي (1918) عن يوسف بن سعيد، قال: حدثنا حجاج، عن ابن جريج، عن ابن عجلان، عن سعيد، عن أبي هريرة وأبي سعيد، فذكراه.","grade":"حسن","chapter_ar":"باب القيام للجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Nasā’ī (1918).","chapter_en":"Standing for the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah and Abū Saʿīd said: We never saw the Messenger of Allah ﷺ attend a funeral and then sit down before it was set down."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1918)."},{"num":3659,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ:  مَرَّتْ جَِنَازَةٌ فَقَامَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقُمْنَا مَعَهُ، فَقُلْنَا: يَا رَسُولَ اللَّهِ! إِنَّهَا يَهُودِيَّةٌ، فَقَالَ: إِنَّ الْمَوْتَ فَزَعٌ، فَإِذَا رَأَيْتُمُ الْجَِنَازَةَ فَقُومُوا."],"takhrij":"متفق عليه: رواه مسلم في الجنائز (960) من طرق عن إسماعيل بن علية، عن هشام الدستوائي، عن يحيى بن أبي كثير، عن عبيدالله بن مِقْسَم، عن جابر ابن عبدالله فذكره.","grade":"متفق عليه","chapter_ar":"باب القيام لجنازة غير المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Muslim (960), and this is Muslim’s wording; al-Bukhārī (1311).","chapter_en":"Standing for the funeral of non-Muslims","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: A funeral passed by, and the Prophet ﷺ stood for it, and we stood with him. We said, “O Messenger of Allah ﷺ, it is a Jewish funeral.” He said: “Death is something alarming, so when you see a funeral, stand.”"]},"buhuth":{"en":["In another narration recorded by Muslim: The Prophet ﷺ and his companions stood for the funeral of a Jew until it passed from view."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (960) واللفظ لمسلم، والبخاري (1311)."},{"num":3660,"demo":false,"sanad":"","matn":["عَبْدَ الرَّحْمَنِ بْنَ أَبِي لَيْلَى، قَالَ: كَانَ سَهْلُ بْنُ حُنَيْفٍ وَقَيْسُ بْنُ سَعْدٍ قَاعِدَيْنِ بِالْقَادِسِيَّةِ، فَمَرُّوا عَلَيْهِمَا بِجَنَازَةٍ فَقَامَا. فَقِيلَ لَهُمَا: إِنَّهَا مِنْ أَهْلِ الأَرْضِ، أَىْ مِنْ أَهْلِ الذِّمَّةِ فَقَالاَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّتْ بِهِ جَنَازَةٌ فَقَامَ، فَقِيلَ لَهُ: إِنَّهَا جَنَازَةُ يَهُودِيٍّ. فَقَالَ: أَلَيْسَتْ نَفْسًا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1312)، ومسلم في الجنائز (961) كلاهما من طريق شعبة، عن عمرو بن مرة، عن ابن ابي ليلى فذكره.","grade":"متفق عليه","chapter_ar":"باب القيام لجنازة غير المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1312), Muslim (961), and this is the wording of al-Bukhārī.","chapter_en":"Standing for the funeral of non-Muslims","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī Laylā said: Sahl ibn Ḥunayf and Qays ibn Saʿd were sitting at al-Qādisiyyah when a funeral passed by them, so they stood. It was said to them, “It is from the people of the land,” meaning from the protected non-Muslim community. They replied: The Prophet ﷺ once had a funeral pass by him and he stood. It was said to him, “It is a Jewish funeral.” He said: “Is it not a human soul?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1312)، ومسلم (961)، واللفظ للبخاري."},{"num":3661,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّتْ بِهِ جَنَازَةُ يَهُودِيٍّ، فَقَامَ: فَقِيلَ لَهُ: يَا رَسُولَ اللَّهِ، إِنَّهَا جَنَازَةُ يَهُودِيٍّ، فَقَالَ: إِنَّ لِلْمَوْتِ فَزَعًا."],"takhrij":"حسن: رواه الإمام أحمد (8527) عن عفان، حدثنا حماد بن سلمة، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب القيام لجنازة غير المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (8527), Ibn Mājah (1543).","chapter_en":"Standing for the funeral of non-Muslims","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah reported that a Jewish funeral passed by the Messenger of Allah ﷺ, and he stood. It was said to him, “O Messenger of Allah ﷺ, it is a Jewish funeral.” He said: “Death is something alarming.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (8527)، وابن ماجه (1543)."},{"num":3662,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ جَنَازَةً، مَرَّتْ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ، فَقِيلَ: إِنَّهَا جَنَازَةُ يَهُودِيٍّ. فَقَالَ: إِنَّمَا قُمْنَا لِلْمَلاَئِكَةِ."],"takhrij":"صحيح: رواه النسائي (1929) عن إسحاق، قال: أنبأنا النضر، قال: حدثنا حماد بن سلمة، عن قتادة، عن أنس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب القيام لجنازة غير المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1929).","chapter_en":"Standing for the funeral of non-Muslims","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik reported that a funeral passed by the Messenger of Allah ﷺ, so he stood. It was said, “It is a Jewish funeral.” He said: “We stood because of the angels.”"]},"buhuth":{"en":["About the phrase “We stood because of the angels,” al-Suyūṭī said: “There is no contradiction, because there may be multiple reasons and wisdoms at the same time. So standing may be sought as a form of respect for the matter of death, for the angels, and for other reasons as well.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1929)."},{"num":3663,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُومُ فِي الْجَنَائِزِ ثُمَّ جَلَسَ، بَعْدُ.","وفي رواية: عَنْ وَاقِدِ بْنِ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ أَنَّهُ قَالَ: رَآنِي نَافِعُ بْنُ جُبَيْرٍ، وَنَحْنُ فِي جَِنَازَةٍ قَائِمًا، وَقَدْ جَلَسَ يَنْتَظِرُ أَنْ تُوضَعَ الْجَِنَازَةُ، فَقَالَ لِي: مَا يُقِيمُكَ؟ فَقُلْتُ: أَنْتَظِرُ أَنْ تُوضَعَ الْجَِنَازَةُ لِمَا يُحَدِّثُ أَبُو سَعِيدٍ الْخُدْرِيُّ، فَقَالَ نَافِعٌ: فَإِنَّ مَسْعُودَ بْنَ الْحَكَمِ حَدَّثَنِي عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ أَنَّهُ قَالَ: قَامَ رَسُولُ اللهِ صلى الله عليه وسلم ثُمَّ قَعَدَ."],"takhrij":"صحيح: رواه مالك في الجنائز (33) عن يحيى بن سعيد، عن واقد بن عمرو بن سعد بن معاذ، عن نافع بن جبير بن مطعم، عن مسعود بن الحكم، عن علي بن أبي طالب فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نسخ القيام للجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Mālik (33), and the second narration is in Muslim (962).","chapter_en":"What is reported about the later discontinuation of standing for the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib reported that the Messenger of Allah ﷺ used to stand for the funeral, then later he sat. In another narration, Wāqid ibn ʿAmr ibn Saʿd ibn Muʿādh said: Nāfiʿ ibn Jubayr saw me standing at a funeral while he himself was sitting, waiting for the funeral to be set down. He said to me, “Why are you still standing?” I said, “I am waiting for the funeral to be set down because of what Abū Saʿīd al-Khudrī narrated.” Nāfiʿ said, “Masʿūd ibn al-Ḥakam narrated to me from ʿAlī ibn Abī Ṭālib that he said: The Messenger of Allah ﷺ stood, then later sat.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (33)، والرواية الثانية عند مسلم (962)."},{"num":3664,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدٍ، أَنَّ جَنَازَةً، مَرَّتْ بِالْحَسَنِ بْنِ عَلِيٍّ وَابْنِ عَبَّاسٍ، فَقَامَ الْحَسَنُ، وَلَمْ يَقُمِ ابْنُ عَبَّاسٍ، فَقَالَ الْحَسَنُ: أَلَيْسَ قَدْ قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِجَنَازَةِ يَهُودِيٍّ؟ قَالَ ابْنُ عَبَّاسٍ: نَعَمْ، ثُمَّ جَلَسَ."],"takhrij":"صحيح: رواه النسائي (1924) عن قتيبة، قال: حدثنا حماد، عن أيوب، عن محمد بن سيرين، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نسخ القيام للجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1924).","chapter_en":"What is reported about the later discontinuation of standing for the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Muḥammad reported that a funeral passed by al-Ḥasan ibn ʿAlī and Ibn ʿAbbās. Al-Ḥasan stood, while Ibn ʿAbbās did not stand. Al-Ḥasan said, “Did not the Messenger of Allah ﷺ stand for the funeral of a Jew?” Ibn ʿAbbās said: “Yes, then later he sat.”"]},"buhuth":{"en":["Legal note (translation):","The Prophet’s statement, “Death is something alarming,” and his statement, “Is it not a human soul?” show that the Prophet ﷺ did stand for funerals. If that is the reason for standing, then that reason remains. So what is reported in the hadith of ʿAlī ibn Abī Ṭālib — that he stood and then later sat — indicates that standing is recommended, not obligatory. The report of ʿAlī ibn Abī Ṭālib would not be an abrogation if the reason for standing remains as mentioned earlier. Other explanations have been given, but the one mentioned here is stronger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1924)."},{"num":3665,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَنَازَةِ رَجُلٍ مِنَ الأَنْصَارِ، فَانْتَهَيْنَا إِلَى الْقَبْرِ، وَلَمْ يُلْحَدْ بَعْدُ، فَجَلَسَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُسْتَقْبِلَ الْقِبْلَةِ، وَجَلَسْنَا مَعَهُ."],"takhrij":"حسن: رواه أبو داود (3212)، والنسائي (2001)، وابن ماجه (1549) كلهم من طريق المنهال بن عمرو، عن زاذان، عن البراء فذكر الحديث واللفظ لأبي داود، وزاد ابن ماجه: كأن على رؤوسنا الطير .","grade":"حسن","chapter_ar":"باب الجلوس عند القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3212), al-Nasā’ī (2001), Ibn Mājah (1549), and this is the wording of Abū Dāwūd.","chapter_en":"Sitting by the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Al-Barā’ ibn ʿĀzib said: We went out with the Messenger of Allah ﷺ for the funeral of a man from the Anṣār. We reached the grave before the burial niche had been prepared, so the Prophet ﷺ sat facing the qiblah, and we sat with him."]},"buhuth":{"en":["Ibn Mājah adds: “It was as if birds were on our heads.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3212)، والنسائي (2001)، وابن ماجه (1549)، واللفظ لأبي داود."},{"num":3666,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ، وَنَهَانَا عَنْ سَبْعٍ: أَمَرَنَا بِاتِّبَاعِ الْجَنَائِزِ، وَعِيَادَةِ الْمَرِيضِ، وَإِجَابَةِ الدَّاعِي، وَنَصْرِ الْمَظْلُومِ، وَإِبْرَارِ الْقَسَمِ، وَرَدِّ السَّلاَمِ، وَتَشْمِيتِ الْعَاطِسِ. وَنَهَانَا عَنْ: آنِيَةِ الْفِضَّةِ، وَخَاتَمِ الذَّهَبِ، وَالْحَرِيرِ، وَالدِّيبَاجِ، وَالْقَسِّيِّ، وَالإِسْتَبْرَقِ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1239) عن أبي الوليد، حدثنا شعبة، عن الأشعث قال: سمعتُ معاوية بن سويد بن مُقرّن، عن البراء فذكره.","grade":"متفق عليه","chapter_ar":"باب الأمر باتباع الجنائز وفضله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1239), Muslim (2066). In one wording, spreading greetings of peace appears instead of returning greetings of peace.","chapter_en":"The command to follow funerals and its virtue","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Al-Barā’ said: The Prophet ﷺ commanded us with seven things and forbade us from seven things. He commanded us to follow funerals, visit the sick, answer invitations, support the one who has been wronged, fulfill oaths, return greetings of peace, and pray for the one who sneezes. And he forbade us from silver vessels, gold rings, silk, brocade, striped silk cloth, and thick silk."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3454,5932],"tks":"متفق عليه: رواه البخاري (1239)، ومسلم (2066). وفيه: (( إفشاء السلام )) بدلا من (( رد السلام ))."},{"num":3667,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ خَمْسٌ: ردّ السَّلاَمِ، وَعِيَادَةُ الْمَرِيضِ، وَاتِّبَاعُ الْجَنَائِزِ، وَإِجَابَةُ الدَّعْوَةِ، وَتَشْمِيتُ الْعَاطِسِ ."],"takhrij":"متفق عليه: رواه البخاريّ في الجنائز (1240)، ومسلم في كتاب السلام (2162) كلاهما من حديث ابن شهاب، قال: أخبرني سعيد بن المسيب، أن أبا هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب الأمر باتباع الجنائز وفضله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1240), Muslim (2162).","chapter_en":"The command to follow funerals and its virtue","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah said: I heard the Messenger of Allah ﷺ say: “The rights of one Muslim over another are five: returning greetings of peace, visiting the sick, following funerals, accepting invitations, and praying for the one who sneezes.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3455],"tks":"متفق عليه: رواه البخاري (1240)، ومسلم (2162)."},{"num":3668,"demo":false,"sanad":"","matn":["إِنَّ أَبَا هُرَيْرَةَ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ تَبِعَ جَنَازَةً فَلَهُ قِيرَاطٌ مِنَ الْأَجْرِ فَقَالَ ابْنُ عُمَرَ: أَكْثَرَ عَلَيْنَا أَبُو هُرَيْرَةَ، فَبَعَثَ إِلَى عَائِشَةَ، فَسَأَلَهَا فَصَدَّقَتْ أَبَا هُرَيْرَةَ فَقَالَ ابْنُ عُمَرَ: لَقَدْ فَرَّطْنَا فِي قَرَارِيطَ كَثِيرَةٍ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1323)، ومسلم في الجنائز (945/55) كلاهما من حديث جرير بن حازم، حدثنا نافع يقول: حُدِّث ابن عمر أن أبا هريرة يقول: فذكر الحديث مرفوعاً عند مسلم، وأما البخاري فجعله من قول أبي هريرة، ولكنه قال: فصدَّقت –يعني عائشة- أبا هريرة وقالت: سمعت رسول الله صلى الله عليه وسلم يقوله.","grade":"متفق عليه","chapter_ar":"باب الأمر باتباع الجنائز وفضله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1323), Muslim (945/55).","chapter_en":"The command to follow funerals and its virtue","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah al-Dawsī said: I heard the Messenger of Allah ﷺ say: “Whoever follows a funeral will have one measure of reward.” Ibn ʿUmar said: “Abū Hurayrah has narrated too much to us.” So he sent to ʿĀ’ishah and asked her, and she confirmed what Abū Hurayrah said. Then Ibn ʿUmar said: “We have missed out on many great rewards.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1323)، ومسلم (945/55)."},{"num":3669,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنْ شَهِدَ الْجَنَازَةَ حَتَّى يُصَلِّيَ عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ شهدها حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ . قِيلَ: وَمَا الْقِيرَاطَانِ؟ قَالَ: مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1325)، ومسلم في الجنائز (945) كلاهما من حديث يونس، عن ابن شهاب، قال: حدثني عبدالرحمن ابن هرمز الأعرج، أن أبا هريرة قال: فذكر الحديث ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب الأمر باتباع الجنائز وفضله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1325), Muslim (945).","chapter_en":"The command to follow funerals and its virtue","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “Whoever attends a funeral until the funeral prayer is offered will have one measure of reward, and whoever attends it until it is buried will have two measures of reward.” It was said: “What are the two measures?” He said: “Like two great mountains.”"]},"buhuth":{"en":["In another narration in Muslim: “The smaller of them is like Mount Uḥud.”","And in another narration: I said, “O Abū Hurayrah, what is one measure?” He said: “Like Mount Uḥud.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1325)، ومسلم (945)."},{"num":3670,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنِ اتَّبَعَ جَنَازَةَ مُسْلِمٍ إِيمَانًا وَاحْتِسَابًا، وَكَانَ مَعَهُ حَتَّى يُصَلَّى عَلَيْهَا، وَيَفْرُغَ مِنْ دَفْنِهَا، فَإِنَّهُ يَرْجِعُ مِنَ الأَجْرِ بِقِيرَاطَيْنِ، كُلُّ قِيرَاطٍ مِثْلُ أُحُدٍ، وَمَنْ صَلَّى عَلَيْهَا ثُمَّ رَجَعَ قَبْلَ أَنْ تُدْفَنَ فَإِنَّهُ يَرْجِعُ بِقِيرَاطٍ."],"takhrij":"صحيح: رواه البخاري في الإيمان (47) عن أحمد بن عبدالله بن علي المنجوفي قال: حدثنا رَوح، قال: حدثنا عوف، عن الحسن ومحمد، عن أبي هريرة فذكره. وتابعه عثمان المؤذن قال: حدثنا عوف، عن محمد، عن أبي هريرة، عن النبيّ صلى الله عليه وسلم نحوه. انتهى.","grade":"صحيح","chapter_ar":"باب الأمر باتباع الجنائز وفضله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (47).","chapter_en":"The command to follow funerals and its virtue","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “Whoever follows the funeral of a Muslim out of faith and seeking reward, and stays with it until the prayer is offered and the burial is completed, will return with two measures of reward, each measure like Mount Uḥud. And whoever prays over it and then returns before it is buried will return with one measure.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (47)."},{"num":3671,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وقاَّص، أَنَّهُ كَانَ قَاعِدًا عِنْدَ عبدالله بْنِ عُمَرَ، إِذْ طَلَع خبَّاب صَاحِبُ الْمَقْصُورَةِ، فَقَالَ: يَا عبدالله بْنَ عُمَرَ، أَلَا تَسْمَعُ مَا يَقُولُ أَبُو هُرَيْرَةَ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ خَرَجَ مَعَ جَِنَازَةٍ مِنْ بَيْتِهَا وَصَلَّى عَلَيْهَا، ثُمَّ تَبِعَها حَتَّى تُدْفَن كَانَ لَهُ قِيرَاطَانِ مِنْ الْأَجْرِ، كلُّ قِيرَاطٍ مثلُ أُحُد، وَمَنْ صَلَّى عَلَيْهَا ثُمَّ رَجَعَ كَانَ لَهُ مِنَ الْأَجْرِ مِثْلُ أُحُد فَأَرْسَلَ ابنُ عُمَرَ خَبَّاباً إِلَى عَائِشَةَ يَسْأَلُهَا عَنْ قَوْلِ أَبِي هُرَيْرَةَ، ثُمَّ يَرْجِعُ إِلَيْهِ فَيُخْبِرُهُ مَا قالَتْ، وَأَخَذَ ابْنُ عُمَرَ قَبْضَةً مِنْ حصْباء الْمَسْجِدِ يُقَلِّبُها فِي يَدِهِ، حَتَّى رجعَ إِلَيْهِ الرَّسُولُ فَقَالَ: قَالَتْ عَائِشَةُ: صَدَقَ أَبُو هُرَيْرَةَ، فَضَرَبَ ابنُ عمرَ بِالْحَصَى الَّذِي كَانَ فِي يدِه الْأَرْضَ ثُمَّ قَالَ: لَقَدْ فرَّطْنَا فِي قَرَارِيطَ كَثِيرَةٍ."],"takhrij":"صحيح: رواه مسلم في الجنائز (945/56) عن محمد بن عبدالله بن نمير، حدثنا عبدالله بن يزيد، حدثني حيوة، حدثني أبو صخر، عن يزيد بن عبدالله ابن قُسيط، أنه حدثه أن داود بن عامر بن سعد بن أبي وقاص حدثه عن أبيه، أنه كان قاعداً فذكره.","grade":"صحيح","chapter_ar":"باب الأمر باتباع الجنائز وفضله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (945/56).","chapter_en":"The command to follow funerals and its virtue","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ reported that he was sitting with ʿAbdullāh ibn ʿUmar when Khabbāb, the keeper of the enclosed area, appeared and said: “O ʿAbdullāh ibn ʿUmar, do you not hear what Abū Hurayrah says? He says that he heard the Messenger of Allah ﷺ say: ‘Whoever goes out with a funeral from its house, prays over it, then follows it until it is buried, will have two measures of reward, each measure like Mount Uḥud. And whoever prays over it and then returns will have a reward like Mount Uḥud.’” So Ibn ʿUmar sent Khabbāb to ʿĀ’ishah to ask her about the statement of Abū Hurayrah, then to come back and tell him what she said. Meanwhile, Ibn ʿUmar took a handful of pebbles from the mosque and kept turning them in his hand until the messenger returned and said: “ʿĀ’ishah said: Abū Hurayrah spoke the truth.” Then Ibn ʿUmar struck the ground with the pebbles that were in his hand and said: “We have missed out on many great rewards.”"]},"buhuth":{"en":["The phrase “the enclosed area” means the one associated with a protected section surrounded by stone walls. Here it refers to the enclosed section of the mosque."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (945/56)."},{"num":3672,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَنْ صَلَّى عَلَى جَِنَازَةٍ، فَلَهُ قِيرَاطٌ، فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ قِيرَاطَانِ، الْقِيرَاطُ مِثْلُ أُحُدٍ."],"takhrij":"صحيح: رواه مسلم في الجنائز (946) من طرق عن قتادة، عن سالم بن أبي الجعد، عن معدان بن أبي طلحة اليعمري، عن ثوبان فذكره.","grade":"صحيح","chapter_ar":"باب الأمر باتباع الجنائز وفضله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (946). In another narration with him, the Prophet ﷺ was asked about the qīrāṭ and he said: “Like Uḥud.”","chapter_en":"The command to follow funerals and its virtue","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Thawbān, the freed servant of the Messenger of Allah ﷺ, reported that the Messenger of Allah ﷺ said: “Whoever prays over a funeral has one qīrāṭ of reward, and if he is present at its burial, he has two qīrāṭs, and a qīrāṭ is like Mount Uḥud.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (946). وفي رواية عنده: سئل النبي ﷺ عن القيراط فقال: (( مثل أحد ))."},{"num":3673,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ: أَنَّهُ مَرَّ بِأَبِي هُرَيْرَةَ وَهُوَ يُحَدِّثُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: مَنْ تَبِعَ جَنَازَةً فَصَلَّى عَلَيْهَا، فَلَهُ قِيرَاطٌ، فَإِنْ شَهِدَ دَفْنَهَا، فَلَهُ قِيرَاطَانِ، الْقِيرَاطُ أَعْظَمُ مِنْ أُحُدٍ فَقَالَ لَهُ ابْنُ عُمَرَ: أَبَا هُرَيْرَةَ انْظُرْ مَا تُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ!! فَقَامَ إِلَيْهِ أَبُو هُرَيْرَةَ، حَتَّى انْطَلَقَ بِهِ إِلَى عَائِشَةَ، فَقَالَ لَهَا: يَا أُمَّ الْمُؤْمِنِينَ، أَنْشُدُكِ بِاللهِ، أَسَمِعْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ تَبِعَ جَنَازَةً فَصَلَّى عَلَيْهَا، فَلَهُ قِيرَاطٌ، فَإِنْ شَهِدَ دَفْنَهَا، فَلَهُ قِيرَاطَانِ؟ فَقَالَتْ: اللهُمَّ نَعَمْ، فَقَالَ أَبُو هُرَيْرَةَ: إِنَّهُ لَمْ يَكُنْ يَشْغَلُنِي عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَرْسُ الْوَدِيِّ، وَلَا صَفْقٌ بِالْأَسْوَاقِ، إِنِّي إِنَّمَا كُنْتُ أَطْلُبُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَلِمَةً يُعَلِّمُنِيهَا، وَأُكْلَةً يُطْعِمُنِيهَا، فَقَالَ لَهُ ابْنُ عُمَرَ: أَنْتَ يَا أَبَا هُرَيْرَةَ كُنْتَ أَلْزَمَنَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَعْلَمَنَا بِحَدِيثِهِ."],"takhrij":"صحيح: رواه الإمام أحمد (4453) عن هُشيم، عن يعلى بن عطاء، عن الوليد بن عبدالرحمن الجرشي، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الأمر باتباع الجنائز وفضله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Aḥmad (4453), and ʿAbd al-Razzāq (6270).","chapter_en":"The command to follow funerals and its virtue","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar reported that he passed by Abū Hurayrah while he was narrating from the Prophet ﷺ that he said: “Whoever follows a funeral and prays over it has one qīrāṭ, and if he is present at its burial, he has two qīrāṭs. A qīrāṭ is greater than Uḥud.” So Ibn ʿUmar said to him: “Abū Hurayrah, be careful about what you narrate from the Messenger of Allah ﷺ.” Then Abū Hurayrah stood up and took him to ʿĀ’ishah and said to her: “O Mother of the Believers, I ask you by Allah, did you hear the Messenger of Allah ﷺ say: ‘Whoever follows a funeral and prays over it has one qīrāṭ, and if he is present at its burial, he has two qīrāṭs’?” She said: “By Allah, yes.” So Abū Hurayrah said: “I was not kept away from the Messenger of Allah ﷺ by planting young palms or bargaining in the markets. I only sought from the Messenger of Allah ﷺ a word he would teach me and a meal he would feed me.” Then Ibn ʿUmar said to him: “You, Abū Hurayrah, were the one among us who stayed closest to the Messenger of Allah ﷺ and knew his hadith best.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (4453)، وعبد الرزاق (6270)."},{"num":3674,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ جَاءَ إِلَى جَنَازَةٍ فَمَشَى مَعَهَا مِنْ أَهْلِهَا حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ انْتَظَرَ حَتَّى تُدْفَنَ، أَوْ يُفْرَغَ مِنْهَا فَلَهُ قِيرَاطَانِ مِثْلُ أُحُدٍ."],"takhrij":"حسن: رواه الإمام أحمد (11218) عن سليمان بن داود، حدثنا وُهيب، عن عمرو بن يحيى الأنصاري.","grade":"حسن","chapter_ar":"باب الأمر باتباع الجنائز وفضله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (11152, 11218), and al-Bazzār in Kashf al-Astār (824).","chapter_en":"The command to follow funerals and its virtue","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that the Messenger of Allah ﷺ said: “Whoever comes to a funeral and walks with it from the family’s place until the funeral prayer is offered has one qīrāṭ. And whoever waits until it is buried, or until it is finished with, has two qīrāṭs like Uḥud.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (11152، 11218)، والبزار في كشف الأستار (824)."},{"num":3675,"demo":false,"sanad":"","matn":["عَنْ أَبِي بُرْدَةَ قَالَ: أَوْصَى أَبُو مُوسَى حِينَ حَضَرَهُ الْمَوْتُ فَقَالَ: إِذَا انْطَلَقْتُمْ بِجِنَازَتِي فَأَسْرِعُوا الْمَشْيَ، وَلَا تُتْبعني بمجمر، وَلَا تَجْعَلُوا فِي لَحْدِي شَيْئًا يَحُولُ بَيْنِي وَبَيْنَ التُّرَابِ، وَلَا تَجْعَلُوا عَلَى قَبْرِي بِنَاءً، وَأُشْهِدُكُمْ أَنِّي برئٌ مِنْ كُلِّ حَالِقَةٍ، أَوْ سَالِقَةٍ، أَوْ خَارِقَةٍ، قَالُوا: أَوْ سمعت فِيهِ شَيْئًا؟ قَالَ: نَعَمْ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. ."],"takhrij":"حسن: رواه الإمام أحمد (19547) عن معتمر بن سليمان التيمي، قال: قرأت على الفُضيل بن ميسرة في حديث أبي حريز، أن أبا بردة حدَّثه قال: أوصي أبو موسى فذكره.","grade":"حسن","chapter_ar":"باب ما يُكره عند حمل الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (19547), Ibn Mājah (1487), authenticated by Ibn Ḥibbān (3150).","chapter_en":"What is disliked when carrying funerals","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Abū Burdah said: Abū Mūsā gave instructions when death came to him. He said: “When you go with my funeral, walk quickly. Do not follow me with a censer. Do not place anything in my burial niche that would come between me and the earth. Do not build anything over my grave. And I make you witnesses that I am free of every woman who shaves her hair, raises her voice in wailing, or tears her clothes.” They said: “Did you hear something about that?” He said: “Yes, from the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3563],"tks":"حسن: رواه الإمام أحمد (19547)، وابن ماجه (1487)، وصححه ابن حبان (3150)."},{"num":3676,"demo":false,"sanad":"","matn":["عَنِ الصُّنَابِحِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَزَالُ أُمَّتِي، - أَوْ هَذِهِ الْأُمَّةُ - فِي مَسَكَةٍ مِنْ دِينِهَا مَا لَمْ يَكِلُوا الْجَنَائِزَ إِلَى أَهْلِهَا."],"takhrij":"صحيح: رواه الحاكم (1371) من طريق أبي بكر بن أبي شيبة، ثنا وكيع، عن الصلت بن بهرام، عن الحارث بن وهب، عن الصنابحي قال: فذكره.","grade":"صحيح","chapter_ar":"باب أن الأمة بخير ما لم يكلوا الجنائز إلى أهلها","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Ḥākim (1371).","chapter_en":"The community remains upon good so long as they do not leave funerals only to the family","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Al-Ṣunābihī said: The Messenger of Allah ﷺ said: “My community — or this community — will continue to hold firmly to its religion so long as they do not leave funerals to the family alone.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (1371)."},{"num":3677,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَسْرِعُوا بِالْجِنَازَةِ، فَإِنْ تَكُ صَالِحَةً فَخَيْرٌ تُقَدِّمُونَهَا {إِلَيْهِ}، وَإِنْ يَكُ سِوَى ذَلِكَ فَشَرٌّ تَضَعُونَهُ عَنْ رِقَابِكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1315)، ومسلم في الجنائز (944) كلاهما من حديث سفيان بن عيينة، قال: حفظناه من الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكر الحديث. ورواه مالك في الجنائز (56) عن نافع، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب الإسراع بالجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1315), Muslim (944).","chapter_en":"Hastening with the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah reported from the Prophet ﷺ that he said: “Hasten with the funeral. If the deceased was righteous, then it is a good to which you are taking him forward. And if it was otherwise, then it is an evil that you are putting down from your necks.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1315)، ومسلم (944)."},{"num":3678,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا وُضِعَتِ الْجِنَازَةُ فَاحْتَمَلَهَا الرِّجَالُ عَلَى أَعْنَاقِهِمْ، فَإِنْ كَانَتْ صَالِحَةً قَالَتْ: قَدِّمُونِي، وَإِنْ كَانَتْ غَيْرَ صَالِحَةٍ قَالَتْ لأَهْلِهَا: يَا وَيْلَهَا، أَين يَذْهَبُونَ بِهَا؟ يَسْمَعُ صَوْتَهَا كُلُّ شيء إِلاَّ الإِنْسَانَ، وَلَوْ سَمِعَ الإِنْسَانُ لصَعِق ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1316) عن عبدالله بن يوسف، حدثنا الليث، حدثنا سعيد، عن أبيه، أنه سمع أبا سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب الإسراع بالجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1316).","chapter_en":"Hastening with the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said: The Prophet ﷺ used to say: “When the funeral is placed and men carry it on their shoulders, if the deceased was righteous it says: ‘Take me forward.’ But if it was not righteous, it says to its people: ‘Woe to it! Where are they taking it?’ Everything hears its voice except the human being, and if the human being heard it, he would collapse.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1316)."},{"num":3679,"demo":false,"sanad":"","matn":["عَنْ عيينة بْنُ عبدالرحمن، عن أَبِيهِ قَالَ: شَهِدْتُ جَنَازَةَ عبدالرحمن بْنِ سَمُرَةَ، وَخَرَجَ زِيَادٌ يَمْشِي بَيْنَ يدي السَّرِيرِ، فَجَعَلَ رِجَالٌ مِنْ أَهْلِ عبدالرحمن وَمَوَالِيهِمْ يَسْتَقْبِلُونَ السَّرِيرَ، وَيَمْشُونَ عَلَى أَعْقَابِهِمْ وَيَقُولُونَ رُويداً رُويداً بَارَكَ اللَّهُ فِيكُمْ فَكَانُوا يَدِبُّونَ دَبيباً حَتَّى إِذَا كُنَّا فِي بَعْضِ طَرِيقِ الْمِرْبَدِ لَحِقَنَا أَبُو بَكْرَةَ عَلَى بَغْلَةٍ، فَلَمَّا رَأَى الَّذِي يَصْنَعُونَ حَمَلَ عَلَيْهِمْ بِبَغْلَتِهِ، وَأَهْوَى إِلَيْهِمْ بِالسَّوْطِ وَقَالَ: خلُّوا فَوَالَّذِي أَكْرَمَ وَجْهَ أَبِي الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِنَّا لَنَكَادُ نَرْمُلُ بِهَا رَمَلاً فَانْبَسَطَ الْقَوْمُ."],"takhrij":"حسن: رواه أبو داود (3183) من طريق خالد بن الحارث، وعيسى بن يونس، والنسائي (1912) من طريق خالد وحده –عن عيينة بن عبدالرحمن به فذكره، واللفظ للنسائي، واختصره أبو داود.","grade":"حسن","chapter_ar":"باب ما جاء أن الماشي يمشي أمام الجنازة وخلفها ويمينها ويسارها، وأن الراكب يكون خلفها","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3183), al-Nasā’ī (1912), Aḥmad (20400).","chapter_en":"What is reported that the walker may walk in front of the funeral, behind it, to its right and left, and that the rider should be behind it","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["ʿUyaynah ibn ʿAbd al-Raḥmān reported from his father: I attended the funeral of ʿAbd al-Raḥmān ibn Samurah, and Ziyād came out walking in front of the bier. Then some men from ʿAbd al-Raḥmān’s family and their freedmen began facing the bier and walking backward, saying: “Slowly, slowly, may Allah bless you.” So they were moving with a crawling pace. Then when we reached part of the road of al-Mirbad, Abū Bakrah caught up with us on a mule. When he saw what they were doing, he drove his mule toward them and swung his whip at them, saying: “Move aside. By the One who honored the face of Abū al-Qāsim ﷺ, I saw us with the Messenger of Allah ﷺ and we were almost moving at a brisk pace with it.” Then the people quickened their pace."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3183)، والنسائي (1912)، والإمام أحمد (20400)."},{"num":3680,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الرَّاكِبُ يَسِيرُ خَلْفَ الْجَنَازَةِ، وَالْمَاشِي يَمْشِي خَلْفَهَا وَأَمَامَهَا، وَعَنْ يَمِينِهَا وَعَنْ يَسَارِهَا قَرِيبًا مِنْهَا، والسِقْطُ يُصَلَّى عَلَيْهِ، ويُدْعى لِوَالِدَيْهِ بِالْمَغْفِرَةِ وَالرَّحْمَةِ ."],"takhrij":"صحيح: رواه أبو داود (3180)، والترمذي (1031)، وابن ماجه (1481، 1507)، والنسائي (1943) كلهم من طرق عن زياد بن جبير بن حية، عن أبيه، عن المغيرة بن شعبة فذكره، واللفظ لأبي داود. قال الترمذي: حسن صحيح .","grade":"صحيح","chapter_ar":"باب ما جاء أن الماشي يمشي أمام الجنازة وخلفها ويمينها ويسارها، وأن الراكب يكون خلفها","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3180), al-Tirmidhī (1031), Ibn Mājah (1481, 1507), al-Nasā’ī (1943).","chapter_en":"What is reported that the walker may walk in front of the funeral, behind it, to its right and left, and that the rider should be behind it","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah reported that the Prophet ﷺ said: “The rider travels behind the funeral, while the walker may walk behind it, in front of it, to its right, and to its left, staying near it. And the miscarried child is prayed over, and supplication is made for its parents for forgiveness and mercy.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3766],"tks":"صحيح: رواه أبو داود (3180)، والترمذي (1031)، وابن ماجه (1481، 1507)، والنسائي (1943)."},{"num":3681,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ:  أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِفَرَسٍ مُعْرَوْرًى، فَرَكِبَهُ حِينَ انْصَرَفَ مِنْ جَِنَازَةِ ابْنِ الدَّحْدَاحِ وَنَحْنُ نَمْشِي حَوْلَهُ.","وفي رواية: صَلَّى رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى ابْنِ الدَّحْدَاحِ، ثُمَّ أُتِيَ بِفَرَسٍ عُرْيٍ فَعَقَلَهُ رَجُلٌ فَرَكِبَهُ، فَجَعَلَ يَتَوَقَّصُ بِهِ، وَنَحْنُ نَتَّبِعُهُ نَسْعَى خَلْفَهُ، قَالَ: فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: إِنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ: كَمْ مِنْ عِذْقٍ مُعَلَّقٍ (أَوْ مُدَلًّى) فِي الْجَنَّةِ لِابْنِ الدَّحْدَاحِ .. أَوَ قَالَ شُعْبَةُ: لِأَبِي الدَّحْدَاحِ ..","وفي رواية: أن النبيّ صلى الله عليه وسلم اتبع جنازة أبي الدحْداح ماشياً، ورجع على فرس."],"takhrij":"صحيح: رواه مسلم في الجنائز (965) من طرق عن وكيع، عن مالك ابن مِغْولٍ، عن سماك بن حربٍ، عن جابر بن سمرة، قال فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الركوب عند الانصراف","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (965). The second narration is also in Muslim, and the third is in al-Tirmidhī (1014).","chapter_en":"Riding when returning from the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Jābir ibn Samurah said: The Prophet ﷺ was brought an unsaddled horse, and he rode it when he returned from the funeral of Ibn al-Daḥdāḥ, while we were walking around him. In another narration: The Messenger of Allah ﷺ prayed over Ibn al-Daḥdāḥ, then an unsaddled horse was brought, and a man held it for him. He rode it, and it began moving quickly while we followed him, hurrying behind him. Then a man from the people said: The Prophet ﷺ said: “How many palm clusters are hanging — or suspended — in Paradise for Ibn al-Daḥdāḥ.” Or Shuʿbah said: “for Abū al-Daḥdāḥ.”","And in another narration: The Prophet ﷺ followed the funeral of Abū al-Daḥdāḥ on foot, and returned on a horse."]},"buhuth":{"en":["The phrase “an unsaddled horse” means a horse without a saddle on it.","The phrase “it began moving quickly” means it moved briskly with short, close steps.","As for “How many palm clusters are hanging in Paradise for Ibn al-Daḥdāḥ,” the word ʿidhq with kasrah means a date-palm cluster-stalk, and with fatḥah it can mean the palm tree itself. Al-Daḥdāḥ refers to a short man below average height. The Prophet ﷺ said this because of a story: an orphan disputed with Abū Lubābah over a palm tree, and the boy cried. So the Prophet ﷺ said to him: “Give it to him, and you will have in exchange for it a palm cluster in Paradise.” He refused. Ibn al-Daḥdāḥ heard this, so he bought it from Abū Lubābah in exchange for an orchard of his own, then asked the Prophet ﷺ: “If I give it to the orphan, will I have a palm cluster in Paradise for it?” He said: “Yes.” So when he did that, the Prophet ﷺ said these words about him.","Other versions of the story were also reported."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (965)، والرواية الثانية أيضا عنده، والرواية الثالثة عند الترمذي (1014)."},{"num":3682,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِدَابَّةٍ وَهُوَ مَعَ الْجَنَازَةِ فَأَبَى أَنْ يَرْكَبَهَا، فَلَمَّا انْصَرَفَ أُتِيَ بِدَابَّةٍ فَرَكِبَ، فَقِيلَ لَهُ: فَقَالَ: إِنَّ الْمَلاَئِكَةَ كَانَتْ تَمْشِي فَلَمْ أَكُنْ لأَرْكَبَ وَهُمْ يَمْشُونَ، فَلَمَّا ذَهَبُوا رَكِبْتُ."],"takhrij":"صحيح: رواه أبو داود (3177) عن يحيى بن موسى البلخي، أخبرنا عبد الرزاق، أخبرنا معمر، عن يحيى بن أبي كثير، عن أبي سلمة بن عبدالرحمن ابن عوف، عن ثوبان قال: فذكره.","grade":"صحيح","chapter_ar":"باب الركوب عند الانصراف","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3177), al-Ḥākim (1314).","chapter_en":"Riding when returning from the funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Thawbān reported that the Messenger of Allah ﷺ was brought a riding animal while he was with a funeral, but he refused to ride it. Then when he returned, a riding animal was brought to him and he rode it. He was asked about that, and he said: “The angels were walking, and I would not ride while they were walking. When they went away, I rode.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3177)، والحاكم (1314)."},{"num":3683,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: نُهِينَا عَنِ اتِّبَاعِ الْجَنَائِزِ، وَلَمْ يُعْزَمْ عَلَيْنَا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1278)، ومسلم في الجنائز (938) كلاهما من طريق حفصة بنت سيرين أم الهُذيل، عن أم عطية ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب نهي النساء عن اتباع الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1278), Muslim (938). In narrations outside the two Ṣaḥīḥ collections: “The Messenger of Allah ﷺ forbade us.”","chapter_en":"Women being prohibited from following funerals","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء عن الميت وحمل الجنازة والقيام لها","group_en":"Compilation of chapters on what is reported about the deceased, carrying the funeral, and standing for it","part_no":13,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["Umm ʿAṭiyyah said: We were prohibited from following funerals, but it was not made strict upon us."]},"buhuth":{"en":["Her statement, “but it was not made strict upon us,” means that the prohibition was not emphasized in the same way as some other prohibitions were emphasized. This indicates that following funerals is disliked for women, but not absolutely forbidden."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1278)، ومسلم (938). وفي غير الصحيحين: (( نهانا رسول الله ﷺ ))."},{"num":3684,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَازِمٍ، قَالَ: شَهِدْتُ حُسَيْنًا حِينَ مَاتَ الْحَسَنُ، وَهُوَ يَدْفَعُ فِي قَفَا سَعِيدِ بْنِ الْعَاصِ، وَهُوَ يَقُولُ: تَقَدَّمْ، فَلَوْلَا السُّنَّةُ مَا قَدَّمْتُكَ، وَسَعِيدٌ أَمِيرٌ عَلَى الْمَدِينَةِ يَوْمَئِذٍ."],"takhrij":"حسن: رواه الطبراني في الكبير (2912) من طريق عبد الرزاق –وهو في مصنفه (6369)، والبزار (1345) من طريق وكيع، كلاهما عن سفيان الثوري، عن سالم بن أبي حفصة، عن أبي حازم قال: فذكره.","grade":"حسن","chapter_ar":"باب من أحق بالصلاة على الميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Kabīr (2/148), ʿAbd al-Razzāq (6369), al-Bazzār (1345).","chapter_en":"Who has the greatest right to lead the prayer over the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abū Ḥāzim said: I was present with al-Ḥusayn when al-Ḥasan died, and he was pushing Saʿīd ibn al-ʿĀṣ from behind, saying: “Step forward. Were it not that this is the Sunnah, I would not have put you forward.” Saʿīd was the governor of Madinah at that time."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (2899)، وعبد الرزاق (6369)، والبزار (1345)."},{"num":3685,"demo":false,"sanad":"","matn":["عَنْ عَطَاءِ بْنِ دِينَارٍ الْهُذَلِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلَاثَةٌ لَا تُقْبَلُ مِنْهُمْ صَلَاةٌ، وَلَا تَصْعَدُ إِلَى السَّمَاءِ، وَلَا تُجَاوِزُ رؤوسهم: رَجُلٌ أَمَّ قَوْمًا وَهُمْ لَهُ كَارِهُونَ، وَرَجُلٌ صَلَّى عَلَى جَنَازَةٍ وَلَمْ يُؤْمَرْ، وَامْرَأَةٌ دَعَاهَا زَوْجُهَا مِنَ اللَّيْلِ، فَأَبَتْ عَلَيْهِ . وَهَذَا مرسل، وعن أنس يرفعه مثله."],"takhrij":"حسن من حديث أنس: رواه ابن خزيمة (1518) عن عيسى بن إبراهيم، حدثنا ابن وهب، عن ابن لهيعة وسعيد بن أبي أيوب، عن عطاء بن دينار الهذلي، فذكره.","grade":"حسن","chapter_ar":"باب من صلى على جنازة ولم يؤمر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan through the narration of Anas: Ibn Khuzaymah (1518).","chapter_en":"One who prays over a funeral without being appointed","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["ʿAṭā’ ibn Dīnār al-Hudhalī reported that the Messenger of Allah ﷺ said: “There are three whose prayer is not accepted, does not rise to the heaven, and does not go beyond their heads: a man who leads people in prayer while they dislike him, a man who prays over a funeral without being appointed, and a woman whose husband calls her at night and she refuses him.” This chain is mursal, and a similar wording is also narrated from Anas as a marfūʿ report."]},"buhuth":{"en":["The phrase “without being appointed” means without authorization from the ruler, or from the heirs of the deceased when the people do not have a regular appointed imam."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (1518)."},{"num":3686,"demo":false,"sanad":"","matn":["عن سَمُرَةَ بْنِ جندب رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّيْتُ وَرَاءَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى امْرَأَةٍ مَاتَتْ فِي نِفَاسِهَا، فَقَامَ عَلَيْهَا وَسَطَهَا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1332) عن عمران بن ميسرة، حدّثنا عبد الوارث، حدثنا حسين، عن ابن بُريدة، حدثنا سمرة بن جندب فذكره، ورواه عن مسدد، عن يزيد بن زريع، عن حسين (وهو ابن ذكوان، بأن المرأة ماتت في نفاسها (1331)، ورواه مسلم في الجنائز (964) عن يحيى ابن يحيى التميمي، أخبرنا عبد الوارث بن سعيد بإسناده، وسمَّى المرأة بأنها أم كعب، ماتت وهي نُفَسَاء.","grade":"متفق عليه","chapter_ar":"باب أن الإمام يقف في الجنازة إذا كانت للمرأة في وسطها، وإذا كانت للرجل عند رأسه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1332), Muslim (964).","chapter_en":"The imam stands at the middle of the woman’s funeral and at the head of the man’s funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Samurah ibn Jundub said: I prayed behind the Prophet ﷺ over a woman who died in childbirth, and he stood opposite her middle."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1332)، ومسلم (964)."},{"num":3687,"demo":false,"sanad":"","matn":["عَنْ أَبِي غَالِبٍ، قَالَ: صَلَّيْتُ مَعَ أَنَسِ بْنِ مَالِكٍ عَلَى جَنَازَةِ رَجُلٍ، فَقَامَ حِيَالَ رَأْسِهِ، ثُمَّ جَاءُوا بِجَنَازَةِ امْرَأَةٍ مِنْ قُرَيْشٍ فَقَالُوا: يَا أَبَا حَمْزَةَ! صَلِّ عَلَيْهَا. فَقَامَ حِيَالَ وَسَطِ السَّرِيرِ. فَقَالَ لَهُ الْعَلاَءُ بْنُ زِيَادٍ: هَكَذَا رَأَيْتَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ عَلَى الْجَنَازَةِ مُقَامَكَ مِنْهَا، وَمِنَ الرَّجُلِ مُقَامَكَ مِنْهُ؟ قَالَ: نَعَمْ. فَلَمَّا فَرَغَ قَالَ: احْفَظُوا."],"takhrij":"صحيح: رواه الترمذي (1034)، وابن ماجه (1494) كلاهما من طريق سعيد بن عامر، عن همام، عن أبي غالب فذكره.","grade":"صحيح","chapter_ar":"باب أن الإمام يقف في الجنازة إذا كانت للمرأة في وسطها، وإذا كانت للرجل عند رأسه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Tirmidhī (1034), Ibn Mājah (1494).","chapter_en":"The imam stands at the middle of the woman’s funeral and at the head of the man’s funeral","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abū Ghālib said: I prayed with Anas ibn Mālik over the funeral of a man, and he stood opposite his head. Then they brought the funeral of a woman from Quraysh and said: “O Abū Ḥamzah, pray over her.” So he stood opposite the middle of the bier. Then al-ʿAlā’ ibn Ziyād said to him: “Is this how you saw the Messenger of Allah ﷺ stand for the funeral, in the same place where you stood for her, and for the man in the same place where you stood for him?” He said: “Yes.” Then when he finished he said: “Memorize this.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1034)، وابن ماجه (1494)."},{"num":3688,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، أَنَّ ابْنَ عُمَرَ صَلَّى عَلَى تِسْعِ جَنَائِزَ جَمِيعًا، فَجَعَلَ الرِّجَال يَلُونَ الْإِمَامَ، وَالنِّسَاءَ يلين الْقِبْلَةَ، فصفَّهن صفاً وَاحِدًا، ووُضعتْ جِنَازَةُ أُمِّ كُلْثُومٍ بنت عَليٍّ امْرَأَةِ عُمَرَ بْنِ الْخَطَّابِ وَابْنٍ لَهَا يُقَالُ لَهُ: زَيْدٌ وُضِعا جَمِيعًا، وَالْإِمَامُ يَوْمَئِذٍ سَعِيدُ بْنُ الْعَاصِ، وَفِي النَّاسِ ابْنُ عُمَرَ وَأَبُو هُرَيْرَةَ وَأَبُو سَعِيد وَأَبُو قَتَادَةَ، فَوُضِعَ الْغُلَامُ مِمَّا يَلِي الْإِمَامَ، فَقَالَ رَجُلٌ: فَأَنْكَرْتُ ذَلِكَ، فَنَظَرتُ إِلَى ابْنِ عَبَّاسٍ وَأَبِي هُرَيْرَةَ وَأَبِي سَعِيدٍ وَأَبِي قَتَادَةَ، فَقُلْتُ: مَا هَذَا؟ قَالُوا: هِيَ السُّنَّةُ."],"takhrij":"صحيح: رواه النسائي (1978) عن محمد بن رافع، قال: أنبانا عبد الرزاق، وهو في المصنف (6337) قال: أنبانا ابن جريج، قال: سمعت نافعاً يزعم أن ابن عمر صلَّى على تسع جنائز فذكره.","grade":"صحيح","chapter_ar":"باب في ترتيب وضع الجنائز من الرجال والنساء والأطفال إذا اجتمعوا","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1978), ʿAbd al-Razzāq (6337).","chapter_en":"The arrangement of male, female, and child funerals when they are gathered together","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Nāfiʿ reported that Ibn ʿUmar prayed over nine funerals together. He placed the men nearest to the imam and the women nearest to the qiblah, arranging them in a single row. The funeral of Umm Kulthūm bint ʿAlī, the wife of ʿUmar ibn al-Khaṭṭāb, and a son of hers named Zayd were placed together. The imam that day was Saʿīd ibn al-ʿĀṣ, and among the people were Ibn ʿUmar, Abū Hurayrah, Abū Saʿīd, and Abū Qatādah. The boy was placed nearest to the imam. A man said: I found that strange, so I looked at Ibn ʿAbbās, Abū Hurayrah, Abū Saʿīd, and Abū Qatādah and asked: “What is this?” They said: “This is the Sunnah.”"]},"buhuth":{"en":["The phrase “the imam that day was Saʿīd ibn al-ʿĀṣ” means that he was the governor.","Their statement, “This is the Sunnah,” carries the ruling of a report traced back to the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1978)، وعبد الرزاق (6337)."},{"num":3689,"demo":false,"sanad":"","matn":["عن عَمَّارِ مولى الحارث بْنِ نوفل، أَنَّهُ شَهِدَ جَنَازَةَ أُمِّ كُلْثُومٍ وَابْنِهَا، فَجُعِلَ الْغُلاَمُ مِمَّا يَلِي الإِمَامَ، فَأَنْكَرْتُ ذَلِكَ، وَفِي الْقَوْمِ ابْنُ عَبَّاسٍ وَأَبُو سَعِيدٍ الْخُدْرِيُّ وَأَبُو قَتَادَةَ وَأَبُو هُرَيْرَةَ فَقَالُوا: هَذِهِ السُّنَّةُ."],"takhrij":"صحيح: رواه أبو داود (3193) عن يزيد بن خالد بن موهب الرملي، حدثنا ابن وهب، عن ابن جريج، عن يحيى بن صبيح قال: حدثني عمار مولى الحارث بن نفيل فذكر الحديث، ورواه النسائي (1977) من وجه آخر عن عمار.","grade":"صحيح","chapter_ar":"باب في ترتيب وضع الجنائز من الرجال والنساء والأطفال إذا اجتمعوا","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3193), al-Nasā’ī (1977).","chapter_en":"The arrangement of male, female, and child funerals when they are gathered together","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["ʿAmmār, the freedman of al-Ḥārith ibn Nawfal, reported that he attended the funeral of Umm Kulthūm and her son. The boy was placed nearest to the imam, and I found that strange. Among the people were Ibn ʿAbbās, Abū Saʿīd al-Khudrī, Abū Qatādah, and Abū Hurayrah, and they said: “This is the Sunnah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3193)، والنسائي (1977)."},{"num":3690,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُصَلَّى عَلَى الْجَنَائِزِ بَيْنَ الْقُبُورِ."],"takhrij":"حسن: رواه الطبراني في الأوسط- مجمع البحرين (1297) عن محمد بن عبدالله الحضرمي، عن حسين بن يزيد الطحان، عن حفص بن غياث، عن عاصم الأحوال، عن محمد بن سيرين، عن أنس بن مالك فذكره، وعنه رواه الضياء المقدسي في المختارة (2594) ورواه البزار كشف الأستار (442) من وجه آخر عن حفص بن غياث، عن الأشعث، عن الحسن، عن أنس أن النبي صلى الله عليه وسلم نهى عن الصلاة بين القبور.","grade":"حسن","chapter_ar":"باب النهي عن الصلاة على الجنازة بين القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Awsaṭ — Majmaʿ al-Baḥrayn (1297).","chapter_en":"The prohibition of praying over the funeral between graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ forbade offering the funeral prayer between graves."]},"buhuth":{"en":["Al-Bazzār also narrated in Kashf al-Astār (442), from Anas, that the Prophet ﷺ forbade praying between graves."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (1297)."},{"num":3691,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ عبدالله بن الزُّبَيْرِ، يُحَدِّثُ عَنْ عَائِشَةَ: أَنَّهَا لَمَّا تُوُفِّيَ سَعْدُ بْنُ أَبِي وقَّاص أَرْسَلَ أَزْوَاجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَمُرُّوا بِجَِنَازَتِهِ فِي الْمَسْجِدِ، فَيُصَلِّينَ عَلَيْهِ. فَفَعَلُوا. فوُقِفَ بِهِ عَلَى حُجَرِهُنَّ يُصَلِّين عَلَيْهِ. وأُخْرج بِهِ مِنْ بَابِ الْجَنَائِزِ الَّذِي كَانَ إِلَى الْمَقَاعِدِ. فبلَغَهُنَّ أنَّ النَّاسَ عَابُوا ذَلِكَ. وَقَالُوا: مَا كَانَتِ الْجَنَائِزُ يُدْخَلُ بِهَا الْمَسْجِدَ. فَبَلَغَ ذَلِكَ عَائِشَةَ فَقَالَتْ: مَا أَسْرَعَ النَّاسَ إِلَى أَنْ يَعِيبُوا مَا لَا عِلْمَ لَهُمْ بِهِ! عَابُوا عَلَيْنَا أَنْ يُمَرَّ بِجَِنَازَةٍ فِي الْمَسْجِدِ! وَمَا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى سُهَيْلِ بن بَيْضَاءَ إِلَّا فِي جَوْفِ الْمَسْجِدِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (973) من طرق عن عبد الواحد بن حمزة، عن عباد بن عبدالله بن الزبير به مثله. وهذه رواية موسى بن عقبة عن عبد الواحد، ورواه غيره عن عبد الواحد مختصراً.","grade":"صحيح","chapter_ar":"باب الصلاة على الجنازة في المسجد، وجوازها للنساء","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (973).","chapter_en":"The funeral prayer in the mosque, and its permissibility for women","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["ʿAbbād ibn ʿAbdullāh ibn al-Zubayr narrated from ʿĀ’ishah that when Saʿd ibn Abī Waqqāṣ died, the wives of the Prophet ﷺ sent word that his funeral should be brought through the mosque so that they could pray over him. That was done. He was stopped near their rooms so they could pray over him, and then he was taken out through the funeral gate that was near the sitting area. Then it reached them that people had criticized this and said: “Funerals were not brought into the mosque.” When that reached ʿĀ’ishah, she said: “How quick people are to criticize what they have no knowledge of. They criticized us for bringing a funeral through the mosque, while the Messenger of Allah ﷺ did not pray over Suhayl ibn Bayḍā’ except inside the mosque.”"]},"buhuth":{"en":["It is also narrated that when Saʿd ibn Abī Waqqāṣ died, ʿĀ’ishah said: “Bring him into the mosque so I may pray over him.” People objected to that, and she said: “By Allah, the Messenger of Allah ﷺ prayed in the mosque over the two sons of Bayḍā’: Suhayl and his brother.”","Muslim said: Suhayl ibn Daʿd was the son of al-Bayḍā’, and his mother was Bayḍā’.","Al-Nawawī said: “The sons of Bayḍā’ were three brothers: Sahl, Suhayl, and Ṣafwān. Their mother was Bayḍā’, whose name was Daʿd; ‘Bayḍā’’ is a description. Their father was Wahb ibn Rabīʿah al-Qurashī al-Fihrī. Suhayl was an early Muslim. He migrated to Abyssinia, then returned to Makkah, then migrated to Madinah. He witnessed Badr and other events, and died in the ninth year after Hijrah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (973)."},{"num":3692,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أنّ الْيَهُودَ جَاءُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ مِنْهُمْ وَامْرَأَةٍ زَنَيَا، فَأَمَرَ بِهِمَا فَرُجِما قَرِيبًا مِنْ مَوْضِعِ الْجَنَائِزِ عِنْدَ الْمَسْجِدِ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1329) عن إبراهيم بن المنذر، قال: حدثنا أبو ضمرة، حدثنا موسى بن عقبة، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على الجنائز في المكان المُعَدّ خارج المسجد","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1329).","chapter_en":"Praying over funerals in the designated place outside the mosque","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar reported that the Jews brought to the Prophet ﷺ a man and a woman from among them who had committed adultery, so he ordered that they be stoned near the place where the funeral prayers were offered beside the mosque."]},"buhuth":{"en":["Regarding the phrase “the place of funerals near the mosque,” al-Ḥāfiẓ said in al-Fatḥ (3/199): “Ibn Baṭṭāl related from Ibn Ḥabīb that the funeral prayer area was attached to the Prophet’s Mosque on the eastern side.”","And he said elsewhere (12/129): “The muṣallā was the place where the Eid prayer and funeral prayers used to be performed, and it was on the side of Baqīʿ al-Gharqad.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1329)."},{"num":3693,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَعَى النَّجَاشِيَّ فِي الْيَوْمِ الَّذِي مَاتَ فِيهِ، خَرَجَ إِلَى الْمُصَلَّى، فَصَفَّ بِهِمْ وَكَبَّرَ أَرْبَعًا."],"takhrij":"متفق عليه: رواه مالك في الجنائز (14) عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة فذكره. ورواه البخاري في الجنائز (1245)، ومسلم في الجنائز (951) كلاهما من طريق به مثله.","grade":"متفق عليه","chapter_ar":"باب الصلاة على الجنائز في المكان المُعَدّ خارج المسجد","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (14), al-Bukhārī (1245), Muslim (951).","chapter_en":"Praying over funerals in the designated place outside the mosque","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ announced the death of al-Najāshī on the day he died, then went out to the prayer place, lined the people up, and said four takbīrs."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3536],"tks":"متفق عليه: رواه مالك (14)، والبخاري (1245)، ومسلم (951)."},{"num":3694,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: مَاتَ رَجُلٌ، فَغَسَّلْنَاهُ، وَكَفَّنَّاهُ، وَحَنَّطْنَاهُ، وَوَضَعْنَاهُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَيْثُ تُوضَعُ الْجَنَائِزُ عِنْدَ مَقَامِ جِبْرِيلَ، ثُمَّ آذَنَّا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالصَّلَاةِ عَلَيْهِ، فَجَاءَ مَعَنَا."],"takhrij":"حسن: رواه الإمام أحمد (14536)، والحاكم (2346) كلاهما من حديث عبدالله بن محمد بن عقيل، عن جابر فذكر الحديث بطوله وسيأتي في باب لا يصلي الإمام على من عليه دين حتى يقضى عنه كاملاً.","grade":"حسن","chapter_ar":"باب الصلاة على الجنائز في المكان المُعَدّ خارج المسجد","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (14536), al-Ḥākim (2346).","chapter_en":"Praying over funerals in the designated place outside the mosque","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Jābir said: A man died, so we washed him, shrouded him, perfumed him, and placed him for the Messenger of Allah ﷺ where funerals were placed near the station of Jibrīl. Then we informed the Messenger of Allah ﷺ so that he could pray over him… then he mentioned the rest of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (14536)، والحاكم (2346)."},{"num":3695,"demo":false,"sanad":"","matn":["عن جابر بْنِ عبدالله رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَدْ تُوُفِّيَ الْيَوْمَ رَجُلٌ صَالِحٌ مِنَ الْحَبَشِ، فَهَلُمَّ فَصَلُّوا عَلَيْهِ. قَالَ: فَصَفَفْنَا، فَصَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِ وَنَحْنُ صُفُوفٌ.","قَالَ أَبُو الزُّبَيْرِ، عَنْ جَابِرٍ: كُنْتُ فِي الصَّفِّ الثَّانِي."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1320)، ومسلم في الجنائز (951) كلاهما من حديث ابن جريج، قال: أخبرني عطاء، أنه سمع جابر بن عبدالله فذكر الحديث، واللفظ للبخاري. ولفظ مسلم مختصر.","grade":"متفق عليه","chapter_ar":"باب الصفوف على الجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1320), Muslim (951), and this is the wording of al-Bukhārī.","chapter_en":"Rows in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Prophet ﷺ said: “Today a righteous man from Abyssinia has died, so come and pray over him.” He said: So we formed rows, and the Prophet ﷺ prayed while we stood in rows behind him. Abū al-Zubayr narrated from Jābir: I was in the second row."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1320)، ومسلم (951)، واللفظ للبخاري."},{"num":3696,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِقَبْرٍ قَدْ دُفِنَ لَيْلاً فَقَالَ: مَتَى دُفِنَ هَذَا. قَالُوا: الْبَارِحَةَ. قَالَ: أَفَلاَ آذَنْتُمُونِي. قَالُوا: دَفَنَّاهُ فِي ظُلْمَةِ اللَّيْلِ، فَكَرِهْنَا أَنْ نُوقِظَكَ. فَقَامَ فَصَفَفْنَا خَلْفَهُ.","قَالَ ابْنُ عَبَّاسٍ: وَأَنَا فِيهِمْ فَصَلَّى عَلَيْهِ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1321) عن موسى بن إسماعيل، ثنا عبد الواحد، ثنا الشيباني، عن عامر، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب صفوف الصبيان مع الرجال في الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1321).","chapter_en":"Rows of boys with the men in funeral prayers","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the Messenger of Allah ﷺ passed by the grave of a deceased person who had been buried during the night and said: “When was this one buried?” They said: “Last night.” He said: “Why did you not inform me?” They said: “We buried him in the darkness of the night, and we disliked waking you.” So he stood, and we formed rows behind him.","Ibn ʿAbbās said: And I was among them, and he prayed over him."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1321)."},{"num":3697,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن أَبِي طَلْحَةَ أَنَّ أَبَا طَلْحَةَ دَعَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عُمَيْرِ بْنِ أَبِي طَلْحَةَ حِينَ تُوُفِّيَ، فَأَتَاهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى عَلَيْهِ فِي مَنْزِلِهِ، فَتَقَدَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ أَبُو طَلْحَةَ وَرَاءَهُ، وَأُمُّ سُلَيْمٍ وَرَاءَ أَبِي طَلْحَةَ، وَلَمْ يَكُنْ مَعَهُمْ غَيْرُهُمْ."],"takhrij":"حسن: رواه البيهقي (6908) من طريق عمارة بن غزية، عن إسحاق بن عبدالله بن أبي طلحة، عن أبيه، أن أبا طلحة فذكره.","grade":"حسن","chapter_ar":"باب أقل عدد ورد فيمن صلى على جنازة فوقعت بهم الكفاية","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bayhaqī (4/30), and al-Ṭabarānī in al-Kabīr.","chapter_en":"The smallest number reported for a funeral prayer that fulfilled the communal duty","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn Abī Ṭalḥah reported that Abū Ṭalḥah invited the Messenger of Allah ﷺ to come to ʿUmayr ibn Abī Ṭalḥah when he died. The Messenger of Allah ﷺ came to them and prayed over him in their home. The Messenger of Allah ﷺ stood in front, Abū Ṭalḥah stood behind him, and Umm Sulaym stood behind Abū Ṭalḥah, and there was no one else with them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (6908)، والطبراني في الكبير."},{"num":3698,"demo":false,"sanad":"","matn":["عَنْ أَبِي عَسِيبٍ، أَوْ أَبِي عَسِيمٍ، قَالَ بَهْزٌ: إِنَّهُ شَهِدَ الصَّلَاةَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالُوا: كَيْفَ نُصَلِّي عَلَيْهِ؟ قَالَ: ادْخُلُوا أَرْسَالًا أَرْسَالًا، قَالَ: فَكَانُوا يَدْخُلُونَ مِنْ هَذَا الْبَابِ، فَيُصَلُّونَ عَلَيْهِ، ثُمَّ يَخْرُجُونَ مِنَ الْبَابِ الْآخَرِ، قَالَ: فَلَمَّا وُضِعَ فِي لَحْدِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ الْمُغِيرَةُ: قَدْ بَقِيَ مِنْ رِجْلَيْهِ شَيْءٌ لَمْ يُصْلِحُوهُ، قَالُوا: فَادْخُلْ فَأَصْلِحْهُ، فَدَخَلَ، وَأَدْخَلَ يَدَهُ، فَمَسَّ قَدَمَيْهِ، فَقَالَ: أَهِيلُوا عَلَيَّ التُّرَابَ، فَأَهَالُوا عَلَيْهِ التُّرَابَ، حَتَّى بَلَغَ أَنْصَافَ سَاقَيْهِ، ثُمَّ خَرَجَ، فَكَانَ يَقُولُ: أَنَا أَحْدَثُكُمْ عَهْدًا بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أحمد (20766) عن بهز وأبي كامل، قالا: حدثنا حماد ابن سلمة، عن أبي عمران –يعني الجَوْني، عن أبي عَسيب أو أبي عسيم فذكره.","grade":"صحيح","chapter_ar":"باب الجماعة يصلون على الجنازة أرسالاً","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Aḥmad (20766).","chapter_en":"People praying over the funeral in groups, one after another","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Abū ʿAsīb, or Abū ʿAsīm — as Bahz said — reported that he witnessed the prayer over the Messenger of Allah ﷺ. They said: “How shall we pray over him?” He said: “Enter in groups, one group after another.” So they would enter through this door, pray over him, then leave through the other door. Then when he ﷺ was placed in his burial niche, al-Mughīrah said: “Something of his feet was still left not properly arranged.” They said: “Then go in and fix it.” So he entered and put in his hand and touched his feet, then said: “Pour the soil over me.” So they poured soil over him until it reached the middle of his shins. Then he came out and used to say: “I am the one among you whose contact with the Messenger of Allah ﷺ is the most recent.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9374],"tks":"صحيح: رواه أحمد (20766)."},{"num":3699,"demo":false,"sanad":"","matn":["عَنْ سَالِمِ بْنِ عُبَيْدٍ، وَكَانَ مِنْ أَصْحَابِ الصُّفَّةِ، قَالَ: دَخَلَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ مَاتَ، ثُمَّ خَرَجَ، فَقِيلَ لَهُ: تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: نَعَمْ، فَعَلِمُوا أَنَّهُ كَمَا قَالَ، قِيلَ: وَيُصَلَّى عَلَيْهِ، وَكَيْفَ يُصَلَّى عَلَيْهِ، قَالَ: يَجِيئُونَ عُصْبًا عُصْبًا فَيُصَلُّونَ، فَعَلِمُوا أَنَّهُ كَمَا قَالَ، فَقَالُوا: هَلْ يُدْفَنُ؟ وَأَيْنَ؟ فَقَالَ: حَيْثُ قَبَضَ اللهُ رُوحَهَ، فَإِنَّهُ لَمْ يَقْبِضِ اللَّهُ رُوحَهَ إِلَّا فِي مَكَانٍ طَيِّبٍ، فَعَلِمُوا أَنَّهُ كَمَا قَالَ."],"takhrij":"صحيح: رواه البيهقي (6906) من طريق يونس بن بكير، عن سلمة بن نُبيط، عن أبيه نُبيط بن شريط الأشجعي، عن سالم بن عبيد فذكره.","grade":"صحيح","chapter_ar":"باب الجماعة يصلون على الجنازة أرسالاً","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bayhaqī (4/30), al-Tirmidhī in al-Shamā’il (379), Ibn Mājah (1234).","chapter_en":"People praying over the funeral in groups, one after another","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Sālim ibn ʿUbayd, who was one of the people of al-Ṣuffah, said: Abū Bakr entered upon the Messenger of Allah ﷺ when he died, then came out. It was said to him: “Has the Messenger of Allah ﷺ died?” He said: “Yes.” So they knew it was as he said. Then it was said: “Prayer should be offered over him — but how should it be offered?” He said: “They should come in groups and pray.” So they knew it was as he said. Then they said: “Should he be buried? And where?” He said: “Where Allah took his soul, for Allah only takes the soul of a prophet in a pure place.” So they knew it was as he said."]},"buhuth":{"en":["Ibn ʿAbbās said: When prayer was offered over the Messenger of Allah ﷺ, the men were brought in and they prayed over him without an imam, group after group, until they finished. Then the women were brought in and they prayed over him. Then the children were brought in and they prayed over him. Then the servants were brought in and they prayed over him in groups. No one led them in prayer over the Messenger of Allah ﷺ.","Al-Shāfiʿī said: That was because of the greatness of the matter of the Messenger of Allah ﷺ — may my father and mother be sacrificed for him — and because they wished that no single person should take the position of imam in the prayer over him, so they prayed over him again and again. Al-Bayhaqī mentioned this."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9375],"tks":"صحيح: رواه البيهقي (6906)، والترمذي في الشمائل (379)، وابن ماجه (1234)."},{"num":3700,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى أَصْحَمَةَ النَّجَاشِيِّ فَكَبَّرَ أَرْبَعًا."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1334)، ومسلم في الجنائز (952) كلاهما من حديث سَليم بن حَيَّان، حدثنا سعيد بن ميناء، عن جابر ابن عبدالله فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أربع تكبيرات على الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1334), Muslim (952).","chapter_en":"What is reported about four takbīrs in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Prophet ﷺ prayed over Aṣḥamah al-Najāshī and said four takbīrs."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1334)، ومسلم (952)."},{"num":3701,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَعَى لِلنَّاسِ النَّجَاشِيَّ فِي الْيَوْمِ الَّذِي مَاتَ فِيهِ، فَخَرَجَ بِهِمْ إِلَى الْمُصَلَّى، وَكَبَّرَ أَرْبَعَ تَكْبِيرَاتٍ."],"takhrij":"متفق عليه: رواه مالك في الجنائز (14) عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة فذكره. ورواه البخاري في الجنائز (1245) عن إسماعيل، ومسلم في الجنائز (951) عن يحيى بن يحيى –كلاهما عن مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أربع تكبيرات على الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (14), al-Bukhārī (1245), Muslim (951).","chapter_en":"What is reported about four takbīrs in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ announced the death of al-Najāshī to the people on the day he died, went out with them to the prayer place, lined them up, and said four takbīrs."]}},"tuhfa":{},"full":1,"rep":[3722],"tks":"متفق عليه: رواه مالك (14)، والبخاري (1245)، ومسلم (951)."},{"num":3702,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى جِنَازَةٍ فكبَّر عَلَيْهَا أَرْبَعًا، ثُمَّ أَتَى قَبْرَ الْمَيِّتِ فحثا عَلَيْهِ مِنْ قِبَلِ رَأْسِهِ ثَلاَثًا."],"takhrij":"حسن: رواه ابن ماجه (1565) عن العباس بن الوليد، قال: حدثني يحيى ابن صالح، قال: حدثنا سلمة بن كلثوم، قال: حدثنا الأوزاعي، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة فذكر الحديث غير أنه لم يذكر فكبَّر عليها أربعاً وإنما رواه المِزِّي في ترجمه سلمة بن كلثوم (2450) بإسناده عن أبي بكر عبدالله بن أبي داود، قال: حدثنا العباس بن الوليد بن صُبح الخلال بإسناده.","grade":"حسن","chapter_ar":"باب ما جاء في أربع تكبيرات على الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (1565), and al-Mizzī in Tahdhīb al-Kamāl under the biography of Salamah ibn Kulthūm (2450).","chapter_en":"What is reported about four takbīrs in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ prayed over a funeral and said four takbīrs over it, then came to the grave of the deceased and threw three handfuls of soil onto it from the direction of its head."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1565)، والمزي في تهذيبه في ترجمة سلمة بن كلثوم (2450)."},{"num":3703,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى النَّجَاشِيِّ فَكَبَّرَ أَرْبَعًا."],"takhrij":"حسن: رواه ابن ماجه (1538) عن سهل بن أبي سهل، قال: حدثنا مكي بن إبراهيم أبو السكن، عن مالك، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أربع تكبيرات على الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Mājah (1538).","chapter_en":"What is reported about four takbīrs in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar reported that the Prophet ﷺ prayed over al-Najāshī and said four takbīrs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1538)."},{"num":3704,"demo":false,"sanad":"","matn":["عَنِ الشَّعْبِيِّ، قَالَ: أَخْبَرَنِي مَنْ، شَهِدَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ أَتَى عَلَى قَبْرٍ مَنْبُوذٍ فَصَفَّهُمْ وَكَبَّرَ أَرْبَعًا. قُلْتُ مَنْ حَدَّثَكَ قَالَ ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا."],"takhrij":"صحيح: رواه البخاري في الجنائز (1319) عن مسلم، (وهو ابن إبراهيم) حدثنا شعبة، حدثنا الشيباني، عن الشعبي فذكره، وسيأتي مفصلاً.","grade":"صحيح","chapter_ar":"باب ما جاء في أربع تكبيرات على الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1319).","chapter_en":"What is reported about four takbīrs in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Al-Shaʿbī said: Someone who witnessed the Prophet ﷺ told me that he came to a grave that was separate from the other graves, lined the people up, and said four takbīrs. I said: “O Abū ʿAmr, who told you this?” He said: Ibn ʿAbbās, may Allah be pleased with them both."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1319)."},{"num":3705,"demo":false,"sanad":"","matn":["عَنْ يَزِيدَ بْنِ ثَابِتٍ، وَكَانَ، أَكْبَرَ مِنْ زَيْدٍ، قَالَ: خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا وَرَدَ الْبَقِيعَ فَإِذَا هُوَ بِقَبْرٍ جَدِيدٍ فَسَأَلَ عَنْهُ فَقَالُوا: فُلاَنَةُ. قَالَ: فَعَرَفَهَا وَقَالَ: أَلاَ آذَنْتُمُونِي بِهَا. قَالُوا: كُنْتَ قَائِلاً صَائِمًا، فَكَرِهْنَا أَنْ نُؤْذِيَكَ. قَالَ: فَلاَ تَفْعَلُوا، لاَ أَعْرِفَنَّ مَا مَاتَ فِيكُمْ مَيِّتٌ، مَا كُنْتُ بَيْنَ أَظْهُرِكُمْ إِلاَّ آذَنْتُمُونِي بِهِ، فَإِنَّ صَلاَتِي عَلَيْهِ لَهُ رَحْمَةٌ. ثُمَّ أَتَى الْقَبْرَ، فَصَفَّنَا خَلْفَهُ، فَكَبَّرَ عَلَيْهِ أَرْبَعًا."],"takhrij":"صحيح: رواه النسائي (2022)، وابن ماجه (1528) كلاهما من حديث عثمان بن حكيم الأنصاري، عن خارجة بن زيد بن ثابت، عن عمه يزيد بن ثابت فذكره،","grade":"صحيح","chapter_ar":"باب ما جاء في أربع تكبيرات على الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (2022), Ibn Mājah (1528).","chapter_en":"What is reported about four takbīrs in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Yazīd ibn Thābit, who was older than Zayd, said: We went out with the Prophet ﷺ, and when we came to al-Baqīʿ, there was a fresh grave there. He asked about it and they said: “It is so-and-so.” He recognized who she was and said: “Why did you not inform me about her?” They said: “You were taking a nap and fasting, so we disliked disturbing you.” He said: “Do not do that. Let me definitely know whenever anyone among you dies, as long as I am among you. My prayer over him is mercy for him.” Then he came to the grave, we formed rows behind him, and he said four takbīrs over it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3733],"tks":"صحيح: رواه النسائي (2022)، وابن ماجه (1528)."},{"num":3706,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سهل بْنِ حُنَيْفٍ أَنَّهُ قَالَ: اشْتَكَتِ امْرَأَةٌ بِالْعَوَالِي مِسْكِينَةٌ، فَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْأَلُهُمْ عَنْهَا، وَقَالَ: إِنْ مَاتَتْ فَلاَ تَدْفِنُوهَا حَتَّى أُصَلِّيَ عَلَيْهَا، فَتُوُفِّيَتْ فجاؤا بِهَا إِلَى الْمَدِينَةِ بَعْدَ الْعَتَمَةِ، فَوَجَدُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ نَامَ، فَكَرِهُوا أَنْ يُوقِظُوهُ، فَصَلُّوا عَلَيْهَا وَدَفَنُوهَا بِبَقِيعِ الْغَرْقَدِ، فَلَمَّا أَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جاؤا فَسَأَلَهُمْ عَنْهَا، فَقَالُوا: قَدْ دُفنتْ يَا رَسُولَ اللَّهِ، وَقَدْ جِئْنَاكَ فَوَجَدْنَاكَ نَائِمًا فَكَرِهْنَا أَنْ نُوقِظَكَ، قَالَ: فَانْطَلِقُوا فَانْطَلَقَ يَمْشِي، وَمَشَوْا مَعَهُ حَتَّى أرَوْه قَبْرَهَا، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَفُّوا وَرَاءَهُ فَصَلَّى عَلَيْهَا وكبَّر أَرْبَعًا."],"takhrij":"صحيح: رواه النسائي (1969) عن يونس بن عبد الأعلى، قال: أنبانا ابن وهب، قال: حدثني يونس، عن ابن شهاب، قال: أخبرني أبو أمامة بن سهل فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أربع تكبيرات على الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1969).","chapter_en":"What is reported about four takbīrs in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Abū Umāmah ibn Sahl ibn Ḥunayf said: A poor woman from al-ʿAwālī became ill, and the Prophet ﷺ used to ask about her. He said: “If she dies, do not bury her until I pray over her.” She then died, and they brought her to Madinah after the night prayer, but they found the Messenger of Allah ﷺ asleep. They disliked waking him, so they prayed over her and buried her in Baqīʿ al-Gharqad. When morning came, they came to the Messenger of Allah ﷺ and he asked them about her. They said: “She has been buried, O Messenger of Allah ﷺ. We came to you but found you asleep, and we disliked waking you.” He said: “Let us go.” So he went walking, and they walked with him until they showed him her grave. Then the Messenger of Allah ﷺ stood, they formed rows behind him, and he prayed over her and said four takbīrs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1969)."},{"num":3707,"demo":false,"sanad":"","matn":["عَنْ أَبِي يَعْفُورٍ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى، قَالَ: شَهِدْتُهُ، وَكَبَّرَ عَلَى جِنَازَةٍ أَرْبَعًا، ثُمَّ قَامَ سَاعَةً، يَعْنِي يَدْعُو، ثُمَّ قَالَ: أَتَرَوْنِي كُنْتُ أُكَبِّرُ خَمْسًا؟ قَالُوا: لَا، قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُكَبِّرُ أَرْبَعًا."],"takhrij":"صحيح: رواه البيهقي (6937) من طرق عن أبي العباس محمد بن يعقوب، ثنا السري بن يحيى، ثنا قبيصة، ثنا الحسن بن صالح، عن أبي يعفور فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أربع تكبيرات على الجنائز","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bayhaqī (4/35).","chapter_en":"What is reported about four takbīrs in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Abū Yaʿfūr reported from ʿAbdullāh ibn Abī Awfā: I witnessed him say four takbīrs over a funeral, then stand for a short while, meaning to make supplication, and then say: “Did you think I was going to say five takbīrs?” They said: “No.” He said: “The Messenger of Allah ﷺ used to say four takbīrs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البيهقي (6937)."},{"num":3708,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن أَبِي لَيْلَى قَالَ: كَانَ زَيْدٌ (بن أَرْقَمَ) يُكَبّر عَلَى جَِنَازَةٍ أَرْبَعًا، وَإِنَّهُ كبَّر عَلَى جَِنَازَةٍ خَمْسًا، فَسَأَلْتُهُ فَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكَبِّرُهَا."],"takhrij":"صحيح: رواه مسلم في الجنائز (957) من طرق عن شعبة، عن عمرو ابن مرة، عن عبدالرحمن بن أبي ليلى فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الزيادة على أربع تكبيرات","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (957).","chapter_en":"What is reported about going beyond four takbīrs","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī Laylā said: Zayd ibn Arqam used to say four takbīrs over a funeral, but he once said five takbīrs over a funeral. So I asked him about that, and he said: The Messenger of Allah ﷺ used to say them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (957)."},{"num":3709,"demo":false,"sanad":"","matn":["عَنْ طَلْحَةَ بْنِ عَبْدِ اللَّهِ بْنِ عَوْفٍ، قَالَ: صَلَّيْتُ خَلْفَ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَلَى جَنَازَةٍ، فَقَرَأَ بِفَاتِحَةِ الْكِتَابِ، قَالَ لِيَعْلَمُوا أَنَّهَا سُنَّةٌ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1335) عن محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن سعد، عن طلحة فذكره.","grade":"صحيح","chapter_ar":"باب قراءة سورة الفاتحة جهراً وسراً","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1335).","chapter_en":"Reciting Sūrat al-Fātiḥah aloud or quietly","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Ṭalḥah ibn ʿAbdullāh ibn ʿAwf said: I prayed behind Ibn ʿAbbās over a funeral, and he recited the Opening of the Book. Then he said: “So that they may know that it is the Sunnah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1335)."},{"num":3710,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّهُ قَالَ: السُّنَّةُ فِي الصَّلاَةِ عَلَى الْجَنَازَةِ أَنْ يَقْرَأَ فِي التَّكْبِيرَةِ الْأُولَى بِأُمِّ الْقُرْآنِ مُخَافَتَةً، ثُمَّ يُكَبِّرَ ثَلاَثًا، وَالتَّسْلِيمُ عِنْدَ الآخِرَةِ."],"takhrij":"صحيح: رواه النسائي (1989) عن قتيبة قال: حدثنا الليث، عن ابن شهاب، عن أبي أمامة فذكره.","grade":"صحيح","chapter_ar":"باب قراءة سورة الفاتحة جهراً وسراً","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1989), authenticated by al-Ḥākim (1/360).","chapter_en":"Reciting Sūrat al-Fātiḥah aloud or quietly","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Abū Umāmah said: The Sunnah in the funeral prayer is that one recites the Opening of the Qur’an quietly after the first takbīr, then says three more takbīrs, and gives salām after the last one."]},"buhuth":{"en":["Benefit: The ruling for someone who joins the imam at the third takbīr in the funeral prayer — meaning he catches the supplication for the deceased with the imam — is that he completes what he missed from the first and second takbīrs. In the first of what he makes up, he sends prayers upon the Prophet ﷺ, and in the second he supplicates for the deceased, then he says the next takbīr and gives salām. This is based on the meaning of completion, as in Ṣaḥīḥ al-Bukhārī (908) and Ṣaḥīḥ Muslim (602/151): “Whatever you miss, then complete it.”","If he instead follows the understanding of making up what was missed, based on another wording in some routes of Ṣaḥīḥ Muslim (602/154): “And make up what preceded you,” then in the first takbīr he recites al-Fātiḥah, and in the second he sends prayers upon the Prophet ﷺ, then he says the next takbīr and gives salām. The first view is stronger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1989)، وصححه الحاكم (1/360)."},{"num":3711,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا صَلَّيْتُمْ عَلَى الْمَيِّتِ فَأَخْلِصُوا لَهُ الدُّعَاءَ."],"takhrij":"حسن: رواه أبو داود (3199)، وابن ماجه (1497) كلاهما من طريق محمد بن سلمة الحرّاني، عن محمد بن إسحاق، عن محمد بن إبراهيم، عن أبي سلمة بن عبدالرحمن، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب إخلاص الدعاء للميت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3199), Ibn Mājah (1497), Ibn Ḥibbān (3077).","chapter_en":"Sincerely supplicating for the deceased","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah said: I heard the Messenger of Allah ﷺ say: “When you pray over the deceased, then make your supplication sincerely for him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11108],"tks":"حسن: رواه أبو داود (3199)، وابن ماجه (1497)، وابن حبان (3077)."},{"num":3712,"demo":false,"sanad":"","matn":["عن عَوْفِ بْنِ مَالِكٍ يَقُولُ:  صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى جَِنَازَةٍ، فَحَفِظْتُ مِنْ دُعَائِهِ وَهُوَ يَقُولُ: اللَّهُمَّ اغْفِرْ لَهُ، وَارْحَمْهُ، وَعَافِهِ، وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ، أَوْ مِنْ عَذَابِ النَّارِ قَالَ: حَتَّى تَمَنَّيْتُ أَنْ أَكُونَ أَنَا ذَلِكَ الْمَيِّتَ."],"takhrij":"صحيح: رواه مسلم في الجنائز (963) عن هارون بن سعيد الأيلي، أخبرنا ابن وهب، أخبرني معاوية بن صالح، عن حبيب بن عبيد، عن جبير بن نُفير، سمعه يقول: سمعت عوف بن مالك فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية على الجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (963).","chapter_en":"What is reported of supplications in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["ʿAwf ibn Mālik said: The Messenger of Allah ﷺ prayed over a funeral, and I memorized from his supplication that he said: “O Allah, forgive him, have mercy on him, grant him well-being, pardon him, honor his reception, make his entrance spacious, wash him with water, snow, and hail, cleanse him of sins just as You cleanse a white garment of filth, replace his home with a better home, his family with a better family, his spouse with a better spouse, admit him into Paradise, and protect him from the punishment of the grave or from the punishment of the Fire.” He said: I even wished that I were that deceased person."]},"buhuth":{"en":["In another wording in Muslim: “O Allah, forgive him, have mercy on him, pardon him and grant him well-being, honor his reception, make his entrance spacious, wash him with water, snow, and hail, cleanse him of sins as a white garment is cleansed of dirt, replace his home with a better home, his family with a better family, his spouse with a better spouse, and protect him from the trial of the grave and the punishment of the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (963)."},{"num":3713,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى جَنَازَةٍ فَقَالَ: اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا، وَشَاهِدِنَا وَغَائِبِنَا، اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الإِيمَانِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الإِسْلاَمِ، اللَّهُمَّ لاَ تَحْرِمْنَا أَجْرَهُ، وَلاَ تُضِلَّنَا بَعْدَهُ."],"takhrij":"صحيح: رواه أبو داود (3201)، والترمذي (1024)، وابن ماجه (1498) من طرق عن يحيى بن أبي كثير، عن أبي سلمة بن عبدالرحمن، عن أبي هريرة فذكره، إلا ابن ماجه فإنه أخرجه من وجه آخر عن أبي سلمة بإسناده مثله.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية على الجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3201), al-Tirmidhī (1024), Ibn Mājah (1498), Ibn Ḥibbān (3070).","chapter_en":"What is reported of supplications in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ prayed over a funeral and said: “O Allah, forgive our living and our dead, our young and our old, our male and our female, those of us present and those absent. O Allah, whoever of us You keep alive, keep him alive upon faith, and whoever of us You cause to die, cause him to die upon Islam. O Allah, do not deprive us of his reward, and do not lead us astray after him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11104],"tks":"صحيح: رواه أبو داود (3201)، والترمذي (1024)، وابن ماجه (1498)، وابن حبان (3070)."},{"num":3714,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اللهُمَّ عَبْدُكَ وَابْنُ عَبْدِكَ، كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَاّ أَنْتَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ، وَأَنْتَ أَعْلَمُ بِهِ، إِنْ كَانَ مُحْسِنًا فزده فِي إِحْسَانِهِ، وَإِنْ كَانَ مُسِيئًا فَاغْفِرْ لَهُ، وَلَا تَحْرِمْنَا أَجْرَهُ وَلَا تَفْتِنَّا بَعْدَهُ ."],"takhrij":"صحيح: رواه أبو يعلى المقصد العلى (465) عن وهب بن بقية، أنا خالد بن عبدالله، عن عبدالرحمن بن إسحاق المديني، عن سعيد بن أبي سعيد، عن أبي هريرة فذكر الحديث، وصحَّحه ابن حبان (3073) فأخرجه عن أبي يعلى وهو أحمد بن علي بن المثنى الموصلي به مثله.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية على الجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Yaʿlā in al-Maqṣid al-ʿAlī (465), authenticated by Ibn Ḥibbān (3073).","chapter_en":"What is reported of supplications in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah reported from the Prophet ﷺ that he said: “O Allah, he is Your servant and the son of Your servant. He used to testify that there is no god but You, and that Muhammad is Your servant and Your Messenger, and You know him best. If he was a doer of good, then increase him in goodness, and if he was a wrongdoer, then forgive him. Do not deprive us of his reward, and do not test us after him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11105],"tks":"صحيح: رواه أبو يعلى في المقصد العلي (465)، وصححه ابن حبان (3073)."},{"num":3715,"demo":false,"sanad":"","matn":["عَنْ وَاثِلَةَ بْنِ الأَسْقَعِ قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ مِنَ الْمُسْلِمِينَ، فَسَمِعْتُهُ يَقُولُ: اللَّهُمَّ إِنَّ فُلاَنَ بْنَ فُلاَنٍ فِي ذِمَّتِكَ، وحبْلِ جِوَارِكَ، فقِه مِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ النَّارِ، وَأَنْتَ أهلُ الْوَفَاءِ والحق - وَفِي رِوَايَةِ الْحَمْدُ - اللَّهُمَّ فَاغْفِرْ لَهُ، وَارْحَمْهُ، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ ."],"takhrij":"حسن: رواه أبو داود (3202)، وابن ماجه (1499) كلاهما عن عبدالرحمن بن إبراهيم الدمشقي، قال: حدثنا الوليد بن مسلم، قال: حدثنا مروان بن جناح، قال: حدثني يونس بن ميسرة بن حَلْبَسٍ، عن واثلة بن الأسْقع فذكره ولفظهما سواء.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية على الجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3202), Ibn Mājah (1499).","chapter_en":"What is reported of supplications in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Wāthilah ibn al-Asqaʿ said: The Messenger of Allah ﷺ led us in prayer over a Muslim man, and I heard him say: “O Allah, so-and-so son of so-and-so is under Your protection and in the bond of Your care, so protect him from the trial of the grave and the punishment of the Fire. You are the One worthy of faithfulness and praise” — and in another wording: “worthy of faithfulness and truth” — “O Allah, forgive him and have mercy on him. Truly You are the Most Forgiving, the Most Merciful.”"]},"buhuth":{"en":["The phrase “in the bond of Your care” was explained by some scholars this way: it was a custom among the Arabs that some would frighten others, so when a man wanted to travel, he would take a pledge of protection from the chief of each tribe. He would remain safe by that pledge as long as he stayed within that tribe’s land, until he reached another tribe and took a similar pledge there. This was called the bond of neighborly protection. So here it means: as long as he is under Your protection. Or it may come from the meaning of granting safety and support. This was mentioned by al-Mundhirī."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11107],"tks":"حسن: رواه أبو داود (3202)، وابن ماجه (1499)."},{"num":3716,"demo":false,"sanad":"","matn":["عَنْ يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ رُكَانَةَ بْنِ الْمُطَّلِبِ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ لِلْجِنَازَةِ لِيُصَلِّيَ عَلَيْهَا قَالَ: اللَّهُمَّ عَبْدُكَ، وَابْنُ أَمَتِكَ احْتَاجَ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ، إِنْ كَانَ مُحْسِنًا فَزِدْ فِي إِحْسَانِهِ، وَإِنْ كَانَ مُسِيئًا فَتَجَاوَزَ عَنْهُ."],"takhrij":"حسن: رواه الحاكم (1328) عن أبي محمد عبد العزيز بن عبدالرحمن الخلال بمكة، ثنا عبدالرحمن بن إسحاق الكاتب، ثنا إبراهيم بن المنذر الحزامي، ثنا الحسين بن زيد بن علي بن الحسين بن علي، عن جعفر بن محمد، عن أبيه، عن يزيد بن ركانة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية على الجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ḥākim (1328).","chapter_en":"What is reported of supplications in the funeral prayer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Yazīd ibn Rukānah said: When the Messenger of Allah ﷺ stood for a funeral to pray over it, he would say: “O Allah, he is Your servant and the son of Your female servant. He is now in need of Your mercy, and You have no need to punish him. If he was a doer of good, then increase him in goodness, and if he was evil, then pardon him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11106],"tks":"حسن: رواه الحاكم (1328)."},{"num":3717,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سهل بْنِ حُنَيْفٍ، وَكَانَ مِنْ كُبَرَاءِ الْأَنْصَارِ وَعُلَمَائِهِمْ، وَأَبْنَاءِ الَّذِينَ شَهِدُوا بَدْرًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَهُ رِجَالٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الصَّلَاةِ عَلَى الْجِنَازَةِ أَنْ يُكَبِّرَ الْإِمَامُ، ثُمَّ يُصَلِّيَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَيُخْلِصَ الصَّلَاةَ –فِي التَّكْبِيرَاتِ الثَّلَاثِ، ثُمَّ يُسَلِّمُ تَسْلِيمًا خَفِيًّا حِينَ يَنْصَرِفُ، والسنـــة أَنْ يَفْعَلَ مِنْ وَرَاءَهُ مِثْلَ مَا فَعَلَ الْإِمَامُ."],"takhrij":"صحيح: رواه الحاكم (1331)، وعنه البيهقي (6962) عن إسماعيل بن أحمد التاجر، ثنا محمد بن الحسن العسقلاني، ثنا حرملة بن يحيى، ثنا ابن وهب، أخبرني يونس، عن ابن شهاب، قال: أخبرني أبو أمامة بن سهل ابن حنيف وكان من كبراء الأنصار وعلمائهم، وأبناء الذين شهدوا بدراً مع رسول الله صلى الله عليه وسلم، أخبره رجال من أصحاب رسول الله صلى الله عليه وسلم في الصلاة على الجنازة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تسليمة واحدة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Ḥākim (1331), and from him al-Bayhaqī (4/39–40).","chapter_en":"What is reported about giving one salām","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":18,"content":{"translation":{"en":["Abū Umāmah ibn Sahl ibn Ḥunayf — who was one of the leading men of the Anṣār, one of their scholars, and from the sons of those who witnessed Badr with the Messenger of Allah ﷺ — reported that some men from the Companions of the Prophet ﷺ informed him about the funeral prayer: the imam says the takbīr, then sends prayers upon the Prophet ﷺ, and makes sincere supplication in the three remaining takbīrs, then gives one quiet salām when finishing. And the Sunnah is that those behind him do the same as the imam did."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (1331)، وعنه البيهقي (6962)."},{"num":3718,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى جِنَازَةٍ، فَكَبَّرَ عَلَيْهَا أَرْبَعًا، وَسَلَّمَ تَسْلِيمَةً وَاحِدَةً."],"takhrij":"حسن: رواه الدارقطني (2/77) عن أحمد بن إسحاق بن البهلول، ثنا الحسين ابن عمرو العنقري، ثنا إبراهيم بن إسماعيل، ثنا حفص بن غيات، عن أبي العنبس، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تسليمة واحدة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Dāraquṭnī (2/77), al-Ḥākim (1332), al-Bayhaqī (4/43).","chapter_en":"What is reported about giving one salām","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ prayed over a funeral, said four takbīrs over it, and gave one salām."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني (2/77)، والحاكم (1332)، والبيهقي (6982)."},{"num":3719,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: ثَلَاثُ خِلَالٍ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُنَّ، تَرَكَهُنَّ النَّاسُ، إِحْدَاهُنَّ: التَّسْلِيمُ عَلَى الْجِنَازَةِ مِثْلُ التَّسْلِيمِ فِي الصَّلَاةِ."],"takhrij":"حسن: رواه الطبراني في الكبير (10/100) من طريق موسى بن أعين، عن خالد بن يزيد أبي عبدالرحمن، عن زيد بن أبي أنيسة، عن حماد، عن إبراهيم، عن علقمة والأسود، عن ابن مسعود، ومن هذا الوجه أخرجه أيضاً البيهقي (6989) واللفظ له.","grade":"حسن","chapter_ar":"باب ما جاء في تسليمتين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Kabīr (10/100), al-Bayhaqī (4/43), and this is his wording.","chapter_en":"What is reported about giving two salāms","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":19,"content":{"translation":{"en":["Ibn Masʿūd said: There are three practices the Messenger of Allah ﷺ used to do which people later left off. One of them is giving salām in the funeral prayer the same way salām is given in the regular prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (10/100)، والبيهقي (6989)، واللفظ له."},{"num":3720,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: السِّقْطُ يُصَلَّى عَلَيْهِ، وَيُدْعَى لِوَالِدَيْهِ بِالْمَغْفِرَةِ وَالرَّحْمَةِ .."],"takhrij":"صحيح: رواه أبو داود (3180)، والترمذي (1031)، والنسائي (1943)، وابن ماجه (1481) كلّهم من طرق عن زياد بن جبير، عن أبيه، عن المغيرة بن شعبة، فذكره في حديث طويل. انظر: ما جاء في الركوب خلف الجنازة. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الصلاة على السِّقْط","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3180), al-Tirmidhī (1031), al-Nasā’ī (1943), Ibn Mājah (1481).","chapter_en":"Praying over a miscarried child","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":20,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah said: The Prophet ﷺ said: “A miscarried child is to be prayed over, and supplication is made for its parents for forgiveness and mercy.”"]},"buhuth":{"en":["The miscarried child over whom the funeral prayer is offered is the one that completed four months. That is because of the hadith of Ibn Masʿūd, who said: The Messenger of Allah ﷺ — and he is the truthful one who is believed — told us: “The creation of each one of you is gathered in his mother’s womb for forty days and forty nights, then he becomes a clot for the same length, then a morsel of flesh for the same length, then the angel is sent to him and is commanded with four matters: his provision, his lifespan, his deeds, and whether he will be wretched or blessed. Then the soul is breathed into him.”","Agreed upon: al-Bukhārī (7454), Muslim (2643)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3180)، والترمذي (1031)، والنسائي (1943)، وابن ماجه (1481)."},{"num":3721,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ مَاتَ النَّجَاشِيُّ: مَاتَ الْيَوْمَ رَجُلٌ صَالِحٌ، فَقُومُوا فَصَلُّوا عَلَى أَخِيكُمْ أَصْحَمَةَ."],"takhrij":"متفق عليه: رواه البخاري في مناقب الأنصار (3877)، ومسلم في الجنائز (952/65) كلاهما من حديث ابن جريج، عن عطاء، عن جابر بن عبدالله فذكره واللفظ للبخاري، وزاد مسلم: فقام فأمَّنا وصلى عليه .","grade":"متفق عليه","chapter_ar":"باب الصلاة على الغائب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (3877), Muslim (952/65), and this is the wording of al-Bukhārī.","chapter_en":"The funeral prayer in absentia","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":21,"content":{"translation":{"en":["Jābir said: The Prophet ﷺ said when al-Najāshī died: “Today a righteous man has died, so stand and pray over your brother Aṣḥamah.”"]},"buhuth":{"ar":["زاد مسلم:  فقام فأمَّنا وصلَّى عليه ."],"en":["Muslim adds: “So he stood, led us, and prayed over him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3877)، ومسلم (952/65)، واللفظ للبخاري."},{"num":3722,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَعَى لِلنَّاسِ النَّجَاشِيَّ فِي الْيَوْمِ الَّذِي مَاتَ فِيهِ، فَخَرَجَ بِهِمْ إِلَى الْمُصَلَّى، وَكَبَّرَ أَرْبَعَ تَكْبِيرَاتٍ."],"takhrij":"متفق عليه: رواه مالك في الجنائز (14) عن بن شهاب، عن سعيد بن المسيب، عن أبي هريرة فذكره. ورواه البخاري في الجنائز (1245)، ومسلم في الجنائز (951) كلاهما من حديث مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب الصلاة على الغائب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (14), al-Bukhārī (1245), Muslim (951).","chapter_en":"The funeral prayer in absentia","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":21,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ announced the death of al-Najāshī to the people on the day he died, then went out with them to the prayer place, lined them up, and said four takbīrs."]},"buhuth":{"en":["In another narration: “He stood up, and we stood up with him, until he reached al-Baqīʿ.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3701],"tks":"متفق عليه: رواه مالك (14)، والبخاري (1245)، ومسلم (951)."},{"num":3723,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنَّ أَخًا لَكُمْ قَدْ مَاتَ، فَقُومُوا فَصَلُّوا عَلَيْهِ - يَعْنِي: النَّجَاشِيَّ.","وفي رواية: إن أخاكم ."],"takhrij":"صحيح: رواه مسلم في الجنائز (953) من طرق عن أيوب، عن أبي قلابة، عن أبي المهلب، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على الغائب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (953).","chapter_en":"The funeral prayer in absentia","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":21,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn said: The Messenger of Allah ﷺ said: “A brother of yours has died, so stand and pray over him,” meaning al-Najāshī."]},"buhuth":{"en":["Aḥmad (2005) also narrated it with the wording: “The Messenger of Allah ﷺ formed the row, and we formed rows behind him, and he prayed over him, while we assumed that a body had been placed before him.” It was authenticated by Ibn Ḥibbān (3102)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3538],"tks":"صحيح: رواه مسلم (953)."},{"num":3724,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ أَسِيدٍ الْغِفَارِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُخْبِر بموت النَّجَاشِيُّ، قَالَ: فَقَالَ: صَلُّوا عَلَى أَخٍ لَكُمْ مَاتَ بِغَيْرِ أَرْضِكُمْ قَالُوا: مَنْ هُوَ؟ قَالَ: النَّجَاشِيُّ ."],"takhrij":"صحيح: رواه ابن ماجه (1537) عن محمد بن المثنى، قال: حدثنا عبدالرحمن بن مهدي، عن المثنى بن سعيد، عن قتادة، عن أبي الطفيل، عن حذيفة ابن أَسيد فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على الغائب","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Mājah (1537).","chapter_en":"The funeral prayer in absentia","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":21,"content":{"translation":{"en":["Ḥudhayfah ibn Asīd al-Ghifārī reported that the Messenger of Allah ﷺ was informed of the death of al-Najāshī, so he said: “Pray over a brother of yours who died in a land other than your own.” They said: “Who is he?” He said: “Al-Najāshī.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1537)."},{"num":3725,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَا مِنْ مَيِّتٍ يُصَلِّي عَلَيْهِ أُمَّةٌ مِنَ الْمُسْلِمِينَ يَبْلُغُونَ مِائَةً كُلُّهُمْ يَشْفَعُونَ لَهُ إِلَّا شُفِّعُوا فِيهِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (947) عن الحسن بن عيسى، حدثنا ابن المبارك، أخبرنا سلاَّمُ بن أبي مطيع، عن أيوب، عن أبي قلابة، عن عبدالله بن يزيد رضيع عائشة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب من صلَّى عليه مائة شُفِّعوا فيه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (947).","chapter_en":"If one hundred pray over him, their intercession is accepted for him","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":22,"content":{"translation":{"en":["ʿĀ’ishah reported from the Prophet ﷺ that he said: “No deceased person has a group of Muslims numbering one hundred pray over him, all of them interceding for him, except that their intercession for him is accepted.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[933],"tks":"صحيح: رواه مسلم (947)."},{"num":3726,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ صَلَّى عَلَيْهِ مِائَةٌ مِنَ الْمُسْلِمِينَ غُفِرَ لَهُ."],"takhrij":"صحيح: رواه ابن ماجه (1488) عن أبي بكر بن أبي شيبة، قال: حدثنا عبيدالله، قال: أنبأنا شيبان، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب من صلَّى عليه مائة شُفِّعوا فيه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Mājah (1488).","chapter_en":"If one hundred pray over him, their intercession is accepted for him","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah reported from the Prophet ﷺ that he said: “If one hundred Muslims pray over him, he is forgiven.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1488)."},{"num":3727,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ، عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ،  أَنَّهُ مَاتَ ابْنٌ لَهُ بِقُدَيْدٍ، أَوْ بِعُسْفَانَ، فَقَالَ: يَا كُرَيْبُ! انْظُرْ مَا اجْتَمَعَ لَهُ مِنَ النَّاسِ، قَالَ: فَخَرَجْتُ فَإِذَا نَاسٌ قَدِ اجْتَمَعُوا لَهُ، فَأَخْبَرْتُهُ، فَقَالَ: تَقُولُ هُمْ أَرْبَعُونَ، قَالَ: نَعَمْ، قَالَ: أَخْرِجُوهُ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ رَجُلٍ مُسْلِمٍ يَمُوتُ فَيَقُومُ عَلَى جَِنَازَتِهِ أَرْبَعُونَ رَجُلًا، لَا يُشْرِكُونَ بِاللهِ شَيْئًا، إِلَّا شَفَّعَهُمُ اللهُ فِيهِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (948) من طرق عن ابن وهب، قال: أخبرني أبو صخر، عن شريك بن عبدالله بن أبي نمر، عن كُريب مولى ابن عباس، عن ابن عباس فذكر الحديث.","grade":"صحيح","chapter_ar":"باب من صلَّى عليه أربعون شُفِّعوا فيه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (948).","chapter_en":"If forty pray over him, their intercession is accepted for him","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":23,"content":{"translation":{"en":["Ibn ʿAbbās had a son who died at Qudayd, or at ʿUsfān, so he said: “O Kurayb, see how many people have gathered for him.” He said: So I went out and found that some people had gathered for him, and I informed him. He said: “Are you saying they are forty?” He said: “Yes.” He said: “Bring him out, for I heard the Messenger of Allah ﷺ say: ‘No Muslim man dies and forty men stand over his funeral, not associating anything with Allah, except that Allah accepts their intercession for him.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (948)."},{"num":3728,"demo":false,"sanad":"","matn":["عن مَيْمُونَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: أَخْبَرَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنْ مَيِّتٍ يُصَلِّي عَلَيْهِ أُمَّةٌ مِنَ النَّاسِ إِلاَّ شُفِّعُوا فِيهِ. فَسَأَلْتُ أَبَا الْمَلِيحِ عَنِ الأُمَّةِ فَقَالَ أَرْبَعُونَ.","وفي رواية: الأمة أربعون إلى مائة."],"takhrij":"حسن: رواه النسائي (1993) عن إسحاق بن إبراهيم، قال: أنبأنا محمد ابن سواء أبو الخطاب، قال: حدثنا أبو بكَّار الحكم بن فرُّوخ قال: صلَّى بنا أبو المليح على جنازة فظننا أنه قد كبَّر، فأقبل علينا بوجهه فقال: أقيموا صفوفكم ولتحسُنْ شَفاعتُكم، قال أبو المليح: حدثني عبدالله وهو ابن سليط، عن إحدى أمهات المؤمنين، وهي ميمونة فذكرت الحديث.","grade":"حسن","chapter_ar":"باب من صلَّى عليه أمة شُفِّعوا","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Nasā’ī (1993), and the second narration is with Aḥmad (26812).","chapter_en":"If a group prays over him, their intercession is accepted","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":24,"content":{"translation":{"en":["Maymūnah, the wife of the Prophet ﷺ, said: The Prophet ﷺ told me: “No deceased person has a group of people pray over him except that their intercession for him is accepted.” So I asked Abū al-Malīḥ about the meaning of “a group,” and he said: forty. And in another narration: A group means between forty and one hundred."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1993)، والرواية الثانية عند الإمام أحمد (26812)."},{"num":3729,"demo":false,"sanad":"","matn":["عن سُلَيْمَانَ الشيباني قَالَ: سَمِعْتُ الشَّعْبِيَّ، قَالَ: أَخْبَرَنِي مَنْ، مَرَّ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَبْرٍ مَنْبُوذٍ، فَأَمَّهُمْ، وَصَفُّوا عَلَيْهِ. فَقُلْتُ: يَا أَبَا عَمْرٍو! مَنْ حَدَّثَكَ؟ فَقَالَ ابْنُ عَبَّاسٍ.","وفي رواية: عَنِ ابْنِ عَبَّاسٍ قَالَ: مَاتَ إِنْسَانٌ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَعُودُهُ فَمَاتَ بِاللَّيْلِ، فَدَفَنُوهُ لَيْلاً، فَلَمَّا أَصْبَحَ أَخْبَرُوهُ فَقَالَ: مَا مَنَعَكُمْ أَنْ تُعْلِمُونِي؟ قَالُوا: كَانَ اللَّيْلُ فَكَرِهْنَا -ـ- وَكَانَتْ ظُلْمَةٌ- أَنْ نَشُقَّ عَلَيْكَ، فَأَتَى قَبْرَهُ فَصَلَّى عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (857)، ومسلم في الجنائز (954) كلاهما من حديث محمد بن جعفر غندر، قال: حدثنا شعبة، عن سليمان الشيباني فذكره.","grade":"متفق عليه","chapter_ar":"باب الصلاة على القبر بعد الدفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (857), Muslim (954), and the second narration is in al-Bukhārī (1247).","chapter_en":"Praying at the grave after burial","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["Sulaymān al-Shaybānī said: I heard al-Shaʿbī say: Someone who passed with the Prophet ﷺ by a grave that was separate from the other graves told me that he led them in prayer over it and they formed rows behind him. So I said: “O Abū ʿAmr, who told you this?” He said: Ibn ʿAbbās. In another narration, Ibn ʿAbbās said: A person whom the Messenger of Allah ﷺ used to visit became ill and died at night, so they buried him during the night. When morning came, they informed him, and he said: “What prevented you from informing me?”","They said: “It was night, and it was dark, so we disliked causing hardship for you.” So he came to the grave and prayed over him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (857)، ومسلم (954)، والرواية الثانية عند البخاري (1247)."},{"num":3730,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ  أَنَّ امْرَأَةً سَوْدَاءَ كَانَتْ تَقُمُّ الْمَسْجِدَ، أَوْ شَابًّا فَفَقَدَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَ عَنْهَا، أَوْ عَنْهُ، فَقَالُوا: مَاتَ. قَالَ: أَفَلَا كُنْتُمْ آذَنْتُمُونِي، قَالَ: فَكَأَنَّهُمْ صَغَّرُوا أَمْرَهَا، أَوْ أَمْرَهُ فَقَالَ: دُلُّونِي عَلَى قَبْرِهِ فَدَلُّوهُ فَصَلَّى عَلَيْهَا، ثُمَّ قَالَ: إِنَّ هَذِهِ الْقُبُورَ مَمْلُوءَةٌ ظُلْمَةً عَلَى أَهْلِهَا، وَإِنَّ اللَّهَ عَزَّ وَجَلَّ يُنَوِّرُهَا لَهُمْ بِصَلَاتِي عَلَيْهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1337)، ومسلم في الجنائز (956) كلاهما من حديث حماد بن زيد، عن ثابت، البناني، عن أبي رافع، عن أبي هريرة فذكره، واللفظ لمسلم، ولفظ البخاري قريب منه.","grade":"متفق عليه","chapter_ar":"باب الصلاة على القبر بعد الدفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1337), Muslim (956), and this is the wording of Muslim.","chapter_en":"Praying at the grave after burial","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah reported that a black woman used to sweep the mosque — or a young man — and the Messenger of Allah ﷺ missed her — or him — and asked about her — or him. They said: “She died.” He said: “Why did you not inform me?” He said: It was as though they considered her matter insignificant. So he said: “Show me her grave.” They showed it to him, and he prayed over her. Then he said: “These graves are filled with darkness for their inhabitants, and Allah, Mighty and Majestic, illuminates them for them through my prayer over them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1337)، ومسلم (956)، واللفظ لمسلم."},{"num":3731,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى قَبْرٍ."],"takhrij":"صحيح: رواه مسلم في الجنائز (955) عن إبراهيم بن محمد بن عَرْعَرة السامي، حدثنا غندر، حدثنا شعبة، عن حبيب بن الشهيد، عن ثابت، عن أنس فذكر الحديث، هكذا رواه مسلم حديث أنس مختصرا وجاء تفصيله في الحديث التالي.","grade":"صحيح","chapter_ar":"باب الصلاة على القبر بعد الدفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (955).","chapter_en":"Praying at the grave after burial","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ prayed over a grave."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (955)."},{"num":3732,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ أَسْوَدَ كَانَ يُنَظِّفُ الْمَسْجِدَ، فَمَاتَ، فَدُفِنَ لَيْلًا، وَأَتَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأُخْبِرَ، فَقَالَ: انْطَلِقُوا إِلَى قَبْرِهِ، فَانْطَلَقُوا إِلَى قَبْرِهِ، فَقَالَ: إِنَّ هَذِهِ الْقُبُورَ مُمْتَلِئَةٌ عَلَى أَهْلِهَا، ظُلْمَةً، وَإِنَّ اللَّهَ يُنَوِّرُهَا بِصَلَاتِي عَلَيْهَا، فَأَتَى الْقَبْرَ فَصَلَّى عَلَيْهِ، وَقَالَ رَجُلٌ مِنَ الْأَنْصَارِ: يَا رَسُولَ اللَّهِ، إِنَّ أَخِي مَاتَ، وَلَمْ تُصَلِّ عَلَيْهِ، قَالَ: فَأَيْنَ قَبْرُهُ؟ فَأَخْبَرَهُ، فَانْطَلَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَ الْأَنْصَارِيِّ."],"takhrij":"حسن: رواه أحمد ( 12517) عن سليمان بن داود الطيالسي، حدثنا أبو عامر –يعني الخزاز، عن ثابت، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب الصلاة على القبر بعد الدفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (12517).","chapter_en":"Praying at the grave after burial","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["Anas reported that a black man used to clean the mosque and then died. He was buried at night, and the Prophet ﷺ was later informed. He said: “Take me to his grave.” So they went to his grave, and he said: “These graves are full of darkness for their inhabitants, and Allah illuminates them by my prayer over them.” Then he came to the grave and prayed over him. And a man from the Anṣār said: “O Messenger of Allah ﷺ, my brother died and you did not pray over him.” He said: “Then where is his grave?” So he informed him, and the Messenger of Allah ﷺ went with the Anṣārī."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12517)."},{"num":3733,"demo":false,"sanad":"","matn":["عَنْ يَزِيدَ بْنِ ثَابِتٍ، وَكَانَ، أَكْبَرَ مِنْ زَيْدٍ، قَالَ: خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا وَرَدَ الْبَقِيعَ فَإِذَا هُوَ بِقَبْرٍ جَدِيدٍ فَسَأَلَ عَنْهُ فَقَالُوا: فُلاَنَةُ. قَالَ: فَعَرَفَهَا وَقَالَ: أَلاَ آذَنْتُمُونِي بِهَا. قَالُوا: كُنْتَ قَائِلاً صَائِمًا، فَكَرِهْنَا أَنْ نُؤْذِيَكَ. قَالَ: فَلاَ تَفْعَلُوا، لاَ أَعْرِفَنَّ مَا مَاتَ فِيكُمْ مَيِّتٌ، مَا كُنْتُ بَيْنَ أَظْهُرِكُمْ إِلاَّ آذَنْتُمُونِي بِهِ، فَإِنَّ صَلاَتِي عَلَيْهِ لَهُ رَحْمَةٌ. ثُمَّ أَتَى الْقَبْرَ، فَصَفَّنَا خَلْفَهُ، فَكَبَّرَ عَلَيْهِ أَرْبَعًا."],"takhrij":"صحيح: رواه النسائي (2022)، وابن ماجه (1528) كلاهما من حديث عثمان بن حكيم الأنصاري، عن خارجة بن زيد بن ثابت، عن عمه يزيد بن ثابت فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على القبر بعد الدفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (2022), Ibn Mājah (1528), authenticated by Ibn Ḥibbān (3087) and al-Ḥākim (3/591).","chapter_en":"Praying at the grave after burial","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["Yazīd ibn Thābit, who was older than Zayd, said: We went out with the Prophet ﷺ, and when we came to al-Baqīʿ, there was a fresh grave there. He asked about it and they said: “It is so-and-so.” He recognized who she was and said: “Why did you not inform me about her?” They said: “You were taking a nap and fasting, and we disliked disturbing you.” He said: “Do not do that. Let me definitely know whenever anyone among you dies, as long as I am among you. My prayer over him is mercy for him.” Then he came to the grave, and we formed rows behind him, and he said four takbīrs over it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3705],"tks":"صحيح: رواه النسائي (2022)، وابن ماجه (1528)، وصححه ابن حبان (3087)، والحاكم (3/591)."},{"num":3734,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ أَنَّهُ أَخْبَرَهُ، أَنَّ مِسْكِينَةً مرضَتْ، فَأُخْبِرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَرَضِهَا، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُ الْمَسَاكِينَ، وَيَسْأَلُ عَنْهُمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِذَا مَاتَتْ فآذنتموني بِهَا فَخَرَجَ بِجَنَازَتِهَا لَيْلاً، فكرهوا أَنْ يُوقِظُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فلمـــا أَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُخْبِرَ بِالَّذِي كَانَ من شأنها فَقَالَ: أَلَمْ آمُرْكُمْ أَنْ تُؤْذِنُونِي بِهَا؟ فَقَالُوا: يَا رَسُولَ اللَّهِ كَرِهْنَا أَنْ نُخرجَك لَيْلاً، ونوقظك، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى صفَّ بِالنَّاسِ عَلَى قَبْرِهَا، وكبَّر أَرْبَعَ تَكْبِيرَاتٍ."],"takhrij":"صحيح: رواه مالك في الجنائز (15) عن ابن شهاب عن أبي أمامة بن سهل فذكره، وهذا مرسل فإن أبا أمامة - واسمه سعد، مشهور بكنيته له رؤية ولم يسمع من النبي صلى الله عليه وسلم.","grade":"صحيح","chapter_ar":"باب الصلاة على القبر بعد الدفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Mālik (15), al-Nasā’ī (1907).","chapter_en":"Praying at the grave after burial","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["Abū Umāmah ibn Sahl ibn Ḥunayf reported that a poor woman became ill, and the Prophet ﷺ was informed of her illness. The Messenger of Allah ﷺ used to visit the poor and ask about them. So the Messenger of Allah ﷺ said: “When she dies, inform me.” But they took out her funeral at night, and they disliked waking the Messenger of Allah ﷺ. When morning came, the Messenger of Allah ﷺ was informed of what had happened, so he said: “Did I not command you to inform me about her?” They said: “O Messenger of Allah ﷺ, we disliked taking you out at night and waking you.” So the Messenger of Allah ﷺ went out until he arranged the people in rows at her grave and said four takbīrs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (15)، ورواه النسائي (1907)."},{"num":3735,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ،: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَى قَبْرِ امْرَأَةٍ بَعْدَ مَا دُفِنَتْ."],"takhrij":"حسن: رواه النسائي (2025) عن المغيرة بن عبدالرحمن، قال: حدثنا زيد بن علي - وهو أبو أسامة، قال: حدثنا جعفر بن بُرقان، عن حبيب بن أبي مرزوق، عن عطاء، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب الصلاة على القبر بعد الدفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Nasā’ī (2025).","chapter_en":"Praying at the grave after burial","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["Jābir reported that the Prophet ﷺ prayed over the grave of a woman after she had been buried."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2025)."},{"num":3736,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بن رَبِيعَةَ قَالَ: مَرَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَبْرٍ فَقَالَ: مَا هَذَا الْقَبْرُ؟ قَالُوا: قَبْرُ فُلَانَةَ، قَالَ: أَفَلَا آذَنْتُمُونِي؟ قَالُوا: كُنْتَ نَائِمًا، فَكَرِهْنَا أَنْ نُوقِظَكَ، قَالَ: فَلَا تَفْعَلُوا فَادْعُونِي لِجَنَائِزِكُمْ فصفَّ عَلَيْهَا فصلَّى."],"takhrij":"حسن: رواه الإمام أحمد (15673) عن قتيبة بن سعيد، حدثنا عبد العزيز -يعني ابن محمد الدراوردي، عن محمد بن زيد التيمي، عن عبدالله ابن عامر، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب الصلاة على القبر بعد الدفن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (15673).","chapter_en":"Praying at the grave after burial","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["ʿĀmir ibn Rabīʿah said: The Messenger of Allah ﷺ passed by a grave and said: “What is this grave?” They said: “The grave of so-and-so.” He said: “Why did you not inform me?” They said: “You were asleep, and we disliked waking you.” He said: “Do not do that. Call me for your funerals.” Then he lined them up and prayed over her."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (15673)."},{"num":3737,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  بِرَجُلٍ قَتَلَ نَفْسَهُ بِمَشَاقِصَ، فَلَمْ يُصَلِّ عَلَيْهِ.","وفي رواية: ذكرت قصة هذا الرجل بأنه مَرِضَ، فَصِيحَ عَلَيْهِ، فَجَاءَ جَارُهُ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم، فَقَالَ [لَهُ]: إِنَّهُ قَدْ مَاتَ، قَالَ: وَمَا يُدْرِيكَ؟ قَالَ: أَنَا رَأَيْتُهُ، قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: إِنَّهُ لَمْ يَمُتْ ،، قَالَ: فَرَجَعَ، فَصِيحَ عَلَيْهِ، فَجَاءَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم، فَقَالَ: إِنَّهُ قَدْ مَاتَ، فَقَالَ النَّبِيُّ صلى الله عليه وسلم: إِنَّهُ لَمْ يَمُتْ فَرَجَعَ، فَصِيحَ عَلَيْهِ، فَقَالَتِ امْرَأَتُهُ: انْطَلِقْ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَأَخْبِرْهُ، فَقَالَ الرَّجُلُ: اللَّهُمَّ الْعَنْهُ، قَالَ: ثُمَّ انْطَلَقَ الرَّجُلُ، فَرَآهُ قَدْ نَحَرَ نَفْسَهُ بِمِشْقَصٍ مَعَهُ، فَانْطَلَقَ إِلَى النَّبِيِّ صلى الله عليه وسلم فَأَخْبَرَهُ أَنَّهُ قَدْ مَاتَ، فَقَالَ: وما يُدْرِيكَ؟ قَالَ: رَأَيْتُهُ يَنْحَرُ نَفْسَهُ بِمَشَاقِصَ مَعَهُ، قَالَ: أَنْتَ رَأَيْتَهُ؟ قَالَ: نَعَمْ، قَالَ: إِذًا لاَ أُصَلِّي عَلَيْهِ .."],"takhrij":"صحيح: رواه مسلم في الجنائز (978) عن عون بن سلاَّم، أخبرنا زهير، عن سماك، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على قاتل نفسه لغير ولي المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (978), and the second narration is in Abū Dāwūd (3185).","chapter_en":"Not praying over the one who killed himself, for someone other than the ruler of the Muslims","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":26,"content":{"translation":{"en":["Jābir ibn Samurah said: The Prophet ﷺ was brought a man who had killed himself with broad arrowheads, and he did not pray over him. In another narration, the story of this man is mentioned: he became ill, and crying arose over him. His neighbor came to the Messenger of Allah ﷺ and said to him: “He has died.”","He said: “How do you know?” He said: “I saw him.” The Messenger of Allah ﷺ said: “He has not died.” He went back, and crying arose again, so he came to the Messenger of Allah ﷺ and said: “He has died.” The Prophet ﷺ said: “He has not died.” He went back again, and crying arose, and his wife said: “Go to the Messenger of Allah ﷺ and tell him.” So the man said: “O Allah, curse him.” Then the man went and saw that he had slaughtered himself with one of the arrowheads he had, so he went to the Prophet ﷺ and informed him that he had died. He said: “How do you know?” He said: “I saw him slaughtering himself with arrowheads he had.” He said: “You saw him?” He said: “Yes.” He said: “Then I will not pray over him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (978)، والرواية الثانية عند أبي داود (3185)."},{"num":3738,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ بْنِ عَبْدِ اللَّهِ أَنَّ رَجُلاً مِنْ أَسْلَمَ جَاءَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاعْتَرَفَ بِالزِّنَا، فَأَعْرَضَ عَنْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى شَهِدَ عَلَى نَفْسِهِ أَرْبَعَ مَرَّاتٍ، قَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَبِكَ جُنُونٌ ؟ قَالَ: لاَ، قَالَ: أحصنت؟ قَالَ: نَعَمْ، قَالَ: فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَ بِالْمُصَلَّى، فَلَمَّا أَذْلَقَتْهُ الْحِجَارَةُ فرَّ، فَأُدْرِكَ فَرُجِمَ حَتَّى مَاتَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْرًا، وَلَمْ يُصَلِّ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الحدود (6820)، ومسلم في الحدود (1691/16) كلاهما من حديث عبد الرزاق، وهو في مصنفه (13337) عن معمر، عن الزهري، عن أبي سلمة بن عبدالرحمن، عن جابر فذكر الحديث واللفظ من مصنف عبد الرزاق.","grade":"متفق عليه","chapter_ar":"باب ترك الصلاة على المرجوم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (6820), Muslim (1691/16), and ʿAbd al-Razzāq (13337).","chapter_en":"Leaving the funeral prayer over the stoned adulterer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":27,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that a man from Aslam came to the Prophet ﷺ and confessed to adultery. The Prophet ﷺ turned away from him until he testified against himself four times. Then the Prophet ﷺ said to him: “Are you mad?” He said: “No.” He said: “Have you previously been married?” He said: “Yes.” Then the Prophet ﷺ ordered that he be stoned at the prayer ground. When the stones hurt him severely, he ran away, but he was caught and stoned until he died. Then the Prophet ﷺ spoke well of him, but did not pray over him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6820)، ومسلم (1691/16)، وعبد الرزاق (13337)."},{"num":3739,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ  أَنَّ امْرَأَةً مِنْ جُهَيْنَةَ أَتَتْ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ حُبْلَى مِنَ الزِّنَى فَقَالَتْ: يَا نَبِيَّ اللَّهِ، أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ، فَدَعَا نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِيَّهَا فَقَالَ: أَحْسِنْ إِلَيْهَا، فَإِذَا وَضَعَتْ فَأْتِنِي بِهَا. فَفَعَلَ، فَأَمَرَ بِهَا نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَشُكَّتْ عَلَيْهَا ثِيَابُهَا، ثُمَّ أَمَرَ بِهَا فَرُجِمَتْ، ثُمَّ صَلَّى عَلَيْهَا، فَقَالَ لَهُ عُمَرُ: تُصَلِّي عَلَيْهَا يَا نَبِيَّ اللَّهِ! وَقَدْ زَنَتْ؟ فَقَالَ: لَقَدْ تَابَتْ تَوْبَةً لَوْ قُسِمَتْ بَيْنَ سَبْعِينَ مِنْ أَهْلِ الْمَدِينَةِ لَوَسِعَتْهُمْ، وَهَلْ وَجَدْتَ تَوْبَةً أَفْضَلَ مِنْ أَنْ جَادَتْ بِنَفْسِهَا لِلهِ تَعَالَى."],"takhrij":"صحيح: رواه مسلم في الحدود (1696) عن أبي غسان مالك بن عبد الواحد المِسْمعي، حدثنا معاذ (يعني ابن هشام) حدثني أبي، عن يحيى بن أبي كثير، حدثني أبو قلابة، أن أبا المهلب حدَّثه، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب جواز الصلاة على المرجوم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (1696).","chapter_en":"The permissibility of praying over the stoned adulterer","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":28,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported that a woman from Juhaynah came to the Prophet of Allah ﷺ while pregnant from adultery and said: “O Prophet of Allah ﷺ, I have incurred a legal punishment, so carry it out upon me.” So the Prophet ﷺ called her guardian and said: “Treat her well, and when she gives birth, bring her to me.” He did so. Then the Prophet ﷺ ordered regarding her, so her clothes were fastened tightly around her, then he ordered that she be stoned, and afterward he prayed over her. ʿUmar said to him: “You pray over her, O Prophet of Allah ﷺ, even though she committed adultery?” He said: “She has repented with such a repentance that if it were divided among seventy people of Madinah, it would have been enough for them. And have you found any repentance better than that she gave up her own life for Allah Most High?”"]}},"tuhfa":{},"full":1,"rep":[6959],"tks":"صحيح: رواه مسلم (1696)."},{"num":3740,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ قَالَ: لَمَّا تُوُفِّيَ عبدالله بْنُ أُبَيّ بْنُ سَلُولَ جَاءَ ابْنُهُ عبدالله بْنُ عبدالله بْنُ أُبيّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَأَلَهُ أَنْ يُعْطِيَهُ قَمِيصَهُ يُكفِّنُ فِيهِ أَبَاهُ فَأَعْطَاهُ. ثُمَّ سَأَلَ أَنْ يُصَلِّيَ عَلَيْهِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ عَلَيْهِ، فَقَامَ عُمَرُ فَأَخَذَ بِثَوْبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! تُصَلِّي عَلَيْهِ، وَقَدْ نَهَاكَ رَبُّكَ أَنْ تُصَلِّيَ عَلَيْهِ؟ فَقَالَ رَسُولُ اللَّهِ: إِنَّمَا خيَّرني اللَّهُ فَقَالَ: ﴿اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً﴾ [سورة التَّوْبَةِ:80] وَسَأَزِيدُهُ عَلَى سَبْعِينَ قَالَ: إِنَّهُ مُنَافِقٌ قَالَ: فَصَلَّى عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَنْزَلَ اللَّهُ: ﴿وَلَا تُصَلِّ عَلَى أَحَدٍ مِنْهُمْ مَاتَ أَبَدًا وَلَا تَقُمْ عَلَى قَبْرِهِ﴾ [سورة التَّوْبَةِ:84]."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4670)، ومسلم في صفات المنافقين (2774) كلاهما من حديث أبي أسامة، حدثنا عبيدالله بن عمر، عن نافع، عن ابن عمر فذكره ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ما جاء من النهي عن الصلاة على المنافقين والمشركين والاستغفار لهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4670) and Muslim (2774).","chapter_en":"What is reported about the prohibition of praying over hypocrites and polytheists and seeking forgiveness for them","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Ibn ʿUmar reported: When ʿAbdullāh ibn Ubayy ibn Salūl died, his son ʿAbdullāh ibn ʿAbdullāh came to the Messenger of Allah ﷺ and asked him to give him his shirt so that he could shroud his father in it. The Prophet ﷺ gave it to him. Then he asked the Prophet ﷺ to perform the funeral prayer over him. The Messenger of Allah ﷺ stood to pray over him, but ʿUmar stood and took hold of the garment of the Messenger of Allah ﷺ and said: “O Messenger of Allah ﷺ, will you pray over him when your Lord has forbidden you to pray over him?” The Messenger of Allah ﷺ replied: “Allah only gave me a choice, saying: ‘Ask forgiveness for them or do not ask forgiveness for them. Even if you ask forgiveness for them seventy times…’ and I will exceed seventy.” ʿUmar said: “He is a hypocrite.” Nevertheless, the Messenger of Allah ﷺ prayed over him. Then Allah revealed: “And never perform the funeral prayer over any of them who dies, nor stand at his grave.”  [Surah al-Tawbah 9:84] In Muslim’s narration: “So he ceased performing the funeral prayer over them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4670)، ومسلم (2774)."},{"num":3741,"demo":false,"sanad":"","matn":["عَنْ المسيب بن حَزْن قَالَ: لَمَّا حضر أَبَا طَالِبٍ الْوَفَاةُ دَخَلَ عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ أَبُو جَهْلٍ وعبدالله بْنُ أَبِي أُمَيَّةَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أي عَمِّ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ أُحَاجُّ لَكَ بِهَا عِنْدَ اللَّهِ فَقَالَ أَبُو جَهْلٍ وعبدالله بْنُ أَبِي أُمَيَّةَ: يَا أَبَا طَالِبٍ! أَتَرْغَبُ عَنْ مِلَّةِ عبدالمطلب؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنه عَنْكَ فَنَزَلَتْ: ﴿مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ﴾ [سورة التَّوْبَةِ:113]."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4675)، ومسلم في الإيمان (24/40) كلاهما عن إسحاق بن إبراهيم، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن سعيد بن المسيب، عن أبيه فذكره، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء من النهي عن الصلاة على المنافقين والمشركين والاستغفار لهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4675) and Muslim (24).","chapter_en":"What is reported about the prohibition of praying over hypocrites and polytheists and seeking forgiveness for them","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Al-Musayyib ibn Ḥazn reported: When death approached Abū Ṭālib, the Prophet ﷺ entered upon him while Abū Jahl and ʿAbdullāh ibn Abī Umayyah were with him. The Prophet ﷺ said: “O uncle, say: ‘There is no deity worthy of worship except Allah,’ a statement by which I will argue on your behalf before Allah.” Abū Jahl and ʿAbdullāh ibn Abī Umayyah said: “O Abū Ṭālib, will you turn away from the religion of ʿAbd al-Muṭṭalib?” They continued speaking to him until the last thing he said to them was: “I am upon the religion of ʿAbd al-Muṭṭalib.” He refused to say: “There is no deity worthy of worship except Allah.” The Prophet ﷺ then said: “I will continue to seek forgiveness for you unless I am forbidden from doing so.” Then Allah revealed: “It is not for the Prophet and those who believe to seek forgiveness for the polytheists, even if they are close relatives, after it has become clear to them that they are companions of the Hellfire.”  [Surah al-Tawbah 9:113] And He revealed: “Indeed, you do not guide whom you love, but Allah guides whom He wills.”  [Surah al-Qaṣaṣ 28:56]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11427],"tks":"متفق عليه: رواه البخاري (4675)، ومسلم (24)."},{"num":3742,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعَمِّهِ عِنْدَ الْمَوْتِ: قُلْ: لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ لَكَ بِهَا يَوْمَ الْقِيَامَةِ، فَأَبَى، فَأَنْزَلَ اللَّهُ: ﴿إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ﴾، الْآيَةَ ."],"takhrij":"صحيح: رواه مسلم في الإيمان (25) من طرق عن مروان، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة فذكر الحديث، ورواه من وجه آخر عن يحيى بن سعيد، حدثنا يزيد بن كيسان بإسناده، وذكر فيه قول أبي طالب: لولا أن تُعيّرني قريش يقولون: إنما حمله على ذلك الجزع، لأقررت بها عينك.","grade":"صحيح","chapter_ar":"باب ما جاء من النهي عن الصلاة على المنافقين والمشركين والاستغفار لهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (25).","chapter_en":"What is reported about the prohibition of praying over hypocrites and polytheists and seeking forgiveness for them","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said to his uncle at the time of death: “Say: There is no god but Allah, and I will testify for you with it on the Day of Resurrection.” But he refused. So Allah revealed: “You do not guide whom you love.” [28:56]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (25)."},{"num":3743,"demo":false,"sanad":"","matn":["عن جابر قال: لما مات أبو طالب قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رحمك الله وغفر لك يا عم، ولا أزال أستغفر لك حتى ينهاني الله عزوجل فأخذ المسلمون يستغفرون لموتاهم الذين ماتوا وهم مشركون، فأنـزل الله تعـالـى: ﴿مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ﴾ [سورة التوبة: 113]."],"takhrij":"صحيح: رواه الحاكم (3290) من طريق أبي حمة اليماني، ثنا سفيان بن عيينة، عن عمرو بن دينار، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من النهي عن الصلاة على المنافقين والمشركين والاستغفار لهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Ḥākim (3290).","chapter_en":"What is reported about the prohibition of praying over hypocrites and polytheists and seeking forgiveness for them","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Jābir said: When Abū Ṭālib died, the Messenger of Allah ﷺ said: “May Allah have mercy on you and forgive you, O uncle. I will keep seeking forgiveness for you until Allah, Mighty and Majestic, forbids me.” Then the Muslims began seeking forgiveness for their dead who had died while being polytheists, so Allah revealed: “It is not for the Prophet and those who believe to seek forgiveness for the polytheists, even if they are close relatives, after it has become clear to them that they are the people of the Fire.” [9:113]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (3290)."},{"num":3744,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ قَالَ: سَمِعْتُ رَجُلًا، يَسْتَغْفِرُ لِأَبَوَيْهِ وَهُمَا مُشْرِكَانِ، فَقُلْتُ: أَتَسْتَغْفِرُ لَهُمَا وَهُمَا مُشْرِكَانِ؟ فَقَالَ: أَوَلَمْ يَسْتَغْفِرْ إِبْرَاهِيمُ لِأَبِيهِ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَذَكَرْتُ ذَلِكَ لَهُ فَنَزَلَتْ: ﴿وَمَا كَانَ اسْتِغْفَارُ إِبْرَاهِيمَ لِأَبِيهِ إِلَّا عَنْ مَوْعِدَةٍ وَعَدَهَا إِيَّاهُ﴾ [التوبة:"],"takhrij":"حسن: رواه الترمذي (3101)، والنسائي (2036) كلاهما من حديث سفيان، عن أبي إسحاق، عن أبي الخليل، عن علي بن أبي طالب فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من النهي عن الصلاة على المنافقين والمشركين والاستغفار لهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Tirmidhī (3101), who graded it Hasan, and al-Nasā’ī (2036).","chapter_en":"What is reported about the prohibition of praying over hypocrites and polytheists and seeking forgiveness for them","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib said: I heard a man seeking forgiveness for his parents even though they were polytheists, so I said: “Do you seek forgiveness for them while they are polytheists?” He said: “Did not Ibrāhīm seek forgiveness for his father?” So I came to the Prophet ﷺ and mentioned that to him, and then the verse was revealed: “And the seeking forgiveness of Ibrāhīm for his father was only because of a promise he had made to him.” [9:114]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3101) وحسنه، والنسائي (2036)."},{"num":3745,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ أُتِيَ بِجَنَازَةٍ، فَقَالُوا: صَلِّ عَلَيْهَا. فَقَالَ: هَلْ عَلَيْهِ دَيْنٌ. قَالُوا: لاَ. قَالَ: فَهَلْ تَرَكَ شَيْئًا. قَالُوا: لاَ. فَصَلَّى عَلَيْهِ، ثُمَّ أُتِيَ بِجَنَازَةٍ أُخْرَى، فَقَالُوا: يَا رَسُولَ اللَّهِ، صَلِّ عَلَيْهَا. قَالَ: هَلْ عَلَيْهِ دَيْنٌ. قِيلَ: نَعَمْ. قَالَ: فَهَلْ تَرَكَ شَيْئًا. قَالُوا: ثَلاَثَةَ دَنَانِيرَ. فَصَلَّى عَلَيْهَا، ثُمَّ أُتِيَ بِالثَّالِثَةِ، فَقَالُوا: صَلِّ عَلَيْهَا. قَالَ: هَلْ تَرَكَ شَيْئًا. قَالُوا: لاَ. قَالَ: فَهَلْ عَلَيْهِ دَيْنٌ. قَالُوا: ثَلاَثَةُ دَنَانِيرَ. قَالَ: صَلُّوا عَلَى صَاحِبِكُمْ.","قَالَ أَبُو قَتَادَةَ: صَلِّ عَلَيْهِ يَا رَسُولَ اللَّهِ وَعَلَىَّ دَيْنُهُ، فَصَلَّى عَلَيْهِ."],"takhrij":"صحيح: رواه البخاري في الكفالة (2289، 2295) من طريقين عن المكي بن إبراهيم، وأبي عاصم، كلاهما عن يزيد بن أبي عبيد، عن سلمة بن الأكوع، فذكره، واللفظ للمكي، ولفظ أبي عاصم مختصر.","grade":"صحيح","chapter_ar":"باب لا يُصلِّي الإمام على من عليه دَيْنٌ حتى يُقضى عنه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (2289, 2295).","chapter_en":"The imam does not pray over one who has debts until they are paid on his behalf","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: We were sitting with the Prophet ﷺ when a funeral was brought, and they said: “Pray over him.” He said: “Does he have any debt?” They said: “No.” He said: “Did he leave anything behind?” They said: “No.” So he prayed over him. Then another funeral was brought, and they said: “O Messenger of Allah ﷺ, pray over him.” He said: “Does he have any debt?” It was said: “Yes.” He said: “Did he leave anything behind?” They said: “Three dinars.” So he prayed over him. Then a third was brought, and they said: “Pray over him.” He said: “Did he leave anything behind?” They said: “No.” He said: “Does he have any debt?” They said: “Three dinars.” He said: “Pray over your companion.” Abū Qatādah said: “Pray over him, O Messenger of Allah ﷺ, and I will take responsibility for his debt.” So he prayed over him."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2289، 2295)."},{"num":3746,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أتى بِجَنَازَةٍ رجل لِيُصَلِّيَ عَلَيْهَا فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : صَلُّوا عَلَى صَاحِبِكُمْ، فَإِنَّ عَلَيْهِ دَيْنًا .","قَالَ أَبُو قَتَادَةَ: هُوَ عَلَىَّ.","فقال رسول الله صلى الله عليه وسلم: بالوفاء ؟ قال: بالوفاء، فصلى عليه.","وفي رواية كان عليه ثمانية عشر، أو تسعة عشر درهما."],"takhrij":"صحيح: رواه الترمذي (1069)، والنسائي (1960)، وابن ماجه (2407) كلهم من طرق عن شعبة، عن عثمان بن عبدالله بن موهب، قال: سمعت عبدالله بن أبي قتادة، عن أبيه فذكره. والرواية الثانية ذكرها ابن ماجه.","grade":"صحيح","chapter_ar":"باب لا يُصلِّي الإمام على من عليه دَيْنٌ حتى يُقضى عنه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Tirmidhī (1069), al-Nasā’ī (1960), and the second narration is mentioned by Ibn Mājah (2407).","chapter_en":"The imam does not pray over one who has debts until they are paid on his behalf","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Abū Qatādah reported that the Prophet ﷺ was brought the funeral of a man so that he could pray over him, and the Prophet ﷺ said: “Pray over your companion, for he has a debt.” Abū Qatādah said: “It is upon me.” The Messenger of Allah ﷺ said: “With commitment to full payment?”","He said: “With full payment.”","So he prayed over him. In another narration: He owed eighteen, or nineteen, dirhams."]},"buhuth":{"en":["Al-Tirmidhī said: Hasan Sahih. Ibn Khuzaymah also authenticated it (3060)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1069)، والنسائي (1960)، والرواية الثانية ذكرها ابن ماجه (2407)."},{"num":3747,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: تُوُفِّيَ رَجُلٌ فَغَسَّلْنَاهُ، وَحَنَّطْنَاهُ، وَكَفَّنَّاهُ، ثُمَّ أَتَيْنَا بِهِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَيْهِ، فَقُلْنَا: تُصَلِّي عَلَيْهِ؟ فَخَطَا خُطًى، ثُمَّ قَالَ: أَعَلَيْهِ دَيْنٌ؟ قُلْنَا: دِينَارَانِ، فَانْصَرَفَ، فَتَحَمَّلَهُمَا أَبُو قَتَادَةَ، فَأَتَيْنَاهُ، فَقَالَ أَبُو قَتَادَةَ: الدِّينَارَانِ عَلَيَّ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: حَقُّ الْغَرِيمُ، وَبَرِئَ مِنْهُمَا الْمَيِّتُ؟ قَالَ: نَعَمْ، فَصَلَّى عَلَيْهِ، ثُمَّ قَالَ بَعْدَ ذَلِكَ بِيَوْمٍ: مَا فَعَلَ الدِّينَارَانِ؟ فَقَالَ: إِنَّمَا مَاتَ أَمْسِ، قَالَ: فَعَادَ إِلَيْهِ مِنَ الْغَدِ، فَقَالَ: لَقَدْ قَضَيْتُهُمَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْآنَ بَرَدَتْ عَلَيْهِ جِلْدُهُ."],"takhrij":"حسن: رواه الإمام أحمد (14536) عن عبد الصمد وأبي سعيد، المعنى، قالا: حدثنا زائدة، عن عبدالله بن محمد بن عَقيل، عن جابر بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب لا يُصلِّي الإمام على من عليه دَيْنٌ حتى يُقضى عنه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (14536), al-Ḥākim (2/58).","chapter_en":"The imam does not pray over one who has debts until they are paid on his behalf","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: A man died, so we washed him, perfumed him, and shrouded him. Then we brought him to the Messenger of Allah ﷺ for him to pray over him. We said: “Will you pray over him?” He took a few steps, then said: “Does he have any debt?” We said: “Two dinars.” So he turned away. Then Abū Qatādah took responsibility for them, and we came back to him. Abū Qatādah said: “The two dinars are upon me.” The Messenger of Allah ﷺ said: “Has the creditor’s right been secured, and has the deceased been cleared of them?” He said: “Yes.” So he prayed over him. Then one day later he said: “What happened to the two dinars?” He said: “He only died yesterday.” Then he returned to him the next day and said: “I have paid them.” So the Messenger of Allah ﷺ said: “Now you have cooled his skin for him.”"]},"buhuth":{"en":["Regarding the phrase “Has the creditor’s right been secured, and has the deceased been cleared of them?” al-Bayhaqī said: “If Ibn ʿAqīl preserved this wording correctly, then what it means — and Allah knows best — is that the creditor may demand it from you alone if he wishes, just as if he had another right against you by some other cause, and the deceased is cleared of it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (14536)، والحاكم (2/58)."},{"num":3748,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: تُوُفِّيَ رَجُلٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يُوجَدْ لَهُ كَفَنٌ، فَأُتِي - النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: انْظُرُوا إِلَى دَاخِلَةِ إِزَارِهِ، فَأُصِيبَ دِينَارٌ، أَوْ دِينَارَانِ، فَقَالَ: كَيَّتَانِ صَلُّوا عَلَى صَاحِبِكُمْ [فَقَالَ رَجُلٌ: إِلَيَّ قَضَائُهُمَا يَا رَسُولَ اللَّهِ، فَصَلَّى عَلَيْهِ]."],"takhrij":"حسن: رواه الطبراني في الكبير (7506) عن محمد بن أحمد بن أبي خيثمة، ثنا عبدالرحمن بن يونس الرقي، ثنا عقبة بن علقمة، عن أرطاة بن المنذر، عن ضمرة بن حبيب، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب لا يُصلِّي الإمام على من عليه دَيْنٌ حتى يُقضى عنه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Kabīr (4/124).","chapter_en":"The imam does not pray over one who has debts until they are paid on his behalf","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Abū Umāmah said: A man died during the time of the Messenger of Allah ﷺ, and no shroud was found for him. So they came to the Prophet ﷺ and he said: “Look into the inside fold of his waist-wrapper.” A dinar or two dinars were found. So he said: “Two cauteries — pray over your companion.” Then a man said: “I will take care of paying it, O Messenger of Allah ﷺ.” So he prayed over him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (7470)."},{"num":3749,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِجِنَازَةٍ، فَقَامَ يُصَلِّي عَلَيْهَا، فَقَالُوا: عَلَيْهِ دَيْنٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: انْطَلِقُوا بِصَاحِبِكُمْ، فَصَلُّوا عَلَيْهِ، فَقَالَ رَجُلٌ: عَلَيَّ دَيْنُهُ، فَصَلِّ عَلَيْهِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّى عَلَيْهِ."],"takhrij":"حسن: رواه البزار (7804) عن محمد بن معمر، قال: نا روح بن عبادة قال: نا محمد بن أبي حفصة، عن الزهري، عن سعيد بن المسيب، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب لا يُصلِّي الإمام على من عليه دَيْنٌ حتى يُقضى عنه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bazzār (7804).","chapter_en":"The imam does not pray over one who has debts until they are paid on his behalf","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ was brought a funeral and stood to pray over it. They said: “He has a debt.” So the Messenger of Allah ﷺ said: “Take your companion and pray over him.” Then a man said: “His debt is upon me, so pray over him.” So the Messenger of Allah ﷺ stood and prayed over him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (7804)."},{"num":3750,"demo":false,"sanad":"","matn":["عن أَسْمَاءَ بِنْتِ يَزِيدَ قَالَتْ: دُعِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى جِنَازَةِ رَجُلٍ مِنَ الْأَنْصَارِ، فَلَمَّا وُضِعَ السَّرِيرُ تَقَدَّمَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ عَلَيْهِ، ثُمَّ الْتَفَتَ فَقَالَ: عَلَى صَاحِبِكُمْ دَيْنٌ؟ قَالُوا: نَعَمْ يَا رَسُولَ اللَّهِ ; دِينَارَانِ، قَالَ: صَلُّوا عَلَى صَاحِبِكُمْ، فَقَالَ أَبُو قَتَادَةَ: أَنَا بِدَيْنِهِ يَا نَبِيَّ اللَّهِ، فَصَلَّى عَلَيْهِ."],"takhrij":"حسن: رواه الطبراني في الكبير (24/ح 466) عن يحيى بن عثمان بن صالح، ثنا عبدالله بن يوسف، ثنا محمد بن مهاجر، عن أبيه، قال: حدثتنا أسماء بنت يزيد فذكرته.","grade":"حسن","chapter_ar":"باب لا يُصلِّي الإمام على من عليه دَيْنٌ حتى يُقضى عنه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭabarānī in al-Kabīr (24/184).","chapter_en":"The imam does not pray over one who has debts until they are paid on his behalf","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Asmā’ bint Yazīd said: The Messenger of Allah ﷺ was called to the funeral of a man from the Anṣār. When the bier was placed down, the Prophet of Allah ﷺ stepped forward to pray over him, then turned and said: “Does your companion have a debt?” They said: “Yes, O Messenger of Allah ﷺ — two dinars.” So he said: “Pray over your companion.” Then Abū Qatādah said: “We will assume his debt, O Prophet of Allah ﷺ.” So he prayed over him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (24/ح 466)."},{"num":3751,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُؤْتَى بِالرَّجُلِ الْمُتَوَفَّى عَلَيْهِ الدَّيْنُ، فَيَسْأَلُ: هَلْ تَرَكَ لِدَيْنِهِ فَضْلاً. فَإِنْ حُدِّثَ أَنَّهُ تَرَكَ لِدَيْنِهِ وَفَاءً صَلَّى، وَإِلاَّ قَالَ لِلْمُسْلِمِينَ: صَلُّوا عَلَى صَاحِبِكُمْ. فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ الْفُتُوحَ قَالَ: أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ، فَمَنْ تُوُفِّيَ مِنَ الْمُؤْمِنِينَ فَتَرَكَ دَيْنًا فَعَلَىَّ قَضَاؤُهُ، وَمَنْ تَرَكَ مَالاً فَلِوَرَثَتِهِ."],"takhrij":"متفق عليه: رواه البخاري في الكفالة (2298)، ومسلم في الفرائض (1619) كلاهما من حديث الليث، عن عُقيل، عن ابن شهاب، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نسخ ترك الصلاة على من مات وعليه دَيْن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (2298), Muslim (1619).","chapter_en":"What is reported about the later abrogation of leaving the funeral prayer for one who died with unpaid debt","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":31,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ used to be brought a man who had died with debt, and he would ask: “Did he leave enough to cover his debt?” If he was told that he had left enough to pay it, he would pray over him. Otherwise he would say to the Muslims: “Pray over your companion.” Then when Allah granted him victories, he said: “I am closer to the believers than their own selves. So whoever among the believers dies and leaves a debt, I am responsible for paying it. And whoever leaves wealth, it belongs to his heirs.”"]},"buhuth":{"en":["Al-Ṭayālisī said: “By this, those hadiths that mention leaving the prayer over the one who had debt were abrogated.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13035],"tks":"متفق عليه: رواه البخاري (2298)، ومسلم (1619)."},{"num":3752,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يُصَلِّي عَلَى رَجُلٍ مَاتَ وَعَلَيْهِ دَيْنٌ، فَأُتِيَ بِمَيِّتٍ فَقَالَ: أَعَلَيْهِ دَيْنٌ. قَالُوا: نَعَمْ، دِينَارَانِ. قَالَ: صَلُّوا عَلَى صَاحِبِكُمْ. فَقَالَ أَبُو قَتَادَةَ الأَنْصَارِيُّ: هُمَا عَلَىَّ يَا رَسُولَ اللَّهِ. قَالَ: فَصَلَّى عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا فَتَحَ اللَّهُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ، فَمَنْ تَرَكَ دَيْنًا فَعَلَىَّ قَضَاؤُهُ، وَمَنْ تَرَكَ مَالاً فَلِوَرَثَتِهِ."],"takhrij":"صحيح: رواه أبو داود (3343)، والنسائي (1962) كلاهما من حديث عبد الرزاق وهو في مصنفه abdrazzaq(15257) عن معمر، عن الزهري، عن أبي سلمة، عن جابر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في نسخ ترك الصلاة على من مات وعليه دَيْن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3343), al-Nasā’ī (1962), ʿAbd al-Razzāq (15257), authenticated by Ibn Ḥibbān (3064).","chapter_en":"What is reported about the later abrogation of leaving the funeral prayer for one who died with unpaid debt","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":31,"content":{"translation":{"en":["Jābir said: The Messenger of Allah ﷺ would not pray over a man who died while owing a debt. Then a deceased person was brought, and he said: “Does he have a debt?” They said: “Yes, two dinars.” He said: “Pray over your companion.” Then Abū Qatādah al-Anṣārī said: “They are upon me, O Messenger of Allah ﷺ.” So the Messenger of Allah ﷺ prayed over him. Then when Allah granted victory to His Messenger ﷺ, he said: “I am closer to every believer than his own self. So whoever leaves a debt, I am responsible for paying it. And whoever leaves wealth, it belongs to his heirs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3343)، والنسائي (1962)، وعبد الرزاق (15257)، وصححه ابن حبان (3064)."},{"num":3753,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ حُمِّلَ مِنْ أُمَّتِي دَيْنًا، ثُمَّ جَهِدَ فِي قَضَائِهِ، فَمَاتَ وَلَمْ يَقْضِهِ، فَأَنَا وَلِيُّهُ."],"takhrij":"صحيح: رواه أحمد (24455، 25211) –والسياق له، وإسحاق بن راهويه في مسنده (1063)، وأبو يعلى (4838) كلهم من طرقٍ عن ابن شهاب، عن أبي سلمة، عن عائشة فذكرتْه. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في نسخ ترك الصلاة على من مات وعليه دَيْن","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Aḥmad (24455, 25211) — this wording is from him — and Isḥāq ibn Rāhawayh in his Musnad (1063).","chapter_en":"What is reported about the later abrogation of leaving the funeral prayer for one who died with unpaid debt","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":31,"content":{"translation":{"en":["ʿĀ’ishah said: The Messenger of Allah ﷺ said: “Whoever from my ummah takes on a debt, then strives hard to repay it, but dies before repaying it, then I am his guardian.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (24455، 25211) — والسياق له —، وإسحاق بن راهويه في مسنده (1063)."},{"num":3754,"demo":false,"sanad":"","matn":["عَنْ أَبِي عَطِيَّةَ أَنَّ رَجُلًا تُوُفِّيَ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ بَعْضُهُمْ يَا رَسُولَ اللَّهِ! لاَ تُصَلِّ عَلَيْهِ، فَقَالَ: هَلْ رَآهُ أَحَدٌ مِنْكُمْ عَلَى شَيْءٍ مِنْ أعمال الْخَيْرِ فَقَالَ رَجُلٌ: حَرَسَ مَعَنَا لَيْلَةَ كَذَا وَكَذَا، قَالَ: فَصَلَّى عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ مَشَى إِلَى قَبْرِهِ ثُمَّ حَثَا عَلَيْهِ وَيَقُولُ: إِنَّ أَصْحَابَكَ يَظُنُّونَ أَنَّكَ مِنْ أَهْلِ النَّارِ، وَأَنَا أَشْهَدُ أَنَّكَ مِنْ أَهْلِ الْجَنَّةِ ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعُمَرَ: إِنَّكَ لا تَسْأَلُ عَنْ أَعْمَالِ النَّاسِ، وَإِنَّمَا تَسْأَلُ عَنِ الْغَيْبَةِ ..","وفي رواية: وإنما تسأل عن الفطرة ."],"takhrij":"حسن: أخرجه أبو يعلى –المطالب العالية (888) والبغوي وأبو أحمد والحاكم كما في الإصابة (4/134) كلهم من طريق إسماعيل بن عياش، حدثنا بحير بن سعد، عن خالد بن معدان، عن أبي عطية.","grade":"حسن","chapter_ar":"باب الصلاة على كل من عمل خيرًا","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: reported by Abū Yaʿlā — al-Maṭālib al-ʿĀliyah (888).","chapter_en":"Praying over everyone who did some good","part_en":"The Book of Funerals","group_ar":"جموع أبواب الصلاة على الجنازة","group_en":"Compilation of chapters on the funeral prayer","part_no":13,"group_no":7,"chapter_no":32,"content":{"translation":{"en":["Abū ʿAṭiyyah reported that a man died during the time of the Messenger of Allah ﷺ, and some people said: “O Messenger of Allah ﷺ, we will not pray over him.” So he said: “Did any of you see him doing any act of good?” A man said: “He stood guard with us on such-and-such a night.” So the Messenger of Allah ﷺ prayed over him, then walked to his grave, then threw soil over it while saying: “Your companions think that you are from the people of the Fire, but I testify that you are from the people of Paradise.” Then the Messenger of Allah ﷺ said to ʿUmar: “You are not asked about the deeds of people; rather, you are only asked about the unseen.” And in another narration: “Rather, you are only asked about the natural disposition.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أخرجه أبو يعلى — المطالب العالية (888)."},{"num":3755,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ الرَّجُلَيْنِ مِنْ قَتْلَى أُحُدٍ فِي ثَوْبٍ وَاحِدٍ، ثُمَّ يَقُولُ: أَيُّهُمْ أَكْثَرُ أَخْذًا لِلْقُرْآنِ. فَإِذَا أُشِيرَ لَهُ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ وَقَالَ: أَنَا شَهِيدٌ عَلَى هَؤُلاَءِ يَوْمَ الْقِيَامَةِ. وَأَمَرَ بِدَفْنِهِمْ فِي دِمَائِهِمْ، وَلَمْ يُغَسَّلُوا، وَلَمْ يُصَلَّ عَلَيْهِمْ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1343) عن عبدالله بن يوسف، حدثنا الليث، قال: حدثني ابن شهاب، عن عبدالرحمن بن كعب بن مالك، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب أن الشهيد في سبيل الله لا يُغسَّل ولا يُنزع منه ثيابه التي استُشهد فيها، ولا يُصلَّى عليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1343).","chapter_en":"The martyr in the path of Allah is not washed, his clothes in which he was martyred are not removed, and the funeral prayer is not offered over him","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في غسل الشهداء والصلاة عليهم ودفنهم","group_en":"Compilation of chapters on washing martyrs, praying over them, and burying them","part_no":13,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Prophet ﷺ used to place two men from the martyrs of Uḥud together in one cloth, then say: “Which of them had memorized more of the Qur’an?” When one of them was pointed out, he placed him first in the burial niche and said: “I will be a witness for these on the Day of Resurrection.” He ordered that they be buried in their blood, and they were not washed and no funeral prayer was offered over them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8108],"tks":"صحيح: رواه البخاري (1343)."},{"num":3756,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي مَغْزًى لَهُ، فَأَفَاءَ اللهُ عَلَيْهِ، فَقَالَ لِأَصْحَابِهِ: هَلْ تَفْقِدُونَ مِنْ أَحَدٍ؟ قَالُوا: نَعَمْ، فُلَانًا وَفُلَانًا وَفُلَانًا، ثُمَّ قَالَ: هَلْ تَفْقِدُونَ مِنْ أَحَدٍ؟ قَالُوا: نَعَمْ، فُلَانًا وَفُلَانًا وَفُلَانًا، ثُمَّ قَالَ: هَلْ تَفْقِدُونَ مِنْ أَحَدٍ؟ قَالُوا: لَا. قَالَ: لَكِنِّي أَفْقِدُ جُلَيْبِيبًا، فَاطْلُبُوهُ. فَطُلِبَ فِي الْقَتْلَى، فَوَجَدُوهُ إِلَى جَنْبِ سَبْعَةٍ قَدْ قَتَلَهُمْ، ثُمَّ قَتَلُوهُ، فَأَتَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَقَفَ عَلَيْهِ فَقَالَ: قَتَلَ سَبْعَةً، ثُمَّ قَتَلُوهُ، هَذَا مِنِّي، وَأَنَا مِنْهُ، هَذَا مِنِّي وَأَنَا مِنْهُ. قَالَ: فَوَضَعَهُ عَلَى سَاعِدَيْهِ، لَيْسَ لَهُ إِلَّا سَاعِدَا النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَحُفِرَ لَهُ، وَوُضِعَ فِي قَبْرِهِ، وَلَمْ يَذْكُرْ غَسْلًا."],"takhrij":"صحيح: رواه مسلم في المناقب (2472) عن إسحاق بن عمر بن سَليط، حدثنا حماد بن سلمة، عن ثابت، عن كِنانة بن نُعيم، عن أبي برزة فذكره.","grade":"صحيح","chapter_ar":"باب أن الشهيد في سبيل الله لا يُغسَّل ولا يُنزع منه ثيابه التي استُشهد فيها، ولا يُصلَّى عليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (2472).","chapter_en":"The martyr in the path of Allah is not washed, his clothes in which he was martyred are not removed, and the funeral prayer is not offered over him","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في غسل الشهداء والصلاة عليهم ودفنهم","group_en":"Compilation of chapters on washing martyrs, praying over them, and burying them","part_no":13,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abū Barzah reported that the Prophet ﷺ was on a military expedition, and Allah granted victory to him. He said to his companions: “Are any of you missing anyone?” They said: “Yes, so-and-so, and so-and-so, and so-and-so.” Then he said: “Are any of you missing anyone?” They said: “Yes, so-and-so, and so-and-so, and so-and-so.” Then he said: “Are any of you missing anyone?” They said: “No.” He said: “But I am missing Julaybīb, so look for him.” They searched for him and found him beside seven men whom he had killed before they killed him. Then the Prophet ﷺ came and stood over him and said: “He killed seven, and then they killed him. He is from me and I am from him. He is from me and I am from him.” He said: Then he placed him on his forearms, for he had no bier except the forearms of the Prophet ﷺ. He said: Then a grave was dug for him, and he was placed in it, and washing was not mentioned."]}},"tuhfa":{},"full":1,"rep":[10136],"tks":"صحيح: رواه مسلم (2472)."},{"num":3757,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن الزُّبَيْرِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: وَقَدْ كَانَ النَّاسُ انْهَزَمُوا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى انْتَهَى بَعْضُهُمْ إِلَى دُونِ الأَعْرَاضِ إِلَى جَبَلٍ بِنَاحِيَةِ الْمَدِينَةِ، ثُمَّ رَجَعُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَقَدْ كَانَ حَنْظَلَةُ بْنُ أَبِي عَامِرٍ الثقفي هُوَ، وَأَبُو سُفْيَانَ بْنُ حَرْبٍ، فَلَمَّا اسْتَعْلَاهُ حَنْظَلَةُ رَآهُ شَدَّادُ بْنُ الأَسْوَدِ، فَعَلَاهُ شَدَّادٌ بِالسَّيْفِ حَتَّى قَتَلَهُ، وَقَدْ كَادَ يَقْتُلُ أَبَا سُفْيَانَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ صَاحِبَكُمْ حَنْظَلَةَ تُغَسِّله الْمَلَائِكَةُ، فَسَلُوا صَاحِبَتَهُ . فَقَالَتْ: خَرَجَ وَهُوَ جُنُبٌ لَمَّا سَمِعَ الْهَائِعَةَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : فَذَاكَ قَدْ غسَّلتْه الْمَلَائِكَةُ ."],"takhrij":"حسن: رواه ابن حبان في صحيحه (7025)، والحاكم (3/204) من طريق محمد بن إسحاق بن إبراهيم، ثنا سعيد بن يحيى الأموي، حدثني أبي، قال: قال ابن إسحاق، حدثني يحيى بن عباد بن عبدالله، عن أبيه، عن جده فذكر الحديث.","grade":"حسن","chapter_ar":"باب أن الشهيد في سبيل الله لا يُغسَّل ولا يُنزع منه ثيابه التي استُشهد فيها، ولا يُصلَّى عليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Ibn Ḥibbān in his Ṣaḥīḥ (7025), al-Ḥākim (3/204).","chapter_en":"The martyr in the path of Allah is not washed, his clothes in which he was martyred are not removed, and the funeral prayer is not offered over him","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في غسل الشهداء والصلاة عليهم ودفنهم","group_en":"Compilation of chapters on washing martyrs, praying over them, and burying them","part_no":13,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn al-Zubayr said: I heard the Messenger of Allah ﷺ say — after people had fled from the Messenger of Allah ﷺ until some of them reached near the outskirts of Madinah, toward a mountain in that area, then returned to the Messenger of Allah ﷺ — and Ḥanẓalah ibn Abī ʿĀmir had encountered Abū Sufyān ibn Ḥarb in combat. When Ḥanẓalah overcame him, Shaddād ibn al-Aswad saw him, then struck Ḥanẓalah with the sword and killed him, though he had almost killed Abū Sufyān. Then the Messenger of Allah ﷺ said: “Your companion Ḥanẓalah is being washed by the angels, so ask his wife.” She said: “He went out while in a state of janābah when he heard the alarm.” So the Messenger of Allah ﷺ said: “That is why the angels washed him.”"]},"buhuth":{"en":["The phrase “the outskirts of Madinah” means its villages in its valleys. It was also said that it means the dark fertile areas of Madinah where crops and palm trees were found.","Her phrase “the alarm” means the sound that causes fear and alarm."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان في صحيحه (7025)، والحاكم (3/204)."},{"num":3758,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: رُمِيَ رَجُلٌ بِسَهْمٍ فِي صَدْرِهِ، أَوْ فِي حَلْقِهِ فَمَاتَ، فَأُدْرِجَ فِي ثِيَابِهِ كَمَا هُوَ، - قَالَ - وَنَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه أبو داود (3133) وأحمد (14952) كلاهما من طرق عن إبراهيم بن طهمان، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب أن الشهيد في سبيل الله لا يُغسَّل ولا يُنزع منه ثيابه التي استُشهد فيها، ولا يُصلَّى عليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3133), Aḥmad (14952).","chapter_en":"The martyr in the path of Allah is not washed, his clothes in which he was martyred are not removed, and the funeral prayer is not offered over him","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في غسل الشهداء والصلاة عليهم ودفنهم","group_en":"Compilation of chapters on washing martyrs, praying over them, and burying them","part_no":13,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Jābir said: A man was struck by an arrow in his chest, or in his throat, and he died. So he was wrapped in his clothes just as he was, while we were with the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3133)، وأحمد (14952)."},{"num":3759,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَتْلَى أُحُدٍ بَعْدَ ثَمَانِي سِنِينَ، كَالْمُوَدِّعِ لِلأَحْيَاءِ وَالأَمْوَاتِ، ثُمَّ طَلَعَ الْمِنْبَرَ فَقَالَ: إِنِّي بَيْنَ أَيْدِيكُمْ فَرَطٌ، وَأَنَا عَلَيْكُمْ شَهِيدٌ، وَإِنَّ مَوْعِدَكُمُ الْحَوْضُ، وَإِنِّي لأَنْظُرُ إِلَيْهِ مِنْ مَقَامِي هَذَا، وَإِنِّي لَسْتُ أَخْشَى عَلَيْكُمْ أَنْ تُشْرِكُوا، وَلَكِنِّي أَخْشَى عَلَيْكُمُ الدُّنْيَا أَنْ تَنَافَسُوهَا. قَالَ: فَكَانَتْ آخِرَ نَظْرَةٍ نَظَرْتُهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4042)، ومسلم في الفضائل (2296) كلاهما من حديث يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر فذكره، واللفظ للبخاري، ولفظ مسلم قريب منه وفيه: فصلَّى على أهل أُحد صلاته على الميت .","grade":"متفق عليه","chapter_ar":"باب من قال: يُصلَّى على الشهيد في سبيل الله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (4042), Muslim (2296). Muslim’s wording includes: “He prayed over the people of Uḥud with the prayer he used for the dead.”","chapter_en":"Those who held that the martyr in the path of Allah is prayed over","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في غسل الشهداء والصلاة عليهم ودفنهم","group_en":"Compilation of chapters on washing martyrs, praying over them, and burying them","part_no":13,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir said: The Messenger of Allah ﷺ prayed over the martyrs of Uḥud after eight years, like one bidding farewell to the living and the dead. Then he ascended the pulpit and said: “I am preceding you, and I am a witness over you. Your appointment is at the Pond, and I can see it from where I stand now. I do not fear that you will commit shirk after me, but I fear that you will compete for this world.” He said: That was the last look I had of the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"rep":[825],"tks":"متفق عليه: رواه البخاري (4042)، ومسلم (2296). وفي مسلم: (( فصلى على أهل أحد صلاته على الميت ))."},{"num":3760,"demo":false,"sanad":"","matn":["عَنْ شَدَّادِ بْنِ الْهَادِ أَنَّ رَجُلًا مِنَ الْأَعْرَابِ جَاءَ إِلَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فآمن بِهِ واتَّبعه ثُمَّ قَالَ: أُهَاجِرُ مَعَكَ، فَأَوْصَى بِهِ النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بعض أَصْحَابَهُ، فَلَمَّا كَانَتْ غَزْوَةُ غَنِمَ النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سبياً فقَسَمَ وقَسَمَ لَهُ، فَأَعْطَى أَصْحَابَهُ مَا قَسَمَ لَهُ وَكَانَ يَرْعَى ظَهْرَهُمْ، فَلَمَّا جَاءَ دَفَعُوهُ إِلَيْهِ فَقَالَ: مَا هَذَا؟ قَالُوا: قَسْم قَسَمَهُ لَكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخَذَهُ فَجَاءَ بِهِ إِلَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا هَذَا؟ قَالَ قَسَمْتُه لَكَ، قَالَ: مَا عَلَى هَذَا اتَّبَعْتُكَ، وَلَكِنِّي اتَّبَعْتُك عَلَى أَنْ أُرْمى إِلَى ههنا. وَأَشَارَ إِلَى حَلْقه بِسَهْمٍ فأمُوتَ فأدخلَ الجنَّة، فَقَالَ: إِنْ تَصْدُق اللَّهَ يَصْدُقْكَ فَلَبِثُوا قَلِيلًا، ثُمَّ نَهَضوا فِي قِتَالِ العدُوِّ فأُتِيَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحْمَلُ وَقَدْ أَصَابَهُ سهْمٌ حَيْثُ أَشَارَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَهُو هُوَ؟ قَالُوا: نَعَمْ، قَالَ: صَدَقَ اللَّهُ فَصَدَقَهُ ، ثُمَّ كفَّنه النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جُبَّةِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قدَّمه فصَلَّى عَلَيْهِ، فَكَانَ فِيمَا ظَهَرَ مِنْ صَلَاتِهِ: اللَّهُمَّ هَذَا عَبْدُك خَرَجَ مُهَاجِرًا فِي سَبِيلِكَ فقُتِلَ شَهِيدًا أنا شَهِيدٌ عَلَى ذَلِكَ ."],"takhrij":"صحيح: رواه النسائي (1953) من طريق ابن جريج قال: أخبرني عكرمة بن خالد، أن ابن أبي عمار أخبره، عن شداد بن الهاد فذكره.","grade":"صحيح","chapter_ar":"باب من قال: يُصلَّى على الشهيد في سبيل الله","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Nasā’ī (1953), al-Ḥākim (6527).","chapter_en":"Those who held that the martyr in the path of Allah is prayed over","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في غسل الشهداء والصلاة عليهم ودفنهم","group_en":"Compilation of chapters on washing martyrs, praying over them, and burying them","part_no":13,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["Shaddād ibn al-Hād reported that a Bedouin man came to the Prophet ﷺ, believed in him, and followed him. Then he said: “I will migrate with you.” So the Prophet ﷺ entrusted him to some of his companions. Then during one of the campaigns, the Prophet ﷺ acquired captives and distributed them, and he allotted a share for that man too, though the man had been tending their riding animals. When he came back, they handed it to him. He said: “What is this?” They said: “A share the Prophet ﷺ assigned to you.” So he took it and brought it to the Prophet ﷺ and said: “What is this?” He said: “I assigned it to you.” He said: “This is not why I followed you. Rather, I followed you so that I would be struck right here” — and he pointed to his throat — “by an arrow, so I would die and enter Paradise.” So he said: “If you are truthful with Allah, He will be truthful with you.” They stayed a little while, then rose to fight the enemy. Then the man was brought to the Prophet ﷺ being carried, and he had been struck by an arrow exactly where he had pointed. The Prophet ﷺ said: “Is it him?” They said: “Yes.” He said: “He was truthful with Allah, so Allah fulfilled it for him.” Then the Prophet ﷺ shrouded him in one of his cloaks, then placed him forward and prayed over him. Part of what was heard from his prayer was: “O Allah, this is Your servant. He went out as a migrant in Your path and was killed as a martyr, and I am a witness to that.”"]},"buhuth":{"en":["The phrase “during a campaign in which the Prophet ﷺ acquired captives” — and in another wording, “something” — refers either to the expedition of Khaybar or Ḥunayn."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1953)، والحاكم (6527)."},{"num":3761,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: كُنَّا حَمَلْنَا الْقَتْلَى يَوْمَ أُحُدٍ لِنَدْفِنَهُمْ، فَجَاءَ مُنَادِي النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكُمْ أَنْ تَدْفِنُوا الْقَتْلَى فِي مَضَاجِعِهِمْ فَرَدَدْنَاهُمْ."],"takhrij":"حسن: رواه أبو داود (3165)، والترمذي (1717)، والنسائي (2005)، وابن ماجه (1516) كلهم من حديث الأسود بن قيس، سمع نُبيحاً العنـزي يقول: سمعت جابر بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الشهداء يُدفنون في مصارعهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3165), al-Tirmidhī (1717), al-Nasā’ī (2005), Ibn Mājah (1516).","chapter_en":"What is reported that martyrs are buried where they fell","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في غسل الشهداء والصلاة عليهم ودفنهم","group_en":"Compilation of chapters on washing martyrs, praying over them, and burying them","part_no":13,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: We had carried the slain on the day of Uḥud in order to bury them, then the caller of the Prophet ﷺ came and said: “The Messenger of Allah ﷺ commands you to bury the slain where they fell.” So we took them back."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3165)، والترمذي (1717)، والنسائي (2005)، وابن ماجه (1516)."},{"num":3762,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: لَمَّا كَانَ يَوْمُ أُحُدٍ نَادَى مُنَادِي رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنْ رُدُّوا الْقَتْلَى إِلَى مَضَاجِعِهِمْ."],"takhrij":"حسن: رواه البزار كشف الأستار (841) عن محمد بن عبد الرحيم صاعقة، ثنا مصعب بن عبدالله، ثنا عبد العزيز بن محمد، عن كثير بن زيد، عن رُبيح بن عبدالرحمن بن أبي سعيد، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الشهداء يُدفنون في مصارعهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Bazzār in Kashf al-Astār (841).","chapter_en":"What is reported that martyrs are buried where they fell","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في غسل الشهداء والصلاة عليهم ودفنهم","group_en":"Compilation of chapters on washing martyrs, praying over them, and burying them","part_no":13,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said: “On the day of Uḥud, the caller of the Messenger of Allah ﷺ called out: ‘Return the slain to the places where they fell.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (841)."},{"num":3763,"demo":false,"sanad":"","matn":["عَنْ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: لَمَّا تُوُفِّيَ إِبْرَاهِيمُ عَلَيْهِ السَّلاَمُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ لَهُ مُرْضِعًا فِي الْجَنَّةِ ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1382) عن أبي الوليد، حدثنا شعبة، عن عدي بن ثابت، أنه سمع البراء قال فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في أولاد المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1382).","chapter_en":"What is reported concerning the children of Muslims","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في أولاد المسلمين والمشركين","group_en":"Compilation of chapters on the children of Muslims and polytheists","part_no":13,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Al-Barā’ ibn ʿĀzib said: When Ibrāhīm passed away, the Messenger of Allah ﷺ said: “He has a wet nurse in Paradise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1382)."},{"num":3764,"demo":false,"sanad":"","matn":["عَنِ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ، فَأَبَوَاهُ يُهَوِّدَانِهِ أَوْ يُنَصِّرَانِهِ، كَمَا تُنَاتَجُ الإِبِلُ مِنْ بَهِيمَةٍ جَمْعَاءَ، هَلْ تُحِسُّ فِيهَا مِنْ جَدْعَاءَ. قَالُوا: يَا رَسُولَ اللَّهِ! أَرَأَيْتَ الَّذِي يَمُوتُ وَهُوَ صَغِيرٌ؟ قَالَ: اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ.","وفي رواية: من يُولد يُولد على هذه الفطرةِ، فأبواه يهودانه ويُنصرانه كما تَنْتِجون الإبلَ، فهل تجدون فيها جَدْعاء؟ حتى تكونوا أنتم تجدعونها .","وفي رواية أخرى: كُلُّ إِنْسَانٍ تَلِدُهُ أُمُّهُ عَلَى الْفِطْرَةِ، وَأَبَوَاهُ بَعْدُ يُهَوِّدَانِهِ، وَيُنَصِّرَانِهِ وَيُمَجِّسَانِهِ، فَإِنْ كَانَا مُسْلِمَيْنِ فَمُسْلِمٌ، كُلُّ إِنْسَانٍ تَلِدُهُ أُمُّهُ يَلْكُزُهُ الشَّيْطَانُ فِي حِضْنَيْهِ، إِلَّا مَرْيَمَ وَابْنَهَا .."],"takhrij":"متفق عليه: رواه مالك في الجنائز (52) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه الشيخان – البخاري في الجنائز (1359)، ومسلم في القدر (2658) كلاهما من حديث الزهري، قال: أخبرني أبو سلمة بن عبد الرحمن، أن أبا هريرة قال فذكر الحديث. وفيه ثم يقول أبو هريرة: فِطْرَتَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ اللَّهِ ذَلِكَ الدِّينُ الْقَيِّمُ [سورة الروم: 30].","grade":"متفق عليه","chapter_ar":"باب ما جاء في أولاد المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: Mālik (52), al-Bukhārī (1359), Muslim (2658). The second and third narrations are in Muslim.","chapter_en":"What is reported concerning the children of Muslims","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في أولاد المسلمين والمشركين","group_en":"Compilation of chapters on the children of Muslims and polytheists","part_no":13,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “Every newborn is born upon the natural disposition, then his parents make him a Jew or a Christian, just as camels are born whole and sound. Do you find any of them born mutilated?” They said: “O Messenger of Allah ﷺ, what about one who dies while still small?” He said: “Allah knows best what they would have done.” In another narration: “Whoever is born is born upon this natural disposition, then his parents make him a Jew or a Christian, just as you produce camels. Do you find among them any mutilated one, until you are the ones who mutilate them?”","In another narration: “Every human being is born by his mother upon the natural disposition. Then afterward his parents make him a Jew, a Christian, or a Magian. If the parents are Muslims, then he is Muslim. Every human being whom his mother bears is touched by Satan at his sides, except Mary and her son.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (52)، والبخاري (1359)، ومسلم (2658)، والرواية الثانية والثالثة عند مسلم."},{"num":3765,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: تُوُفِّيَ صَبِيٌّ، فَقُلْتُ: طُوبَى لَهُ، عُصْفُورٌ مِنْ عَصَافِيرِ الْجَنَّةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَوَ لا تَدْرِي أَنَّ اللَّهَ خَلَقَ الْجَنَّةَ، وَخَلَقَ النَّارَ، فَخَلَقَ لِهَذِهِ أهْلاً، وَلِهَذِهِ أَهْلًا .","وفي رواية: دُعِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى جِنَازَةِ صَبِيٍّ مِنَ الْأَنْصَارِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ! طُوبَى لِهَذَا، عُصْفُورٌ مِنْ عَصَافِيرِ الْجَنَّةِ، لَمْ يَعْمَلِ السؤ وَلَمْ يُدْرِكْهُ، قَالَ: أَوَ غَيْرُ ذَلِكِ يَا عَائِشَةُ إِنَّ اللَّهَ خَلَقَ لِلْجَنَّةِ أَهْلًا، خَلَقَهُمْ لَهَا وَهُمْ فِي أَصْلَابِ آبَائِهِمْ، وَخَلَقَ لِلنَّارِ أَهْلًا، خَلَقَهُمْ لَهَا وهم فِي أصلاب آبَائِهِم .."],"takhrij":"صحيح: رواه مسلم في القدر (2662) عن زهير بن حرب، حدثنا جرير، عن العلاء بن المسيب، عن فُضيل بن عمرو، عن عائشة بنت طلحة، عن عائشة أم المؤمنين فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في أولاد المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (2662), and the second narration is also in Muslim.","chapter_en":"What is reported concerning the children of Muslims","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في أولاد المسلمين والمشركين","group_en":"Compilation of chapters on the children of Muslims and polytheists","part_no":13,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["ʿĀ’ishah said: A young boy died, and I said: “Glad tidings for him, a little bird from the birds of Paradise.” The Messenger of Allah ﷺ said: “Do you not know that Allah created Paradise and created the Fire, and He created for this one a people, and for that one a people?” In another narration: The Messenger of Allah ﷺ was called to the funeral of a boy from the Anṣār, and I said: “O Messenger of Allah ﷺ, glad tidings for this one, a little bird from the birds of Paradise. He did not do evil and did not live long enough to reach it.”","He said: “Or perhaps otherwise, O ʿĀ’ishah. Allah created people for Paradise and created them for it while they were still in the loins of their fathers, and He created people for the Fire and created them for it while they were still in the loins of their fathers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2662)، والرواية الثانية عند مسلم."},{"num":3766,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الرَّاكِبُ يَسِيرُ خَلْفَ الْجَنَازَةِ، وَالْمَاشِي يَمْشِي خلْفَها وَأَمَامَهَا، وَعَنْ يَمِينِهَا وَعَنْ يَسَارِهَا قَرِيبًا مِنْهَا، والسِقْطُ يُصَلَّى عَلَيْهِ، ويُدعَى لِوَالِدَيْهِ بِالْمَغْفِرَةِ وَالرَّحْمَةِ ."],"takhrij":"صحيح: رواه أبو داود (3180)، والترمذي (1031)، وابن ماجه (1481، 1507)، والنسائي (1943) كلهم من طرق عن زياد بن جبير بن حية، عن أبيه، عن المغيرة بن شعبة فذكره، واللفظ لأبي داود، ولفظ غيره: الطفلُ يصلى عليه .","grade":"صحيح","chapter_ar":"باب الصلاة على أطفال المسلمين وسِقطهم","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3180), al-Tirmidhī (1031), Ibn Mājah (1481, 1507), al-Nasā’ī (1943).","chapter_en":"Praying over the children of Muslims and their miscarried infants","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في أولاد المسلمين والمشركين","group_en":"Compilation of chapters on the children of Muslims and polytheists","part_no":13,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah reported that the Prophet ﷺ said: “The rider travels behind the funeral, while the walker may walk behind it, in front of it, to its right, and to its left, staying near it. And the miscarried child is prayed over, and supplication is made for its parents for forgiveness and mercy.”"]},"buhuth":{"en":["A miscarried child is one that falls from its mother’s womb before full term. If it completed four months, then the funeral prayer is offered over it because the soul has been breathed into it by then. What is before that is not prayed over, because it is not regarded as a deceased person; rather, it is only a clot or a lump of flesh."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3680],"tks":"صحيح: رواه أبو داود (3180)، والترمذي (1031)، وابن ماجه (1481، 1507)، والنسائي (1943)."},{"num":3767,"demo":false,"sanad":"","matn":["عَنْ إِسْمَاعِيلَ السُّدِّيِّ قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ، قُلْتُ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى ابْنِهِ إِبْرَاهِيمَ؟ قَالَ: لَا أَدْرِي، رَحْمَةُ اللَّهِ عَلَى إِبْرَاهِيمَ، لَوْ عَاشَ كَانَ صِدِّيقًا نَبِيًّا، قَالَ: قُلْتُ: كَيْفَ أَنْصَرِفُ إِذَا صَلَّيْتُ، عَنْ يَمِينِي، أَوْ عَنْ يَسَارِي؟ قَالَ: أَمَّا أَنَا فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْصَرِفُ عَنْ يَمِينِهِ."],"takhrij":"حسن: رواه أحمد (13985)عن عفان، حدثنا أبو عوانة، عن إسماعيل السدي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صلاة النبي ﷺ على ولده إبراهيم عليه السلام","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (13985).","chapter_en":"What is reported about the Prophet’s prayer over his son Ibrāhīm","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في أولاد المسلمين والمشركين","group_en":"Compilation of chapters on the children of Muslims and polytheists","part_no":13,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Ismāʿīl al-Suddī said: I asked Anas ibn Mālik, “Did the Messenger of Allah ﷺ pray over his son Ibrāhīm?” He said: “I do not know. May Allah have mercy on Ibrāhīm. If he had lived, he would have been a truthful one and a prophet.” He said: I asked: “How should I turn away after praying, to my right or to my left?” He said: “As for me, I saw the Messenger of Allah ﷺ turn away to his right.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (13985)."},{"num":3768,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمْ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَوْلاَدِ الْمُشْرِكِينَ فَقَالَ: اللَّهُ إِذْ خَلَقَهُمْ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1383)، ومسلم في القدر (2660) كلاهما من طريق أبي بشر، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما قيل في أولاد المشركين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1383), Muslim (2660).","chapter_en":"What has been said regarding the children of polytheists","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في أولاد المسلمين والمشركين","group_en":"Compilation of chapters on the children of Muslims and polytheists","part_no":13,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbās said: The Messenger of Allah ﷺ was asked about the children of the polytheists, and he said: “When Allah created them, He knew best what they would have done.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1383)، ومسلم (2660)."},{"num":3769,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ يَقُولُ: سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَراري الْمُشْرِكِينَ فَقَالَ: اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1384)، ومسلم في القدر (2659) كلاهما عن أبي اليمان، أخبرنا شُعيب، عن ابن شهاب الزهري قال: أخبرني عطاء ابن يزيد الليثي، أنه سمع أبا هريرة فذكر الحديث. ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ما قيل في أولاد المشركين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1384), Muslim (2659).","chapter_en":"What has been said regarding the children of polytheists","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في أولاد المسلمين والمشركين","group_en":"Compilation of chapters on the children of Muslims and polytheists","part_no":13,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah said: The Prophet ﷺ was asked about the children of the polytheists, and he said: “Allah knows best what they would have done.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1384)، ومسلم (2659)."},{"num":3770,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ غُلاَمٌ يَهُودِيٌّ يَخْدُمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَرِضَ، فَأَتَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُهُ، فَقَعَدَ عِنْدَ رَأْسِهِ فَقَالَ لَهُ: أَسْلِمْ. فَنَظَرَ إِلَى أَبِيهِ وَهْوَ عِنْدَهُ فَقَالَ لَهُ: أَطِعْ أَبَا الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَسْلَمَ، فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ يَقُولُ: الْحَمْدُ لِلَّهِ الَّذِي أَنْقَذَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1356) عن سليمان بن حرب، حدثنا حماد (وهو ابن زيد) عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب عرض الإسلام على الصبي عند الموت","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1356).","chapter_en":"Presenting Islam to a child at the time of death","part_en":"The Book of Funerals","group_ar":"جموع أبواب ما جاء في أولاد المسلمين والمشركين","group_en":"Compilation of chapters on the children of Muslims and polytheists","part_no":13,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Anas said: A Jewish boy used to serve the Prophet ﷺ. He became ill, so the Prophet ﷺ came to visit him and sat by his head and said to him: “Accept Islam.” The boy looked at his father, who was with him, and his father said to him: “Obey Abū al-Qāsim.” So he accepted Islam. Then the Prophet ﷺ came out saying: “Praise be to Allah who saved him from the Fire.”"]}},"tuhfa":{},"full":1,"rep":[8155],"tks":"صحيح: رواه البخاري (1356)."},{"num":3771,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُرْسِلَ مَلَكُ الْمَوْتِ إِلَى مُوسَى ـ عَلَيْهِمَا السَّلاَمُ، ـ فَلَمَّا جَاءَهُ صَكَّهُ، فَرَجَعَ إِلَى رَبِّهِ فَقَالَ: أَرْسَلْتَنِي إِلَى عَبْدٍ لاَ يُرِيدُ الْمَوْتَ. فَرَدَّ اللَّهُ عَلَيْهِ عَيْنَهُ، وَقَالَ: ارْجِعْ فَقُلْ لَهُ يَضَعُ يَدَهُ عَلَى مَتْنِ ثَوْرٍ، فَلَهُ بِكُلِّ مَا غَطَّتْ بِهِ يَدُهُ بِكُلِّ شَعْرَةٍ سَنَةٌ. قَالَ: أَىْ رَبِّ، ثُمَّ مَاذَا؟ قَالَ: ثُمَّ الْمَوْتُ. قَالَ: فَالآنَ. فَسَأَلَ اللَّهَ أَنْ يُدْنِيَهُ مِنَ الأَرْضِ الْمُقَدَّسَةِ رَمْيَةً بِحَجَرٍ. قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَلَوْ كُنْتُ ثَمَّ، لأَرَيْتُكُمْ قَبْرَهُ إِلَى جَانِبِ الطَّرِيقِ عِنْدَ الْكَثِيبِ الأَحْمَرِ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1339)، ومسلم في الفضائل (2373) كلاهما من حديث عبد الرزاق، أخبرنا معمر، عن ابن طاوس، عن أبيه، عن أبي هريرة فذكره. ولم يذكرا فيه الرفعَ إلى النبي صلى الله عليه وسلم ولكن ساقه البخاري في أحاديث الأنبياء من هذا الوجه ثم قال: وعن معمر، عن همام بن منبه، عن أبي هريرة، عن النبي صلى الله عليه وسلم، وكذلك ساقه مسلم.","grade":"متفق عليه","chapter_ar":"باب من أحب أن يُدفن في الأرض المقدسة أو نحوها","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1339), Muslim (2373).","chapter_en":"One who wished to be buried in the holy land or near it","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah said: The Angel of Death was sent to Mūsā, peace be upon him. When he came to him, Mūsā struck him, so he returned to his Lord and said: “You sent me to a servant who does not want death.” So Allah restored his eye and said: “Go back and tell him to place his hand on the back of a bull, and for every hair covered by his hand he will have one year.” He said: “My Lord, then what?” He said: “Then death.” He said: “Then now.” So he asked Allah to bring him near the holy land by a stone’s throw. The Messenger of Allah ﷺ said: “If I were there, I would show you his grave beside the road at the red sand hill.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1339)، ومسلم (2373)."},{"num":3772,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ الجهني يَقُولُ:  ثَلَاثُ سَاعَاتٍ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَانَا أَنْ نُصَلِّيَ فِيهِنَّ، أَوْ أَنْ نَقْبُرَ فِيهِنَّ مَوْتَانَا: حِينَ تَطْلُعُ الشَّمْسُ بَازِغَةً حَتَّى تَرْتَفِعَ، وَحِينَ يَقُومُ قَائِمُ الظَّهِيرَةِ حَتَّى تَمِيلَ الشَّمْسُ، وَحِينَ تَضَيَّفُ الشَّمْسُ لِلْغُرُوبِ حَتَّى تَغْرُبَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (831) عن يحيى بن يحيى، حدثنا عبدالله بن وهب، عن موسى بن علي، عن أبيه، قال: سمعتُ عقبة بن عامر الجهني يقول: فذكره.","grade":"صحيح","chapter_ar":"باب في الأوقات التي تُكره فيها الصلاة على الجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (831).","chapter_en":"The times in which praying over the funeral is disliked","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir al-Juhanī said: “There were three times during which the Messenger of Allah ﷺ used to forbid us from praying or burying our dead: when the sun begins rising until it rises high, when the sun stands at midday until it declines, and when the sun inclines toward setting until it fully sets.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2485],"tks":"صحيح: رواه مسلم (831)."},{"num":3773,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: صَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ بَعْدَ مَا دُفِنَ بِلَيْلَةٍ، قَامَ هُوَ وَأَصْحَابُهُ، وَكَانَ سَأَلَ عَنْهُ فَقَالَ: مَنْ هَذَا. فَقَالُوا: فُلاَنٌ، دُفِنَ الْبَارِحَةَ. فَصَلَّوْا عَلَيْهِ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1340) عن عثمان بن أبي شيبة، حدثنا جرير، عن الشيباني، عن الشعبي، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب الدفن بالليل","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1340).","chapter_en":"Burial at night","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās said: The Prophet ﷺ prayed over a man after he had been buried the night before. He and his companions stood, and he had asked about him, saying: “Who is this?” They said: “So-and-so, who was buried last night,” so they prayed over him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1340)."},{"num":3774,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عبدالله قَالَ: رَأَى نَاسٌ نَارًا فِي الْمَقْبَرَةِ، فَأَتَوْهَا، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْقَبْرِ، وَإِذَا يَقُولُ: نَاوِلُونِي صَاحِبَكُمْ فَإِذَا هُوَ الرَّجُلُ الَّذِي كَانَ يَرْفَعُ صَوْتَهُ بِالذِّكْرِ."],"takhrij":"حسن: رواه أبو داود (3164) عن محمد بن حاتم بن بزيغ، حدثنا أبو نعيم، عن محمد بن مسلم، عن عمرو بن دينار، أخبرني جابر بن عبدالله قال: فذكره.","grade":"حسن","chapter_ar":"باب الدفن بالليل","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3164), al-Ḥākim (1361).","chapter_en":"Burial at night","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: Some people saw a fire in the graveyard and went toward it, and there was the Messenger of Allah ﷺ in the grave, saying: “Hand me your companion.” And it was the man who used to raise his voice in remembrance."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3164)، والحاكم (1361)."},{"num":3775,"demo":false,"sanad":"","matn":["أَخْبَرَنِي أَبُو الزُّبَيْرِ، أَنَّهُ سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ يُحَدِّثُ  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ يَوْمًا، فَذَكَرَ رَجُلًا مِنْ أَصْحَابِهِ قُبِضَ، فَكُفِّنَ فِي كَفَنٍ غَيْرِ طَائِلٍ، وَقُبِرَ لَيْلًا، فَزَجَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْبَرَ الرَّجُلُ بِاللَّيْلِ حَتَّى يُصَلَّى عَلَيْهِ، إِلَّا أَنْ يُضْطَرَّ إِنْسَانٌ إِلَى ذَلِكَ، وَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا كَفَّنَ أَحَدُكُمْ أَخَاهُ فَلْيُحَسِّنْ كَفَنَهُ."],"takhrij":"صحيح: رواه مسلم في الجنائز (943) من طرق عن حجاج بن محمد قال: قال ابن جريج، أخبرني أبو الزبير، فذكره.","grade":"صحيح","chapter_ar":"باب في النهي عن الدفن بالليل، والمقصود منه كيلا تفوته الصلاة على الجنازة","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (943).","chapter_en":"The prohibition of burial at night, meaning so that the funeral prayer is not missed","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Abū al-Zubayr heard Jābir ibn ʿAbdullāh narrate that the Prophet ﷺ once delivered a sermon and mentioned a man from his companions who had died. He had been shrouded in a poor shroud and buried at night. So the Prophet ﷺ strongly discouraged that a person be buried at night until the funeral prayer had been offered over him, unless there was a necessity. And the Prophet ﷺ said: “When one of you shrouds his brother, let him do his shrouding well.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (943)."},{"num":3776,"demo":false,"sanad":"","matn":["عَنْ أَبِي إِسْحَاقَ، قَالَ: أَوْصَى الْحَارِثُ أَنْ يُصَلِّيَ، عَلَيْهِ عَبْدُ اللَّهِ بْنُ يَزِيدَ فَصَلَّى عَلَيْهِ، ثُمَّ أَدْخَلَهُ الْقَبْرَ مِنْ قِبَلِ رِجْلَىِ الْقَبْرِ. وَقَالَ: هَذَا مِنَ السُّنَّةِ."],"takhrij":"صحيح: رواه أبو داود (3211) عن عبيدالله بن معاذ، حدثنا أبي، حدثنا شعبة، عن أبي إسحاق قال: فذكره.","grade":"صحيح","chapter_ar":"باب من السنة أن يُدخل الميت من قِبَل رجلي القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3211), al-Bayhaqī (4/54).","chapter_en":"It is from the Sunnah that the deceased be entered from the side of the grave’s feet","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Abū Isḥāq said: Al-Ḥārith instructed that ʿAbdullāh ibn Yazīd should pray over him. So he prayed over him, then entered him into the grave from the side of the grave’s feet and said: “This is from the Sunnah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3211)، والبيهقي (7052)."},{"num":3777,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: شَهِدْنَا بِنْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ عَلَى الْقَبْرِ، فَرَأَيْتُ عَيْنَيْهِ تَدْمَعَانِ، فَقَالَ: هَلْ فِيكُمْ مِنْ أَحَدٍ لَمْ يُقَارِفِ اللَّيْلَةَ. فَقَالَ أَبُو طَلْحَةَ: أَنَا. قَالَ: فَانْزِلْ فِي قَبْرِهَا. فَنَزَلَ فِي قَبْرِهَا فَقَبَرَهَا.","قَالَ ابْنُ الْمُبَارَكِ، قَالَ فُلَيْحٌ: أُرَاهُ يَعْنِي الذَّنْبَ.","قال أبو عبدالله (البخاري) ﴿ لِيَقْتَرِفُوا ﴾ أي ليكتسبوا."],"takhrij":"صحيح: رواه البخاري في الجنائز (1342) عن محمد بن سِنان، حدثنا فليح بن سليمان، حدثنا هلال بن علي، عن أنس فذكره،","grade":"صحيح","chapter_ar":"باب ما جاء في تولي الرجال إنزال الميت في القبر ولو كانت امرأة أجنبية","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Bukhārī (1342).","chapter_en":"Men taking charge of lowering the deceased into the grave, even if the deceased is a non-related woman","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik said: We attended the burial of a daughter of the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ was sitting by the grave, and I saw his eyes shedding tears. Then he said: “Is there anyone among you who did not have relations tonight?” Abū Ṭalḥah said: “I did not.” He said: “Then go down into her grave.” So he went down into her grave and buried her."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1342)."},{"num":3778,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا وَضَعَ الْمَيِّتَ فِي الْقَبْرِ قَالَ: بِسْمِ اللَّهِ، وَعَلَى سُنَّةِ رَسُولِ اللَّهِ."],"takhrij":"صحيح: رواه أبو داود (3213)، والنسائي في الكبرى (10927) وصحَّحه ابن حبان (3110)، والحاكم (1354) كلهم من طريق همام بن يحيى، عن قتادة، عن أبي الصديق وهو الناجي، عن ابن عمر فذكره، واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب ماذا يُقال إذا أُدخل الميت في القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3213), al-Nasā’ī in al-Kubrā (10927), authenticated by Ibn Ḥibbān (3110).","chapter_en":"What is said when the deceased is placed into the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar reported that when the Prophet ﷺ placed the deceased in the grave, he would say: “In the name of Allah, and upon the way of the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3213)، والنسائي في الكبرى (10927)، وصححه ابن حبان (3110)."},{"num":3779,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَفَّانَ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا فَرَغَ مِنْ دَفْنِ الْمَيِّتِ، وَقَفَ عَلَيْهِ فَقَالَ: اسْتَغْفِرُوا لأَخِيكُمْ، وَسَلُوا لَهُ التَّثْبِيتَ، فَإِنَّهُ الْآنَ يُسْأَلُ."],"takhrij":"حسن: أخرجه أبو داود (3221) عن إبراهيم بن موسى الرازي، حدثنا هشام، عن عبدالله بن بَحير، عن هانئ مولى عثمان، عن عثمان بن عفان فذكره.","grade":"حسن","chapter_ar":"باب الاستغفار للميت عند القبر بعد دفنه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3221), al-Bayhaqī in Ithbāt ʿAdhāb al-Qabr (50).","chapter_en":"Seeking forgiveness for the deceased at the grave after burial","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":9,"content":{"translation":{"en":["ʿUthmān ibn ʿAffān said: When the Prophet ﷺ finished burying the deceased, he would stand over him and say: “Seek forgiveness for your brother, and ask firmness for him, for he is now being questioned.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11110],"tks":"حسن: أخرجه أبو داود (3221)، والبيهقي في إثبات عذاب القبر (50)."},{"num":3780,"demo":false,"sanad":"","matn":["عَنْ قَتَادَةَ قَالَ: ذَكَرَ لَنَا أَنَسُ بْنُ مَالِكٍ، عَنْ أَبِي طَلْحَةَ قَالَ:  لَمَّا كَانَ يَوْمُ بَدْرٍ، وَظَهَرَ عَلَيْهِمْ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِبِضْعَةٍ وَعِشْرِينَ رَجُلًا. وَفِي حَدِيثِ رَوْحٍ بِأَرْبَعَةٍ وَعِشْرِينَ رَجُلًا مِنْ صَنَادِيدِ قُرَيْشٍ، فَأُلْقُوا فِي طَوِيٍّ مِنْ أَطْوَاءِ بَدْرٍ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (3976)، ومسلم في كتاب الجنَّة (2875)، كلاهما من حديث روح بن عبادة، حدثنا سعيد بن أبي عروبة، عن قتادة، فذكره في سياق طويل وسيأتي في المغازي بطوله.","grade":"متفق عليه","chapter_ar":"باب دفن الكافر والمشرك في مقابرهم الخاصة، وأنهم لا يُدفنون في مقابر المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (3976), Muslim (2875). In another narration: They were dragged by their feet.","chapter_en":"Burying disbelievers and polytheists in their own graveyards, and that they are not buried in Muslim graveyards","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":10,"content":{"translation":{"en":["Abū Ṭalḥah said: On the day of Badr, when the Prophet of Allah ﷺ was given victory over them, he ordered that some twenty-odd men — and in another narration, twenty-four men — from the chiefs of Quraysh be thrown into one of the wells of Badr."]},"buhuth":{"en":["The phrase “into a well” refers to a well lined with stones or something similar. Its plural is aṭwā’."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3976)، ومسلم (2875). وفي رواية: فجروا بأرجلهم."},{"num":3781,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُرِينَا مَصَارِعَ أَهْلِ بَدْرٍ بِالْأَمْسِ، يَقُولُ: هَذَا مَصْرَعُ فُلَانٍ غَدًا إِنْ شَاءَ اللَّهُ. قَالَ: فَقَالَ عُمَرُ: فَوَالَّذِي بَعَثَهُ بِالْحَقِّ مَا أَخْطَئُوا الْحُدُودَ الَّتِي حَدَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَجُعِلُوا فِي بِئْرٍ بَعْضُهُمْ عَلَى بَعْضٍ."],"takhrij":"صحيح: رواه مسلم في الجنة (2873) عن إسحاق بن عمر بن سليط الهذلي، حدثنا سليمان بن المغيرة، عن ثابت، قال: قال أنس: كنت مع عمر بين مكة والمدينة، فتراءَيْنا الهلال، وكنت رجلاً حديد البصر فرأيتُه، وليس أحد يزعم أنه رآه غيري، قال: فجعلتُ أقولُ لعُمَر: أمَا تراه؟ فجعل لا يراه، قال: يقول عمر: سأراه وأنا مستلق على فراشي، ثم أنشأ يحدثنا عن أهل بدر فذكره.","grade":"صحيح","chapter_ar":"باب دفن الكافر والمشرك في مقابرهم الخاصة، وأنهم لا يُدفنون في مقابر المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (2873).","chapter_en":"Burying disbelievers and polytheists in their own graveyards, and that they are not buried in Muslim graveyards","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":10,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb said: The Messenger of Allah ﷺ used to show us the places where the people of Badr would fall the day before, saying: “This is where so-and-so will fall tomorrow, if Allah wills.” He said: By the One who sent him with the truth, they did not miss the exact places that the Messenger of Allah ﷺ had marked out. He said: Then they were placed in a well, one on top of another."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2873)."},{"num":3782,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْقَتْلَى أَنْ يُطْرَحُوا فِي الْقَلِيبِ، فَطُرِحُوا فيهِ، إلاَّ مَا كَانَ مِنْ أميَّة بْنِ خَلَفٍ، فإنَّهُ انْتفخَ فِي دِرعِه فَمَلَأَهَا، فَذَهَبُوا لِيُحَرِّكُوهُ، فَتَزَايَلَ (لحمه) فَأَقَرُّوهُ وَأَلْقَوْا عَلَيْهِ مَا غيَّبه مِنَ التُّرَابِ وَالْحِجَارَةِ...، الحديث بِطُولِهِ وسيأتي فِي مَوْضِعِهِ كاملاً."],"takhrij":"حسن: رواه الإمام أحمد (26361) عن يعقوب، قال: حدثنا أبي، عن ابن إسحاق، قال: حدثني يزيد بن رومان، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب دفن الكافر والمشرك في مقابرهم الخاصة، وأنهم لا يُدفنون في مقابر المسلمين","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Aḥmad (26361), authenticated by Ibn Ḥibbān (7088) and al-Ḥākim (3/224).","chapter_en":"Burying disbelievers and polytheists in their own graveyards, and that they are not buried in Muslim graveyards","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":10,"content":{"translation":{"en":["ʿĀ’ishah said: The Messenger of Allah ﷺ ordered that the slain be thrown into the well, so they were thrown into it, except for Umayyah ibn Khalaf, for he had swollen inside his armor until he filled it. They tried to move him, but his flesh began to come apart, so they left him where he was and threw over him enough dirt and stones to cover him. The rest of the long hadith will come later in its full place."]},"buhuth":{"en":["Al-qalīb means a well.","The phrase “his flesh came apart” means that his flesh separated."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (26361)، وصححه ابن حبان (7088)، والحاكم (3/224)."},{"num":3783,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، عَلَيْهِ السَّلاَمُ قَالَ: قُلْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ عَمَّكَ الشَّيْخَ الضَّالَّ قَدْ مَاتَ. قَالَ: اذْهَبْ فَوَارِ أَبَاكَ، ثُمَّ لاَ تُحْدِثَنَّ شَيْئًا حَتَّى تَأْتِيَنِي. فَذَهَبْتُ فَوَارَيْتُهُ وَجِئْتُهُ، فَأَمَرَنِي فَاغْتَسَلْتُ، وَدَعَا لِي."],"takhrij":"حسن: رواه أبو داود (3214)، والنسائي (2006)، وابن الجارود (550)، وأحمد (1093) كلّهم من حديث أبي إسحاق، عن ناجية بن كعب، عن علي بن أبي طالب فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في دفن المشرك","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3214), al-Nasā’ī (2006), Ibn al-Jārūd (550), Aḥmad (1093).","chapter_en":"What is reported about burying a polytheist","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":11,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib said: I said to the Prophet ﷺ: “Your elderly misguided uncle has died.” He said: “Go and bury your father, then do not do anything until you come back to me.” So I went and buried him, then came back to him. He instructed me, so I bathed, and he supplicated for me."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3214)، والنسائي (2006)، وابن الجارود (550)، وأحمد (1093)."},{"num":3784,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَسْرُ عَظْمِ الْمَيِّتِ كَكَسْرِهِ حَيًّا."],"takhrij":"صحيح: رواه أبو داود (3207)، وابن ماجه (1616) كلاهما من طريق عبد العزيز بن محمد الدراوردي، حدثنا سعد بن سعيد، عن عمرة بنت عبدالرحمن، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في احترام الميت والنهي عن كسر عظامه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3207), Ibn Mājah (1616), Aḥmad (24308), Ibn al-Jārūd (551).","chapter_en":"Respecting the dead and the prohibition of breaking their bones","part_en":"The Book of Funerals","group_ar":"جموع أبواب الدفن وتوابعه","group_en":"Compilation of chapters on burial and related matters","part_no":13,"group_no":10,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah reported that the Messenger of Allah ﷺ said: “Breaking the bone of the dead is like breaking it while he is alive.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3207)، وابن ماجه (1616)، وأحمد (24308)، وابن الجارود (551)."},{"num":3785,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ عَقْرَ فِي الإِسْلاَمِ.","قَالَ عَبْدُ الرَّزَّاقِ: كَانُوا يَعْقِرُونَ عِنْدَ الْقَبْرِ ببقرةٍ أَوْ شَاةً."],"takhrij":"صحيح: رواه أبو داود (3222) عن يحيى بن موسى البلْخِي، حدثنا عبد الرزاق، أخبرنا معمر، عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الذبح عند القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Abū Dāwūd (3222), ʿAbd al-Razzāq (6690).","chapter_en":"The dislike of slaughtering at the grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik said: The Messenger of Allah ﷺ said: “There is no ritual slaughter at graves in Islam.”","ʿAbd al-Razzāq said: They used to slaughter a cow or a sheep at the grave."]},"buhuth":{"en":["Regarding the phrase “There is no ʿaqr,” al-Sindī said: ʿAqr means striking the legs of a camel or sheep with a sword while it is standing. They used to slaughter camels at the graves of the dead, saying: “The person in this grave used to slaughter for guests, so we repay him in the same way.”","Al-Nawawī said in al-Majmūʿ (5/320): “As for slaughtering and ʿaqr at the grave, it is blameworthy because of this hadith of Anas.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3222)، وعبد الرزاق (6690)."},{"num":3786,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا اشْتَكَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَكَرَتْ بَعْضُ نِسَائِهِ كَنِيسَةً رَأَيْنَهَا بِأَرْضِ الْحَبَشَةِ، يُقَالُ لَهَا مَارِيَةُ، وَكَانَتْ أُمُّ سَلَمَةَ وَأُمُّ حَبِيبَةَ رَضِيَ اللَّهُ عَنْهُمَا أَتَتَا أَرْضَ الْحَبَشَةِ، فَذَكَرَتَا مِنْ حُسْنِهَا وَتَصَاوِيرَ فِيهَا، فَرَفَعَ رَأْسَهُ فَقَالَ: أُولَئِكَ إِذَا مَاتَ مِنْهُمُ الرَّجُلُ الصَّالِحُ بَنَوْا عَلَى قَبْرِهِ مَسْجِدًا، ثُمَّ صَوَّرُوا فِيهِ تِلْكَ الصُّورَةَ، أُولَئِكَ شِرَارُ الْخَلْقِ عِنْدَ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1341)، ومسلم في المساجد (528) كلاهما من حديث هشام، عن أبيه، عن عائشة فذكرته واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن بناء المسجد على القبر","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1341), Muslim (528), and this is the wording of al-Bukhārī.","chapter_en":"The prohibition of building a mosque over a grave","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah said: When the Prophet ﷺ fell ill, some of his wives mentioned a church they had seen in Abyssinia called Māriyah. Umm Salamah and Umm Ḥabībah had both gone to Abyssinia, and they described its beauty and the images inside it. He then raised his head and said: “Those people, when a righteous man among them died, would build a mosque over his grave, then place those images in it. Those are the worst of creation in the sight of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1341)، ومسلم (528)، واللفظ للبخاري."},{"num":3787,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُجَصَّصَ الْقَبْرُ، وَأَنْ يُقْعَدَ عَلَيْهِ، وَأَنْ يُبْنَى عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (970) من طرق عن ابن جريج، قال: أخبرني أبو الزبير، أنه سمع جابر بن عبدالله فذكر الحديث مثله.","grade":"صحيح","chapter_ar":"باب النهي عن تجصيص القبور والكتابة عليها","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (970).","chapter_en":"The prohibition of plastering graves and writing on them","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Jābir said: The Messenger of Allah ﷺ forbade plastering the grave, sitting on it, and building over it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3793],"tks":"صحيح: رواه مسلم (970)."},{"num":3788,"demo":false,"sanad":"","matn":["عن ثُمامة بن شٌفيٍّ حَدَّثَهُ قَالَ:  كُنَّا مَعَ فَضَالَةَ بْنِ عُبَيْدٍ بِأَرْضِ الرُّومِ بِرُودِسَ، فَتُوُفِّيَ صَاحِبٌ لَنَا، فَأَمَرَ فَضَالَةُ بْنُ عُبَيْدٍ بِقَبْرِهِ فَسُوِّيَ، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ بِتَسْوِيَتِهَا."],"takhrij":"صحيح: رواه مسلم في الجنائز (968) من طرق عن أبي علي الهمداني، حدَّثه، أن ثُمامة بن شُفِّي حدَّثه قال: فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بتسوية القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (968).","chapter_en":"The command to level graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":4,"content":{"translation":{"en":["Thumāmah ibn Shufayy said: We were with Faḍālah ibn ʿUbayd in the land of the Romans, at Rhodes, when one of our companions died. Faḍālah ibn ʿUbayd ordered that his grave be leveled, then said: “I heard the Messenger of Allah ﷺ command that graves be leveled.”"]},"buhuth":{"en":["Rhodes is a well-known island in the Mediterranean Sea, southwest of Turkey."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (968)."},{"num":3789,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْهَيَّاجِ الْأَسَدِيِّ قَالَ:  قَالَ لِي عَلِيُّ بْنُ أَبِي طَالِبٍ: أَلَا أَبْعَثُكَ عَلَى مَا بَعَثَنِي عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنْ لَا تَدَعَ تِمْثَالًا إِلَّا طَمَسْتَهُ، وَلَا قَبْرًا مُشْرِفًا إِلَّا سَوَّيْتَهُ.","وفي رواية: ولا صورةً إلا طمستها."],"takhrij":"صحيح: رواه مسلم في الجنائز (969) من طرق عن وكيع، عن سفيان، عن حبيب بن أبي ثابت، عن أبي وائل، عن أبي الهيَّاج فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بتسوية القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (969).","chapter_en":"The command to level graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":4,"content":{"translation":{"en":["Abū al-Hayyāj al-Asadī said: ʿAlī ibn Abī Ṭālib said to me: “Shall I not send you on the same mission the Messenger of Allah ﷺ sent me on: that you leave no statue without erasing it, and no raised grave without leveling it?” And in another narration: “and no image without erasing it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (969)."},{"num":3790,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ قَالَ: إِنَّ تَسْوِيَةَ القبور مِنَ السُّنَّةِ، وَقَدْ رَفَعَتِ الْيَهُودُ وَالنَّصَارَى فَلَا تَشَبَّهُوا بِهِمَا."],"takhrij":"صحيح: رواه الطبراني في الكبير (19/ح 823) عن الحسين بن إسحاق التستري، ثنا وهب بن بقية، أنا خالد بن عبدالله، عن عمران بن حدير، عن مجلز، أن معاوية قال: فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بتسوية القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: al-Ṭabarānī in al-Kabīr (19/352).","chapter_en":"The command to level graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":4,"content":{"translation":{"en":["Muʿāwiyah said: Leveling graves is from the Sunnah. The Jews and Christians raised them, so do not resemble them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (19/ح 823)."},{"num":3791,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَأَنْ يَجْلِسَ أَحَدُكُمْ عَلَى جَمْرَةٍ فَتُحْرِقَ ثِيَابَهُ، فَتَخْلُصَ إِلَى جِلْدِهِ، خَيْرٌ لَهُ مِنْ أَنْ يَجْلِسَ عَلَى قَبْرٍ."],"takhrij":"صحيح: رواه مسلم في الجنائز (971) من طرق عن سُهيل، عن أبيه، عن أبي هريرة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الجلوس على القبر ووطئه والصلاة إليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (971).","chapter_en":"The prohibition of sitting on a grave, stepping on it, and praying toward it","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah said: The Messenger of Allah ﷺ said: “For one of you to sit on a live coal that burns through his clothes and reaches his skin is better for him than sitting on a grave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (971)."},{"num":3792,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَرْثَدٍ الْغَنَوِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَا تَجْلِسُوا عَلَى الْقُبُورِ، وَلَا تُصَلُّوا إِلَيْهَا."],"takhrij":"صحيح: رواه مسلم في الجنائز (972) من طريق الوليد بن مسلم، عن ابن جابر (وهو عبدالرحمن بن يزيد بن جابر) عن بُسر بن عبيدالله، عن واثلة ابن الأسقع، عن أبي مرثد الغنوي فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الجلوس على القبر ووطئه والصلاة إليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (972).","chapter_en":"The prohibition of sitting on a grave, stepping on it, and praying toward it","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["Abū Marthad al-Ghanawī said: The Messenger of Allah ﷺ said: “Do not sit on graves, and do not pray toward them.”"]},"buhuth":{"en":["The phrase “do not pray toward them” means: do not take graves as a direction of prayer, because that leads to glorifying the one buried there, and then eventually to worshiping him. Many scholars clearly stated that praying toward a grave is forbidden because of the plain wording of this prohibition."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (972)."},{"num":3793,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُجَصَّصَ الْقَبْرُ، وَأَنْ يُقْعَدَ عَلَيْهِ، وَأَنْ يُبْنَى عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (970) من طرق عن ابن جريج، قال: أخبرني أبو الزبير، أنه سمع جابر بن عبدالله فذكر الحديث وسبق قبل أبواب.","grade":"صحيح","chapter_ar":"باب النهي عن الجلوس على القبر ووطئه والصلاة إليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Muslim (970).","chapter_en":"The prohibition of sitting on a grave, stepping on it, and praying toward it","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["Jābir said: The Messenger of Allah ﷺ forbade plastering the grave, sitting on it, and building over it."]}},"tuhfa":{},"full":1,"rep":[3787],"tks":"صحيح: رواه مسلم (970)."},{"num":3794,"demo":false,"sanad":"","matn":["عَنْ زَيْدَ بْنَ ثَابِتٍ قَالَ: هَلُمَّ يَا ابْنَ أَخِي أُخْبِرْكَ، إِنَّمَا نَهَى النَّبِيُّ صلى الله عليه وسلم عَنِ الْجُلُوسِ عَلَى الْقُبُورِ لِحَدَثِ غَائِطٍ أَوْ بَوْلٍ."],"takhrij":"حسن: رواه الطحاوي في شرح معاني الآثار (2877) عن سليمان بن شعيب، قال: ثنا الخصيب، قال: ثنا عمرو بن علي، قال: ثنا عثمان بن حكيم، عن أبي أمامة، أن زيد بن ثابت قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الجلوس على القبر ووطئه والصلاة إليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Ṭaḥāwī in Sharḥ Maʿānī al-Āthār (2877).","chapter_en":"The prohibition of sitting on a grave, stepping on it, and praying toward it","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["Zayd ibn Thābit said: Come here, my nephew, and I will tell you: the Prophet ﷺ only forbade sitting on graves for relieving oneself with feces or urine."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطحاوي في شرح معاني الآثار (2877)."},{"num":3795,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لأَنْ أَمْشِيَ عَلَى جَمْرَةٍ أَوْ سَيْفٍ، أَوْ أَخْصِفَ نَعْلِي بِرِجْلِي، أَحَبُّ إِلَىَّ مِنْ أَنْ أَمْشِيَ عَلَى قَبْرِ مُسْلِمٍ، وَمَا أُبَالِي أَوَسَطَ الْقُبُورِ قَضَيْتُ حَاجَتِي، أَوْ وَسَطَ السُّوقِ."],"takhrij":"صحيح: رواه ابن ماجه (1567) عن محمد بن إسماعيل بن سمرة، قال: حدثنا المحاربي، عن الليث بن سعد، عن يزيد بن أبي حبيب، عن أبي الخير مرثد بن عبدالله اليزني، عن عقبة بن عامر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن الجلوس على القبر ووطئه والصلاة إليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Ibn Mājah (1567).","chapter_en":"The prohibition of sitting on a grave, stepping on it, and praying toward it","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir said: The Messenger of Allah ﷺ said: “For me to walk on a live coal, or a sword, or to patch my sandal with my foot, is more beloved to me than walking on the grave of a Muslim. And I do not care whether I relieve myself in the middle of graves or in the middle of the market.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1567)."},{"num":3796,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ حَزْمٍ، قَالَ: رَآنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُتَّكَأً عَلَى قَبْرٍ، فَقَالَ: لَا تُؤْذِ صَاحِبَ هَذَا الْقَبْرِ - أَوْ لَا تُؤْذِهِ."],"takhrij":"صحيح: رواه الإمام أحمد في مسنده (39/476 رقم 000/39- الأحاديث المستدركة من مسند الأنصار) عن علي بن عبد الله، حدثنا ابن وهب، أخبرني عمرو بن الحارث، عن بكر بن سوادة الجذامي، عن زياد بن نُعيم الحضرمي، عن عمرو بن حزم قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الجلوس على القبر ووطئه والصلاة إليه","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Authentic: Aḥmad (39/476), al-Ṭaḥāwī in Sharḥ Maʿānī al-Āthār (2944).","chapter_en":"The prohibition of sitting on a grave, stepping on it, and praying toward it","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["ʿAmr ibn Ḥazm said: The Messenger of Allah ﷺ saw me leaning on a grave, so he said: “Do not harm the occupant of this grave,” or, “Do not harm him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (24009)، والطحاوي في شرح معاني الآثار (2944)."},{"num":3797,"demo":false,"sanad":"","matn":["عَنْ بَشِيرِ بْنِ الخصاصية – وَكَانَ اسْمُهُ فِي الْجَاهِلِيَّةِ زَحْمُ بْنُ مَعْبَدٍ، فَهَاجَرَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ: مَا اسْمُكَ؟ قَالَ: زَحْمٌ، قَالَ: بَلْ أَنْتَ بَشِيرٌ – قَالَ: بَيْنَمَا أَنَا أَمْشِي مَعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مرَّ بِقُبُورِ الْمُشْرِكِينَ فَقَالَ: لَقَدْ سَبَقَ هَؤُلاَءِ خَيْرًا كَثِيرًا ثَلاَثًا، ثُمَّ مَرَّ بِقُبُورِ الْمُسْلِمِينَ فَقَالَ: لَقَدْ أَدْرَكَ هَؤُلاَءِ خَيْرًا كَثِيرًا وحــانت مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَظْرَةٌ فَإِذَا رَجُلٌ يَمْشِي فِي الْقُبُورِ عَلَيْهِ نَعْلاَنِ فَقَالَ: يَا صَاحِبَ السَّبْتِيَّتَينِ وَيْحَكَ ألْقِ سَبْتِيَّتَيك فَنَظَرَ الرَّجُلُ، فَلَمَّا عَرَفَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَلَعَهُمَا فَرَمَى بِهِمَا."],"takhrij":"حسن: رواه أبو داود (3230)، والنسائي (2048)، وابن ماجه (1568) كلهم من طريق الأسود بن شيبان، عن خالد بن سمير، عن بشير بن نُهيك، عن بشير بن الخصاصية فذكره ولفظهم قريب.","grade":"حسن","chapter_ar":"باب كراهية المشي في النعال بين القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: Abū Dāwūd (3230), al-Nasā’ī (2048), Ibn Mājah (1568).","chapter_en":"The dislike of walking in sandals among the graves","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":6,"content":{"translation":{"en":["Bashīr ibn al-Khaṣāṣiyyah — whose name in the pre-Islamic period had been Zaḥm ibn Maʿbad, then he migrated to the Messenger of Allah ﷺ, who said: “What is your name?” He said: “Zaḥm.” He said: “Rather, you are Bashīr.” He said: While I was walking with the Messenger of Allah ﷺ, he passed by the graves of the polytheists and said: “These people have missed much good,” three times. Then he passed by the graves of the Muslims and said: “These people have attained much good.” Then the Messenger of Allah ﷺ looked and saw a man walking among the graves while wearing sandals, so he said: “O wearer of the two leather sandals, woe to you, throw away your two sandals.” The man looked, and when he recognized the Messenger of Allah ﷺ, he took them off and threw them away."]},"buhuth":{"en":["The phrase “the two leather sandals” refers to sandals made from specially tanned cowhide. They were called that because the hair had been removed from the leather."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3230)، والنسائي (2048)، وابن ماجه (1568)."},{"num":3798,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْعَبْدَ إِذَا وُضِعَ فِي قَبْرِهِ، وَتَوَلَّى عَنْهُ أَصْحَابُهُ إنه يسمع قرعَ نِعَالِهِمْ ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1374)، ومسلم في كتاب الجنة (2870) كلاهما من حديث سعيد بن أبي عروبة، عن قتادة، عن أنس بن مالك في حديث طويل – انظر جموع إثبات عذاب القبر.","grade":"متفق عليه","chapter_ar":"باب من قال بجواز المشي بالنعال بين القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Agreed upon: al-Bukhārī (1374), Muslim (2870).","chapter_en":"Those who held that walking in sandals among graves is allowed","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Mālik reported that the Messenger of Allah ﷺ said: “When the servant is placed in his grave and his companions turn away from him, he hears the sound of their sandals.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1374)، ومسلم (2870)."},{"num":3799,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: إِنَّ الْمَيِّتَ يَسْمَعُ حِسَّ النِّعَالِ إِذَا وَلَّوْا عَنْهُ النَّاسُ مُدْبِرِينَ، ثُمَّ يُجْلَسُ وَيُوضَعُ كَفَنُهُ فِي عُنُقِهِ، ثُمَّ يُسْأَلُ ."],"takhrij":"حسن: رواه البغوي في شرح السنة (1521) بإسناده عن ابن عدي، نا عبدالله ابن سعيد، نا أسد بن موسى، نا عنبسة بن سعيد بن كثير، قال: حدثني جدي، عن أبي هريرة فذكره. قال الشيخ: كثير جد عنبسة: هو كثير بن عبيد رضيع عائشة مولى أبي بكر .","grade":"حسن","chapter_ar":"باب من قال بجواز المشي بالنعال بين القبور","chapter_ur":"","part_ar":"كتاب الجنائز","part_ur":"","takhrij_en":"Hasan: al-Baghawī in Sharḥ al-Sunnah (5/413).","chapter_en":"Those who held that walking in sandals among graves is allowed","part_en":"The Book of Funerals","group_ar":"جموع أبواب القبور","group_en":"Compilation of chapters on graves","part_no":13,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah reported from the Prophet ﷺ that he said: “The deceased hears the sound of sandals when the people turn away from him and leave. Then he is made to sit, his shroud is placed around his neck, and then he is questioned.”"]},"buhuth":{"en":["The prohibition is understood to apply to stepping on graves and walking directly over them. Walking with sandals is allowed if one walks among the graves without stepping on an actual grave."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البغوي في (( شرح السنة )) (5/413)."}]);